namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * Product variant line item moved within an inter-branch stock transfer.
 */
class StockTransferItem extends Model
{
    protected $fillable = [
        'stock_transfer_id', 'product_variant_id', 'from_location_id', 'to_location_id',
        'requested_qty', 'approved_qty', 'shipped_qty', 'received_qty',
    ];

    protected $casts = [
        'requested_qty' => 'decimal:4',
        'approved_qty' => 'decimal:4',
        'shipped_qty' => 'decimal:4',
        'received_qty' => 'decimal:4',
    ];

    public function transfer(): BelongsTo
    {
        return $this->belongsTo(StockTransfer::class, 'stock_transfer_id');
    }

    public function variant(): BelongsTo
    {
        return $this->belongsTo(ProductVariant::class, 'product_variant_id')->withTrashed();
    }

    public function fromLocation(): BelongsTo
    {
        return $this->belongsTo(Location::class, 'from_location_id');
    }

    public function toLocation(): BelongsTo
    {
        return $this->belongsTo(Location::class, 'to_location_id');
    }
}<?php

declare(strict_types=1);

namespace App\Support;

/**
 * Normalizes Eastern Arabic (Arabic-Indic) and Persian numerals to Western digits.
 */
final class ArabicDigits
{
    /** @var array<string, string> Contiguous transliteration map for Arabic-Indic (٠-٩) and Persian (۰-۹) digits. */
    public const MAP = [
        '٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',
        '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',
        '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',
        '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',
    ];

    /**
     * Transliterates Arabic-Indic and Persian numerals into standard ASCII digits.
     *
     * @param  string  $value  Input text potentially containing Eastern Arabic or Persian numerals.
     * @return string Normalized text with Western ASCII digits (0-9).
     */
    public static function normalize(string $value): string
    {
        return strtr($value, self::MAP);
    }
}import { useEffect, useRef, useState } from 'react';
import { defaultApiClient } from '@alfarid/api-client';

interface Recognition {
  lang: string;
  onresult: ((event: { results: { transcript: string }[][] }) => void) | null;
  onerror: (() => void) | null;
  onend: (() => void) | null;
  start(): void;
  abort(): void;
}
type SpeechWindow = Window & { SpeechRecognition?: new () => Recognition; webkitSpeechRecognition?: new () => Recognition };

function scanId(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  bytes[6] = (bytes[6] & 15) | 64;
  bytes[8] = (bytes[8] & 63) | 128;
  const hex = Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

export default function StocktakeVoiceCount() {
  const [session, setSession] = useState('');
  const [barcode, setBarcode] = useState('');
  const [words, setWords] = useState('');
  const [busy, setBusy] = useState(false);
  const [listening, setListening] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const request = useRef<{ payload: string; id: string } | null>(null);
  const submitting = useRef(false);
  const recognition = useRef<Recognition | null>(null);
  const barcodeInput = useRef<HTMLInputElement>(null);
  const Speech = (window as SpeechWindow).SpeechRecognition ?? (window as SpeechWindow).webkitSpeechRecognition;
  useEffect(() => () => { recognition.current?.abort(); }, []);

  const listen = () => {
    if (!Speech || busy || listening) return;
    setError('');
    const listener = new Speech;
    recognition.current = listener;
    listener.lang = 'ar-EG';
    listener.onresult = event => setWords(event.results[0]?.[0]?.transcript ?? '');
    listener.onerror = () => setError('تعذّر سماع العدد؛ جرّب تاني أو اكتبه.');
    listener.onend = () => setListening(false);
    try { setListening(true); listener.start(); }
    catch { setListening(false); setError('تعذّر تشغيل الميكروفون؛ اكتب العدد.'); }
  };

  return <section dir="rtl" aria-label="عد الجرد بالصوت" style={{ maxWidth: 600, margin: '24px auto', padding: 24, border: '1px solid #d4d4d8', borderRadius: 12, display: 'grid', gap: 16 }}>
    <h2>عد الجرد بالصوت</h2>
    <p>امسح الباركود، وقول العدد أو اكتبه. راجع العدد قبل تسجيل المسحة.</p>
    <form style={{ display: 'grid', gap: 16 }} onSubmit={async event => {
      event.preventDefault();
      if (submitting.current || listening) return;
      submitting.current = true; setBusy(true); setError(''); setMessage('');
      try {
        const normalized = session.replace(/[٠-٩۰-۹]/g, digit => String('٠١٢٣٤٥٦٧٨٩'.includes(digit) ? '٠١٢٣٤٥٦٧٨٩'.indexOf(digit) : '۰۱۲۳۴۵۶۷۸۹'.indexOf(digit)));
        if (!/^[1-9]\d*$/.test(normalized)) throw new Error('اكتب معرّف جلسة الجرد كرقم صحيح.');
        const payload = JSON.stringify({ session: normalized, barcode: barcode.trim(), words: words.trim() });
        if (!request.current || request.current.payload !== payload) request.current = { payload, id: scanId() };
        const response = await defaultApiClient.post<{ sku: string; counted_qty: string | number }>(`/api/v1/pos/stocktakes/${normalized}/scan`, { barcode: barcode.trim(), qty_words: words.trim(), scan_id: request.current.id });
        setMessage(`اتسجل ${response.data.sku} — إجمالي العد: ${response.data.counted_qty}`);
        request.current = null; setBarcode(''); setWords(''); barcodeInput.current?.focus();
      } catch (failure) {
        const e = failure as { message?: string; response?: { data?: { message?: string } } };
        setError(e.response?.data?.message ?? e.message ?? 'تعذّر التسجيل؛ أعد المحاولة بنفس البيانات.');
      } finally { submitting.current = false; setBusy(false); }
    }}>
      <label>معرّف جلسة الجرد<input aria-label="معرّف جلسة الجرد" value={session} onChange={e => setSession(e.target.value)} required inputMode="numeric" disabled={busy || listening} /></label>
      <label>الباركود<input ref={barcodeInput} aria-label="باركود الجرد" value={barcode} onChange={e => setBarcode(e.target.value)} required maxLength={100} disabled={busy || listening} /></label>
      <label>العدد<input aria-label="العدد المنطوق" value={words} onChange={e => setWords(e.target.value)} required maxLength={50} placeholder="اتنين وعشرين أو ٢٢" disabled={busy || listening} /></label>
      {Speech ? <button type="button" onClick={listen} disabled={busy || listening || !barcode.trim()}>{listening ? 'بسمع العدد…' : 'قول العدد'}</button> : <p>الإملاء الصوتي غير متاح في المتصفح ده؛ اكتب العدد.</p>}
      <button type="submit" disabled={busy || listening || !session || !barcode.trim() || !words.trim()}>{busy ? 'جارٍ التسجيل…' : 'تسجيل المسحة'}</button>
    </form>
    {message && <p role="status">{message}</p>}
    {error && <p role="alert">{error}</p>}
  </section>;
}import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom';
import { Icon } from '../ui/Icons';
import { egp, fmt, PImg, Api, Kbd, MoneyInput, Field, cx, useEsc } from '../ui/SharedUI';
import { ReceiptDone } from './ReceiptDone';
import { posMockService } from '../../services/pos-mock.service';
import type { PosCartLine, Customer, Branch, CashierUser } from '../../types/pos.types';

interface CheckoutModalProps {
  open: boolean;
  onClose: () => void;
  cart: PosCartLine[];
  customer: Customer | null;
  discount: number;
  onPaid: () => void;
  branch?: Branch | null;
  cashier?: CashierUser | null;
}

const uuid = () =>
  'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  });

export function CheckoutModal({
  open,
  onClose,
  cart,
  customer,
  discount,
  onPaid,
  branch,
  cashier,
}: CheckoutModalProps) {
  const [method, setMethod] = useState<'cash' | 'card' | 'mixed'>('cash');
  const [received, setReceived] = useState<string>('');
  const [cashPart, setCashPart] = useState<string>('');
  const [notes, setNotes] = useState<string>('');
  const [stage, setStage] = useState<'pay' | 'sending' | 'done'>('pay');
  const [idem, setIdem] = useState<string>('');
  const [invoiceNumber, setInvoiceNumber] = useState<string>('');

  const subtotal = cart.reduce((s, l) => s + l.price * l.qty, 0);
  const total = Math.max(0, subtotal - discount);

  useEffect(() => {
    if (open) {
      setMethod('cash');
      setReceived('');
      setCashPart('');
      setNotes('');
      setStage('pay');
      setIdem(uuid());
      setInvoiceNumber('');
    }
  }, [open]);

  useEffect(() => {
    if (!open || stage !== 'pay') return;
    const h = (e: KeyboardEvent) => {
      if ((e.target as HTMLElement).tagName === 'TEXTAREA' || (e.target as HTMLElement).tagName === 'INPUT') return;
      if (e.key === 'F1') {
        e.preventDefault();
        setMethod('cash');
      }
      if (e.key === 'F3') {
        e.preventDefault();
        setMethod('card');
      }
      if (e.key === 'F4') {
        e.preventDefault();
        setMethod('mixed');
      }
    };
    window.addEventListener('keydown', h);
    return () => window.removeEventListener('keydown', h);
  }, [open, stage]);

  useEsc(() => stage !== 'sending' && onClose(), open);
  if (!open) return null;

  const rec = Number(received || 0);
  const change = rec - total;
  const cashA = Math.min(Number(cashPart || 0), total);
  const cardA = Math.max(0, total - cashA);

  const valid =
    method === 'card' ||
    (method === 'cash' && rec >= total) ||
    (method === 'mixed' && cashA > 0 && cardA > 0 && Math.abs(cashA + cardA - total) < 0.01);

  const roundUps = [
    ...new Set([
      total,
      Math.ceil(total / 50) * 50,
      Math.ceil(total / 100) * 100,
      Math.ceil(total / 200) * 200,
      Math.ceil(total / 500) * 500,
    ]),
  ]
    .filter((v) => v >= total)
    .slice(0, 4);

  const press = (k: string) => {
    const set = method === 'mixed' ? setCashPart : setReceived;
    const cur = method === 'mixed' ? cashPart : received;
    if (k === '⌫') set(cur.slice(0, -1));
    else if (k === '.') {
      if (!cur.includes('.')) set((cur || '0') + '.');
    } else set(cur + k);
  };

  const confirm = async () => {
    if (!valid || stage === 'sending') return;
    setStage('sending');
    try {
      const res = await posMockService.createSale({
        items: cart.map((l) => ({
          product_variant_id: l.id,
          qty: l.qty,
          unit_price: l.price,
          discount_amount: 0,
        })),
        customer_id: customer?.id ?? null,
        payment_method: method,
        cash_amount: method === 'cash' ? total : method === 'mixed' ? cashA : 0,
        card_amount: method === 'card' ? total : method === 'mixed' ? cardA : 0,
        notes,
      });
      setInvoiceNumber(res.invoiceNumber);
      setStage('done');
    } catch {
      setStage('pay');
    }
  };

  return ReactDOM.createPortal(
    <div
      dir="rtl"
      className={document.querySelector('.app')?.classList.contains('theme-dark') ? 'theme-dark' : ''}
    >
      <div className="overlay" onClick={() => stage === 'pay' && onClose()} />
      <div
        className="modal"
        style={{ width: 'min(960px, calc(100vw - 32px))' }}
        data-screen-label="05 Checkout"
        role="dialog"
        aria-modal="true"
      >
        <div className="pop">
          {stage !== 'done' ? (
            <div className="co">
              <div className="co-main">
                <div className="row between">
                  <h3 className="fs-16">الدفع وطرق التحصيل</h3>
                  <button className="icon-btn sm" onClick={onClose} aria-label="إغلاق">
                    <Icon n="x" s={16} />
                  </button>
                </div>
                <div className="due">
                  <div className="col gap-1">
                    <span className="fs-13 t-2">المطلوب سداده</span>
                    <span className="v">
                      {egp(total)}
                      <small>ج.م</small>
                    </span>
                  </div>
                  {customer && (
                    <span className="badge b-neutral">
                      <Icon n="users" s={13} />
                      {customer.name}
                    </span>
                  )}
                </div>
                <div className="methods" role="radiogroup">
                  {(
                    [
                      ['cash', 'نقدي', 'cash', 'F1'],
                      ['card', 'بطاقة / فيزا', 'card', 'F3'],
                      ['mixed', 'دفع مختلط', 'split', 'F4'],
                    ] as const
                  ).map(([v, l, ic, k]) => (
                    <button
                      key={v}
                      role="radio"
                      className="method"
                      aria-checked={method === v}
                      onClick={() => setMethod(v)}
                    >
                      <Kbd>{k}</Kbd>
                      <Icon n={ic} s={24} w={1.6} />
                      {l}
                    </button>
                  ))}
                </div>

                {method === 'cash' && (
                  <div className="grid" style={{ gridTemplateColumns: '1fr 220px', gap: 16 }}>
                    <div className="col gap-3">
                      <span className="fs-13 fw-5">المبلغ المستلم من العميل</span>
                      <MoneyInput
                        value={received}
                        onChange={setReceived}
                        autoFocus
                        placeholder={String(total)}
                        onEnter={confirm}
                      />
                      <div className="denoms">
                        {roundUps.map((v, i) => (
                          <button
                            key={v}
                            className="denom"
                            onClick={() => setReceived(String(v))}
                          >
                            {i === 0 && v === total ? (
                              <span className="fs-13" style={{ fontFamily: 'var(--f-body)' }}>
                                المبلغ بالضبط
                              </span>
                            ) : (
                              <>
                                {fmt(v)}
                                <small>ج</small>
                              </>
                            )}
                          </button>
                        ))}
                      </div>
                      <div className={cx('change', change < 0 && received && 'neg')}>
                        <span className="col">
                          <span className="fs-12" style={{ opacity: 0.75 }}>
                            {change < 0 && received
                              ? 'المبلغ غير كافٍ — متبقٍ'
                              : 'المتبقي للعميل (الفكة)'}
                          </span>
                        </span>
                        <span className="v">
                          {received ? egp(Math.abs(change)) : '٠'}
                          <small className="fs-13" style={{ opacity: 0.6, marginInlineStart: 4 }}>
                            ج
                          </small>
                        </span>
                      </div>
                    </div>
                    <div className="keypad">
                      {['7', '8', '9', '4', '5', '6', '1', '2', '3', '.', '0', '⌫'].map((k) => (
                        <button key={k} onClick={() => press(k)}>
                          {k}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {method === 'card' && (
                  <div className="col gap-3">
                    <div
                      className="card card-pad row gap-4"
                      style={{ background: 'var(--bg-sunken)' }}
                    >
                      <div
                        style={{
                          width: 64,
                          height: 88,
                          borderRadius: 12,
                          background: 'var(--bg-ink)',
                          color: 'var(--on-ink)',
                          display: 'grid',
                          placeItems: 'center',
                          flexShrink: 0,
                        }}
                      >
                        <Icon n="card" s={26} w={1.5} />
                      </div>
                      <div className="col gap-1 grow">
                        <b className="fs-14">ادفع على ماكينة البطاقات</b>
                        <p className="fs-13 t-2">
                          أدخل مبلغ <b className="num t-1">{egp(total)} ج</b> على الماكينة، وبعد
                          خروج إيصال الموافقة اضغط «تأكيد الدفع».
                        </p>
                      </div>
                    </div>
                    <Field
                      label="آخر ٤ أرقام / رقم الموافقة"
                      hint="اختياري — يظهر في تقرير الوردية"
                    >
                      <input
                        className="input ltr num"
                        style={{ textAlign: 'right', maxWidth: 240 }}
                        placeholder="•••• 4821"
                      />
                    </Field>
                  </div>
                )}

                {method === 'mixed' && (
                  <div className="col gap-3">
                    <div className="grid" style={{ gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                      <div className="col gap-2">
                        <span className="fs-13 fw-5 row gap-2">
                          <Icon n="cash" s={16} />
                          الجزء النقدي
                        </span>
                        <MoneyInput
                          size="md"
                          value={cashPart}
                          onChange={(v) =>
                            setCashPart(String(Math.min(Number(v || 0), total) || ''))
                          }
                          autoFocus
                          placeholder="0"
                        />
                      </div>
                      <div className="col gap-2">
                        <span className="fs-13 fw-5 row gap-2">
                          <Icon n="card" s={16} />
                          الجزء بالبطاقة <span className="t-3 fs-12">(تلقائي)</span>
                        </span>
                        <div
                          className="money-in md"
                          style={{ background: 'var(--bg-sunken)' }}
                        >
                          <span className="cur">ج.م</span>
                          <input
                            readOnly
                            value={cashPart ? String(cardA) : ''}
                            placeholder="—"
                          />
                        </div>
                      </div>
                    </div>
                    <div className="split-bar">
                      <span
                        style={{
                          width: `${total ? (cashA / total) * 100 : 0}%`,
                          background: 'var(--ok)',
                        }}
                      />
                      <span
                        style={{
                          width: `${total && cashPart ? (cardA / total) * 100 : 0}%`,
                          background: 'var(--info)',
                        }}
                      />
                    </div>
                    <div className="row between fs-12">
                      <span className="row gap-3">
                        <span className="row gap-1">
                          <i
                            style={{
                              width: 8,
                              height: 8,
                              borderRadius: 99,
                              background: 'var(--ok)',
                            }}
                          />
                          نقدي <b className="num">{egp(cashA)}</b>
                        </span>
                        <span className="row gap-1">
                          <i
                            style={{
                              width: 8,
                              height: 8,
                              borderRadius: 99,
                              background: 'var(--info)',
                            }}
                          />
                          بطاقة <b className="num">{egp(cashPart ? cardA : 0)}</b>
                        </span>
                      </span>
                      {valid ? (
                        <span className="t-ok row gap-1 fw-6">
                          <Icon n="check" s={14} w={2.5} />
                          المجموع = إجمالي الفاتورة
                        </span>
                      ) : (
                        <span className="t-3">حدد جزءًا نقديًا أقل من الإجمالي</span>
                      )}
                    </div>
                    <div className="row gap-2">
                      {[0.25, 0.5, 0.75].map((r) => (
                        <button
                          key={r}
                          className="note-chip"
                          onClick={() => setCashPart(String(Math.round(total * r)))}
                        >
                          {fmt(r * 100)}٪ نقدي
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                <Field
                  label={
                    <>
                      ملاحظات على الفاتورة <span className="t-3 fs-12">(اختياري)</span>
                    </>
                  }
                >
                  <input
                    className="input"
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    placeholder="تظهر في أسفل الإيصال"
                  />
                </Field>
                <div className="row gap-2" style={{ marginTop: 'auto' }}>
                  <button className="btn btn-secondary btn-lg" onClick={onClose}>
                    رجوع
                  </button>
                  <button
                    className="pay-btn grow"
                    style={{ margin: 0 }}
                    disabled={!valid || stage === 'sending'}
                    onClick={confirm}
                  >
                    <span className="row gap-2">
                      <Icon n="printer" s={18} />
                      {stage === 'sending' ? 'جارِ تسجيل البيع…' : 'تأكيد الدفع وطباعة الإيصال'}
                    </span>
                    <span
                      className="kbd"
                      style={{
                        background: 'rgba(255,255,255,.15)',
                        borderColor: 'rgba(255,255,255,.35)',
                        color: '#fff',
                      }}
                    >
                      Enter
                    </span>
                  </button>
                </div>
              </div>
              <div className="co-side">
                <div className="row between">
                  <span className="section-label">ملخص الفاتورة</span>
                  <span className="fs-12 t-3 num">
                    {fmt(cart.reduce((s, l) => s + l.qty, 0))} قطعة
                  </span>
                </div>
                <div className="col gap-2" style={{ flex: 1, overflow: 'auto', maxHeight: 300 }}>
                  {cart.map((l) => {
                    const p = posMockService.getProductById(l.id);
                    if (!p) return null;
                    return (
                      <div key={l.id} className="row gap-2">
                        <PImg p={p} size="xs" />
                        <div className="grow" style={{ minWidth: 0 }}>
                          <div className="fs-12 fw-5 truncate">{p.name}</div>
                          <div className="fs-12 t-3 num">
                            {fmt(l.qty)} × {egp(l.price)}
                          </div>
                        </div>
                        <span className="price fs-13">{egp(l.qty * l.price)}</span>
                      </div>
                    );
                  })}
                </div>
                <div
                  className="col gap-1 fs-13"
                  style={{ borderTop: '1px dashed var(--line-strong)', paddingTop: 10 }}
                >
                  <div className="row between t-2">
                    <span>المجموع</span>
                    <span className="num">{egp(subtotal)}</span>
                  </div>
                  {discount > 0 && (
                    <div className="row between t-2">
                      <span>خصم</span>
                      <span className="num t-ok">−{egp(discount)}</span>
                    </div>
                  )}
                  <div className="row between fw-6">
                    <span>الإجمالي</span>
                    <span className="num fs-16">{egp(total)}</span>
                  </div>
                </div>
                <div
                  className="col gap-2"
                  style={{ borderTop: '1px solid var(--line)', paddingTop: 12 }}
                >
                  <Api m="POST" path="/api/v1/pos/sales" />
                  <div className="fs-12 t-3">Idempotency-Key</div>
                  <code
                    className="mono"
                    style={{
                      fontSize: 10.5,
                      direction: 'ltr',
                      wordBreak: 'break-all',
                      color: 'var(--text-2)',
                    }}
                  >
                    {idem}
                  </code>
                  <div className="fs-12 t-3">يمنع تكرار الخصم عند الضغط المزدوج</div>
                </div>
              </div>
            </div>
          ) : (
            <ReceiptDone
              invoiceNumber={invoiceNumber}
              total={total}
              method={method}
              received={rec}
              change={change}
              cashA={cashA}
              cardA={cardA}
              cart={cart}
              customer={customer}
              discount={discount}
              notes={notes}
              onNew={() => {
                onPaid();
                onClose();
              }}
              branch={branch}
              cashier={cashier}
            />
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}import React from 'react';
import { Icon } from '../ui/Icons';
import { egp, fmt, PImg, Api, Empty, Drawer } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { PosHeldSale, Branch } from '../../types/pos.types';

interface HeldDrawerProps {
  open: boolean;
  onClose: () => void;
  held: PosHeldSale[];
  onResume: (h: PosHeldSale) => void;
  onDelete: (h: PosHeldSale) => void;
  cartBusy: boolean;
  branch?: Branch | null;
}

export function HeldDrawer({
  open,
  onClose,
  held,
  onResume,
  onDelete,
  cartBusy,
  branch,
}: HeldDrawerProps) {
  return (
    <Drawer
      open={open}
      onClose={onClose}
      title="الفواتير المعلقة"
      sub={
        <span className="row gap-2">
          {fmt(held.length)} فاتورة في {branch?.name || 'فرع مدينة نصر'}{' '}
          <Api path="/pos/sales/held" />
        </span>
      }
    >
      {held.length === 0 ? (
        <Empty
          icon="inbox"
          title="لا توجد فواتير معلقة"
          body="الفواتير التي تعلّقها من شاشة البيع ستظهر هنا لاستكمالها لاحقًا."
        />
      ) : (
        <div className="col gap-3">
          {cartBusy && (
            <div className="banner b-warn">
              <Icon n="alert" s={16} />
              السلة الحالية بها أصناف — الاسترجاع سيضيف الأصناف إليها.
            </div>
          )}
          {held.map((h) => {
            const total = h.items.reduce((s, i) => {
              const p = posMockService.getProductById(i.id);
              return s + (p?.price || 0) * i.qty;
            }, 0);
            const pcs = h.items.reduce((s, i) => s + i.qty, 0);

            return (
              <div key={h.ref} className="held-card" data-screen-label="06 Held Sale">
                <div className="row gap-3">
                  <div className="stack-thumbs">
                    {h.items.slice(0, 3).map((i) => (
                      <PImg
                        key={i.id}
                        p={posMockService.getProductById(i.id)}
                        size="sm"
                      />
                    ))}
                  </div>
                  <div className="grow">
                    <div className="row gap-2">
                      <b className="mono" style={{ fontSize: 13 }}>
                        {h.ref}
                      </b>
                      {h.mins > 60 && (
                        <span className="badge b-warn" style={{ height: 20, fontSize: 11 }}>
                          منذ أكثر من ساعة
                        </span>
                      )}
                    </div>
                    <div className="fs-12 t-3 row gap-1">
                      <Icon n="history" s={12} />
                      {h.at}
                      <span className="dot-sep" />
                      {fmt(pcs)} قطعة
                      <span className="dot-sep" />
                      {h.customer || 'بدون عميل'}
                    </div>
                  </div>
                  <span className="price fs-20">
                    {egp(total)}
                    <small>ج</small>
                  </span>
                </div>
                {h.note && (
                  <div
                    className="fs-13 t-2 row gap-2"
                    style={{
                      padding: '8px 10px',
                      borderRadius: 10,
                      background: 'var(--bg-sunken)',
                    }}
                  >
                    <Icon n="edit" s={14} />
                    {h.note}
                  </div>
                )}
                <div className="row gap-2">
                  <button className="btn btn-primary grow" onClick={() => onResume(h)}>
                    <Icon n="arrowUpLeft" s={15} />
                    استرجاع الفاتورة
                  </button>
                  <button className="btn btn-ghost" onClick={() => onDelete(h)}>
                    <Icon n="trash" s={15} />
                    حذف
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </Drawer>
  );
}import React, { useState, useEffect } from 'react';
import { Icon } from '../ui/Icons';
import { egp, fmt, PImg, Api, Field, Modal } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { PosCartLine, Customer } from '../../types/pos.types';

interface HoldModalProps {
  open: boolean;
  onClose: () => void;
  onHold: (note: string) => void;
  cart: PosCartLine[];
  customer: Customer | null;
}

export function HoldModal({ open, onClose, onHold, cart, customer }: HoldModalProps) {
  const [note, setNote] = useState('');

  useEffect(() => {
    if (open) setNote('');
  }, [open]);

  const total = cart.reduce((s, l) => s + l.price * l.qty, 0);

  return (
    <Modal
      open={open}
      onClose={onClose}
      title="تعليق الفاتورة"
      width={460}
      footer={
        <>
          <span className="grow">
            <Api m="POST" path="/pos/sales/hold" />
          </span>
          <button className="btn btn-secondary" onClick={onClose}>
            إلغاء
          </button>
          <button className="btn btn-primary" onClick={() => onHold(note)}>
            <Icon n="pause" s={15} />
            تعليق وخدمة زبون آخر
          </button>
        </>
      }
    >
      <div className="col gap-4">
        <div className="sunken row gap-3" style={{ padding: 12 }}>
          <div className="stack-thumbs">
            {cart.slice(0, 3).map((l) => (
              <PImg key={l.id} p={posMockService.getProductById(l.id)} size="xs" />
            ))}
          </div>
          <div className="grow">
            <div className="fs-13 fw-6 num">
              {fmt(cart.reduce((s, l) => s + l.qty, 0))} قطعة
            </div>
            <div className="fs-12 t-3">{customer ? customer.name : 'بدون عميل'}</div>
          </div>
          <span className="price fs-16">{egp(total)} ج</span>
        </div>
        <Field
          label={
            <>
              ملاحظة <span className="t-3 fs-12">(اختياري)</span>
            </>
          }
        >
          <input
            className="input"
            autoFocus
            value={note}
            onChange={(e) => setNote(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && onHold(note)}
            placeholder="مثال: زبون بيجيب محفظة إضافية"
          />
        </Field>
        <div className="row gap-2 wrap">
          {['بانتظار العميل', 'بيجيب فلوس', 'بيقيس لون تاني', 'هيرجع كمان شوية'].map((s) => (
            <button key={s} className="note-chip" onClick={() => setNote(s)}>
              {s}
            </button>
          ))}
        </div>
      </div>
    </Modal>
  );
}import React, { useEffect } from 'react';
import { Icon } from '../ui/Icons';
import { egp, fmt, Kbd } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { PosCartLine, Customer, Branch, CashierUser } from '../../types/pos.types';

interface ReceiptDoneProps {
  invoiceNumber: string;
  total: number;
  method: 'cash' | 'card' | 'mixed';
  received: number;
  change: number;
  cashA: number;
  cardA: number;
  cart: PosCartLine[];
  customer: Customer | null;
  discount: number;
  notes?: string;
  onNew: () => void;
  branch?: Branch | null;
  cashier?: CashierUser | null;
}

export function ReceiptDone({
  invoiceNumber,
  total,
  method,
  received,
  change,
  cashA,
  cardA,
  cart,
  customer,
  discount,
  notes,
  onNew,
  branch,
  cashier,
}: ReceiptDoneProps) {
  useEffect(() => {
    const h = (e: KeyboardEvent) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        onNew();
      }
    };
    const t = setTimeout(() => window.addEventListener('keydown', h), 300);
    return () => {
      clearTimeout(t);
      window.removeEventListener('keydown', h);
    };
  }, [onNew]);

  return (
    <div className="grid" style={{ gridTemplateColumns: '1fr 360px' }}>
      <div
        className="col center"
        style={{ padding: 36, gap: 18, alignItems: 'flex-start', justifyContent: 'center' }}
      >
        <span
          style={{
            width: 60,
            height: 60,
            borderRadius: 20,
            background: 'var(--ok-bg)',
            color: 'var(--ok)',
            display: 'grid',
            placeItems: 'center',
          }}
        >
          <Icon n="check" s={30} w={2.4} />
        </span>
        <div>
          <h2 className="fs-26">تم تسجيل البيع بنجاح</h2>
          <p className="t-2" style={{ marginTop: 4 }}>
            فاتورة <b className="num ltr t-1">{invoiceNumber}</b> — تم خصم المخزون وإيداع النقدية
            بالدرج.
          </p>
        </div>
        {method !== 'card' && (
          <div className="change" style={{ width: '100%', maxWidth: 380 }}>
            <span className="fs-13" style={{ opacity: 0.8 }}>
              {method === 'cash' ? 'الفكة للعميل' : 'تم تحصيل نقدي'}
            </span>
            <span className="v">
              {egp(method === 'cash' ? Math.max(0, change) : cashA)}{' '}
              <small className="fs-13" style={{ opacity: 0.6 }}>
                ج
              </small>
            </span>
          </div>
        )}
        <div className="row gap-2">
          <button className="btn btn-secondary btn-lg" onClick={() => window.print()}>
            <Icon n="printer" s={17} />
            إعادة الطباعة
          </button>
          <button className="btn btn-primary btn-lg" autoFocus onClick={onNew}>
            فاتورة جديدة <Kbd>Enter</Kbd>
          </button>
        </div>
      </div>
      <div
        style={{
          background: 'var(--bg-sunken)',
          padding: '28px 0 40px',
          borderInlineStart: '1px solid var(--line)',
        }}
      >
        <div className="receipt">
          <div style={{ textAlign: 'center' }}>
            <b className="fs-14 display">الفريد للشنط</b>
            <div style={{ color: '#6f6a76' }}>{branch?.name || 'فرع مدينة نصر'}</div>
            <div className="num" style={{ color: '#6f6a76' }}>
              {invoiceNumber} ·{' '}
              {new Date().toLocaleString('ar-EG', { dateStyle: 'short', timeStyle: 'short' })}
            </div>
          </div>
          <div className="dash" />
          {cart.map((l) => {
            const p = posMockService.getProductById(l.id);
            if (!p) return null;
            return (
              <div key={l.id}>
                <div className="truncate">{p.name}</div>
                <div className="rr" style={{ color: '#6f6a76' }}>
                  <span className="num">
                    {fmt(l.qty)} × {egp(l.price)}
                  </span>
                  <span className="num" style={{ color: '#18151c' }}>
                    {egp(l.qty * l.price)}
                  </span>
                </div>
              </div>
            );
          })}
          <div className="dash" />
          {discount > 0 && (
            <div className="rr">
              <span>خصم</span>
              <span className="num">−{egp(discount)}</span>
            </div>
          )}
          <div className="rr" style={{ fontWeight: 700, fontSize: 14 }}>
            <span>الإجمالي</span>
            <span className="num">{egp(total)} ج</span>
          </div>
          {method === 'cash' && (
            <>
              <div className="rr">
                <span>نقدي مستلم</span>
                <span className="num">{egp(received)}</span>
              </div>
              <div className="rr">
                <span>الباقي</span>
                <span className="num">{egp(Math.max(0, change))}</span>
              </div>
            </>
          )}
          {method === 'card' && (
            <div className="rr">
              <span>بطاقة</span>
              <span className="num">{egp(total)}</span>
            </div>
          )}
          {method === 'mixed' && (
            <>
              <div className="rr">
                <span>نقدي</span>
                <span className="num">{egp(cashA)}</span>
              </div>
              <div className="rr">
                <span>بطاقة</span>
                <span className="num">{egp(cardA)}</span>
              </div>
            </>
          )}
          {customer && (
            <>
              <div className="dash" />
              <div className="rr">
                <span>العميل</span>
                <span>{customer.name}</span>
              </div>
            </>
          )}
          {notes && <div style={{ marginTop: 6, color: '#6f6a76' }}>{notes}</div>}
          <div className="dash" />
          <div style={{ textAlign: 'center', color: '#6f6a76' }}>
            الكاشير: {cashier?.name || 'أحمد سمير'} — الاستبدال خلال ١٤ يومًا بالإيصال
          </div>
          <div className="bars" />
        </div>
      </div>
    </div>
  );
}import React, { useState, useEffect } from 'react';
import { Icon } from '../ui/Icons';
import { fmt, PImg, Api, Empty, Status, toAsciiNum, cx } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { StockTransfer } from '../../types/pos.types';

interface ReceiveTabProps {
  toast: (msg: string, tone?: 'ok' | 'bad') => void;
}

export function ReceiveTab({ toast }: ReceiveTabProps) {
  const [list, setList] = useState<StockTransfer[]>([]);
  const [cur, setCur] = useState<number | null>(null);
  const [rec, setRec] = useState<Record<number, string>>({});

  useEffect(() => {
    posMockService.getTransfersIn().then((transfers) => {
      setList(transfers);
      if (transfers.length > 0) {
        setCur(transfers[0].id);
      }
    });
  }, []);

  const t = list.find((x) => x.id === cur);

  useEffect(() => {
    if (t) {
      setRec(Object.fromEntries(t.items.map((i) => [i.id, String(i.qty)])));
    }
  }, [cur, t]);

  if (!t) {
    return (
      <div className="card">
        <Empty
          icon="truck"
          title="لا توجد شحنات واردة"
          body="كل التحويلات المشحونة للفرع تم استلامها."
        />
      </div>
    );
  }

  const shipped = t.items.reduce((s, i) => s + i.qty, 0);
  const got = t.items.reduce((s, i) => s + Number(rec[i.id] || 0), 0);
  const diffs = t.items.filter((i) => Number(rec[i.id] || 0) !== i.qty).length;

  const handleReceive = async () => {
    const quantities: Record<number, number> = {};
    for (const [id, val] of Object.entries(rec)) {
      quantities[Number(id)] = Number(val);
    }
    await posMockService.receiveTransfer(t.id, quantities);
    toast(`تم استلام ${t.number} ورفع رصيد الفرع`);
    const rest = list.filter((x) => x.id !== t.id);
    setList(rest);
    setCur(rest[0]?.id || null);
  };

  return (
    <div
      className="grid"
      style={{
        gridTemplateColumns: '320px minmax(0, 1fr)',
        gap: 16,
        alignItems: 'start',
      }}
    >
      <div className="tr-list">
        {list.map((x) => (
          <button
            key={x.id}
            className="tr-item"
            aria-pressed={x.id === cur}
            onClick={() => setCur(x.id)}
          >
            <div className="row between">
              <b className="mono" style={{ fontSize: 12.5 }}>
                {x.number}
              </b>
              <Status kind="transfer" s="shipped" />
            </div>
            <div className="route">
              <Icon
                n={x.from.includes('المخزن') ? 'warehouse' : 'store'}
                s={15}
                className="t-3"
              />
              <span className="truncate" style={{ maxWidth: 110 }}>
                {x.from}
              </span>
              <span className="ln" />
              <Icon n="store" s={15} className="t-acc" />
              <span>فرعنا</span>
            </div>
            <div className="row between fs-12 t-3">
              <span>{x.shipped}</span>
              <span className="num">
                {fmt(x.items.reduce((s, i) => s + i.qty, 0))} قطعة · {fmt(x.items.length)} أصناف
              </span>
            </div>
          </button>
        ))}
      </div>
      <div className="card" style={{ overflow: 'hidden' }}>
        <div className="card-head">
          <div className="col">
            <h3>{t.number}</h3>
            <span className="fs-12 t-3">
              من {t.from} · السائق {t.driver}
            </span>
          </div>
          <button
            className="btn btn-secondary btn-sm"
            onClick={() =>
              setRec(Object.fromEntries(t.items.map((i) => [i.id, String(i.qty)])))
            }
          >
            <Icon n="check" s={14} />
            الكل مطابق
          </button>
        </div>
        <table className="tbl">
          <thead>
            <tr>
              <th>الصنف</th>
              <th className="n">المشحون</th>
              <th style={{ textAlign: 'center' }}>المستلم فعليًا</th>
              <th className="n">الفرق</th>
              <th className="n">رصيد الفرع بعد</th>
            </tr>
          </thead>
          <tbody>
            {t.items.map((i) => {
              const p = posMockService.getProductById(i.id);
              const r = Number(rec[i.id] || 0);
              const d = r - i.qty;
              const stock = p?.stock || 0;
              return (
                <tr key={i.id} className={d !== 0 ? 'selected' : ''}>
                  <td>
                    <div className="row gap-3">
                      <PImg p={p} size="xs" />
                      <div>
                        <div className="fw-5">{p?.name}</div>
                        <div className="mono t-3" style={{ fontSize: 11 }}>
                          {p?.sku}
                        </div>
                      </div>
                    </div>
                  </td>
                  <td className="n fw-6">{fmt(i.qty)}</td>
                  <td style={{ textAlign: 'center' }}>
                    <input
                      className={cx('qty-input', d !== 0 && 'bad')}
                      value={rec[i.id] ?? ''}
                      onChange={(e) =>
                        setRec({ ...rec, [i.id]: toAsciiNum(e.target.value) })
                      }
                    />
                  </td>
                  <td className="n">
                    {d === 0 ? (
                      <span className="t-ok">
                        <Icon n="check" s={15} w={2.4} />
                      </span>
                    ) : (
                      <span className="badge b-bad num">
                        {d > 0 ? '+' : '−'}
                        {fmt(Math.abs(d))}
                      </span>
                    )}
                  </td>
                  <td className="n">
                    <span className="t-3 num">{fmt(stock)}</span>{' '}
                    <Icon n="arrowLeft" s={12} className="t-3" />{' '}
                    <b className="num">{fmt(stock + r)}</b>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
        <div
          className="row gap-3"
          style={{
            padding: '14px 16px',
            borderTop: '1px solid var(--line)',
            background: 'var(--bg-sunken)',
          }}
        >
          <div className="grow col gap-1">
            <div className="fs-13">
              <b className="num">{fmt(got)}</b> من <b className="num">{fmt(shipped)}</b> قطعة{' '}
              {diffs > 0 && (
                <span className="badge b-bad" style={{ marginInlineStart: 6 }}>
                  {fmt(diffs)} صنف به فرق
                </span>
              )}
            </div>
            <div className="row gap-2">
              <Api m="POST" path={`/pos/transfers/${t.id}/receive`} />
              <span className="perm">
                <Icon n="shield" s={11} />
                transfers.receive
              </span>
            </div>
          </div>
          <button className="btn btn-accent btn-lg" onClick={handleReceive}>
            <Icon n="check" s={16} w={2.4} />
            تأكيد الاستلام ورفع الرصيد
          </button>
        </div>
      </div>
    </div>
  );
}import React, { useState, useEffect } from 'react';
import { Icon } from '../ui/Icons';
import { fmt, PImg, Api, Empty, Search, Field, cx } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { PosProduct, TransferSource, Branch } from '../../types/pos.types';

interface RequestTabProps {
  toast: (msg: string, tone?: 'ok' | 'bad') => void;
  branch?: Branch | null;
}

export function RequestTab({ toast, branch }: RequestTabProps) {
  const [src, setSrc] = useState<number>(1);
  const [lines, setLines] = useState<{ id: number; qty: number }[]>([
    { id: 106, qty: 8 },
    { id: 112, qty: 10 },
  ]);
  const [q, setQ] = useState('');
  const [note, setNote] = useState('');
  const [allProducts, setAllProducts] = useState<PosProduct[]>([]);
  const [sources, setSources] = useState<TransferSource[]>([]);

  useEffect(() => {
    posMockService.getProducts().then(setAllProducts);
    posMockService.getTransferSources().then((s) => {
      setSources(s);
      if (s.length > 0) setSrc(s[0].id);
    });
  }, []);

  const res = q
    ? allProducts
        .filter(
          (p) =>
            p.name.includes(q) ||
            p.sku.toLowerCase().includes(q.toLowerCase())
        )
        .slice(0, 5)
    : [];

  const suggestions = allProducts.filter(
    (p) => p.stock <= p.reorder && !lines.find((l) => l.id === p.id)
  );

  const add = (p: PosProduct, qty = 1) =>
    setLines((l) => (l.find((x) => x.id === p.id) ? l : [...l, { id: p.id, qty }]));

  const handleSubmit = async () => {
    if (!lines.length) return;
    await posMockService.requestTransfer(src, lines, note);
    toast('تم إرسال طلب التحويل للاعتماد');
    setLines([]);
    setNote('');
  };

  const currentSource = sources.find((s) => s.id === src);

  return (
    <div
      className="grid"
      style={{
        gridTemplateColumns: 'minmax(0, 1fr) 340px',
        gap: 16,
        alignItems: 'start',
      }}
    >
      <div className="card" style={{ overflow: 'visible' }}>
        <div className="card-head">
          <h3>الأصناف المطلوبة</h3>
          <span className="meta">
            {fmt(lines.length)} أصناف · {fmt(lines.reduce((s, l) => s + l.qty, 0))} قطعة
          </span>
        </div>
        <div style={{ padding: 16, position: 'relative' }}>
          <Search value={q} onChange={setQ} placeholder="أضف صنفًا بالاسم أو الكود…" />
          {res.length > 0 && (
            <div className="scan-results" style={{ insetInline: 16 }}>
              {res.map((p) => (
                <button
                  key={p.id}
                  className="scan-row"
                  onClick={() => {
                    add(p);
                    setQ('');
                  }}
                >
                  <PImg p={p} size="xs" />
                  <span className="grow fs-13">{p.name}</span>
                  <span className="badge b-neutral">رصيدنا {fmt(p.stock)}</span>
                </button>
              ))}
            </div>
          )}
        </div>
        <table className="tbl">
          <thead>
            <tr>
              <th>الصنف</th>
              <th className="n">رصيدنا</th>
              <th className="n">حد الطلب</th>
              <th style={{ textAlign: 'center' }}>الكمية المطلوبة</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {lines.map((l) => {
              const p = posMockService.getProductById(l.id);
              if (!p) return null;
              return (
                <tr key={l.id}>
                  <td>
                    <div className="row gap-3">
                      <PImg p={p} size="xs" />
                      <div>
                        <div className="fw-5">{p.name}</div>
                        <div className="mono t-3" style={{ fontSize: 11 }}>
                          {p.sku}
                        </div>
                      </div>
                    </div>
                  </td>
                  <td className={cx('n', p.stock <= p.reorder && 't-warn fw-6')}>
                    {fmt(p.stock)}
                  </td>
                  <td className="n t-2">{fmt(p.reorder)}</td>
                  <td style={{ textAlign: 'center' }}>
                    <div className="stepper-q">
                      <button
                        onClick={() =>
                          setLines((x) =>
                            x.map((y) => (y.id === l.id ? { ...y, qty: y.qty + 1 } : y))
                          )
                        }
                      >
                        <Icon n="plus" s={13} />
                      </button>
                      <span>{fmt(l.qty)}</span>
                      <button
                        onClick={() =>
                          setLines((x) =>
                            x.map((y) =>
                              y.id === l.id ? { ...y, qty: Math.max(1, y.qty - 1) } : y
                            )
                          )
                        }
                      >
                        <Icon n="minus" s={13} />
                      </button>
                    </div>
                  </td>
                  <td>
                    <button
                      className="icon-btn sm"
                      onClick={() => setLines((x) => x.filter((y) => y.id !== l.id))}
                    >
                      <Icon n="trash" s={15} />
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
        {lines.length === 0 && (
          <Empty
            icon="box"
            title="لم تتم إضافة أصناف"
            body="ابحث عن صنف أو اختر من المقترحات."
          />
        )}
        {suggestions.length > 0 && (
          <div style={{ padding: 16, borderTop: '1px solid var(--line)' }}>
            <div className="section-label row gap-2" style={{ marginBottom: 10 }}>
              <Icon n="sparkle" s={13} className="t-acc" />
              مقترح — أصناف تحت حد الطلب
            </div>
            <div className="row gap-2 wrap">
              {suggestions.map((p) => (
                <button
                  key={p.id}
                  className="chip"
                  onClick={() => add(p, Math.max(1, p.reorder * 2 - p.stock))}
                >
                  <Icon n="plus" s={12} />
                  {p.name.split('—')[0]}
                  <span className="count">{fmt(p.stock)}</span>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
      <div className="card card-pad col gap-4" style={{ position: 'sticky', top: 0 }}>
        <div className="col gap-2">
          <span className="fs-13 fw-5">الفرع المصدر</span>
          <div className="col gap-2">
            {sources.map((s) => (
              <button
                key={s.id}
                role="radio"
                aria-checked={src === s.id}
                onClick={() => setSrc(s.id)}
                className="row gap-3"
                style={{
                  padding: '10px 12px',
                  borderRadius: 12,
                  border:
                    '1.5px solid ' +
                    (src === s.id ? 'var(--acc)' : 'var(--line-strong)'),
                  background: src === s.id ? 'var(--acc-tint)' : 'var(--bg-card)',
                  textAlign: 'start',
                }}
              >
                <span className="radio-dot" />
                <Icon n={s.kind} s={17} className="t-3" />
                <span className="fs-13 fw-5 grow">{s.name}</span>
              </button>
            ))}
          </div>
        </div>
        <div
          className="route"
          style={{ padding: '10px 12px', borderRadius: 12, background: 'var(--bg-sunken)' }}
        >
          <Icon n="warehouse" s={15} />
          <span className="truncate">{currentSource?.name || 'المخزن الرئيسي — العبور'}</span>
          <span className="ln" />
          <Icon n="store" s={15} className="t-acc" />
          {branch?.name || 'فرع مدينة نصر'}
        </div>
        <Field
          label={
            <>
              ملاحظة <span className="t-3 fs-12">(اختياري)</span>
            </>
          }
        >
          <textarea
            className="input"
            rows={2}
            value={note}
            onChange={(e) => setNote(e.target.value)}
            placeholder="مثال: مطلوب قبل الويك إند"
          />
        </Field>
        <button
          className="btn btn-accent btn-lg"
          disabled={!lines.length}
          onClick={handleSubmit}
        >
          <Icon n="arrowLeft" s={16} />
          إرسال طلب التحويل
        </button>
        <div className="col gap-1">
          <Api m="POST" path="/pos/transfer-requests" />
          <span className="perm">
            <Icon n="shield" s={11} />
            transfers.create · Idempotency-Key
          </span>
        </div>
      </div>
    </div>
  );
}import React, { useState, useEffect } from 'react';
import { Icon } from '../ui/Icons';
import { egp, fmt, PImg, Api, KPI, FilterSelect, Empty, cx } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { PosProduct, ProductCategory, Branch } from '../../types/pos.types';

interface StockPageProps {
  branch?: Branch | null;
}

export function StockPage({ branch }: StockPageProps) {
  const [q, setQ] = useState('');
  const [low, setLow] = useState(false);
  const [cat, setCat] = useState('all');
  const [products, setProducts] = useState<PosProduct[]>([]);
  const [categories, setCategories] = useState<ProductCategory[]>([]);

  const loadData = () => {
    posMockService.getProducts().then(setProducts);
    posMockService.getCategories().then(setCategories);
  };

  useEffect(() => {
    loadData();
    const unsub = posMockService.subscribe(loadData);
    return unsub;
  }, []);

  const list = products.filter(
    (p) =>
      (!q ||
        p.name.includes(q) ||
        p.sku.toLowerCase().includes(q.toLowerCase()) ||
        p.barcode.includes(q)) &&
      (!low || p.stock <= p.reorder) &&
      (cat === 'all' || p.cat === cat)
  );

  const lowCount = products.filter((p) => p.stock <= p.reorder).length;
  const outCount = products.filter((p) => p.stock === 0).length;

  return (
    <div className="page" data-screen-label="08 Branch Stock">
      <div className="page-in page-enter">
        <div className="page-title">
          <div>
            <h1>مخزون الفرع</h1>
            <p>أرصدة {branch?.name || 'فرع مدينة نصر'} لحظيًا — بدون مغادرة نقطة البيع.</p>
          </div>
          <Api path={`/pos/stock?q=${q || '…'}&low_stock=${low}&per_page=20`} />
        </div>
        <div
          className="grid"
          style={{ gridTemplateColumns: 'repeat(3, 1fr)', gap: 12, marginBottom: 16 }}
        >
          <KPI
            label="أصناف بالفرع"
            value={fmt(products.length)}
            icon="box"
            foot={
              <>
                إجمالي{' '}
                <b className="num t-1">
                  {fmt(products.reduce((s, p) => s + p.stock, 0))}
                </b>{' '}
                قطعة
              </>
            }
          />
          <KPI
            label="منخفضة عن حد الطلب"
            value={fmt(lowCount)}
            icon="alert"
            warn
            onClick={() => setLow(!low)}
            active={low}
            foot="اضغط للفلترة"
          />
          <KPI
            label="نفدت من الفرع"
            value={fmt(outCount)}
            icon="x"
            foot="اطلب تحويل من فرع آخر"
          />
        </div>
        <div className="card" style={{ overflow: 'hidden' }}>
          <div className="toolbar">
            <div className="input-group" style={{ width: 360 }}>
              <Icon n="barcode" s={16} />
              <input
                className="input"
                autoFocus
                value={q}
                onChange={(e) => setQ(e.target.value)}
                placeholder="SKU أو الاسم أو الباركود"
              />
            </div>
            <button className={cx('chip', low && 'on')} onClick={() => setLow(!low)}>
              <Icon n="alert" s={13} />
              الأصناف المنخفضة
              <span className="count">{fmt(lowCount)}</span>
            </button>
            <FilterSelect
              label="الفئة"
              value={cat === 'all' ? '' : cat}
              options={categories.slice(1).map((c) => ({ value: c.id, label: c.name }))}
              onChange={(v) => setCat(v || 'all')}
            />
            <span className="ms-auto fs-12 t-3">{fmt(list.length)} صنف</span>
          </div>
          <div className="table-wrap">
            <table className="tbl">
              <thead>
                <tr>
                  <th>الصنف</th>
                  <th>الكود</th>
                  <th>الباركود</th>
                  <th className="n">السعر</th>
                  <th>المستوى</th>
                  <th className="n">الرصيد المتاح</th>
                  <th className="n">حد إعادة الطلب</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {list.map((p) => {
                  const st = p.stock === 0 ? 'out' : p.stock <= p.reorder ? 'low' : 'ok';
                  const pct = Math.min(100, (p.stock / (p.reorder * 3)) * 100);
                  return (
                    <tr key={p.id}>
                      <td>
                        <div className="row gap-3">
                          <PImg p={p} size="sm" />
                          <span className="fw-5">{p.name}</span>
                        </div>
                      </td>
                      <td>
                        <span className="mono">{p.sku}</span>
                      </td>
                      <td>
                        <span className="mono t-3">{p.barcode}</span>
                      </td>
                      <td className="n">{egp(p.price)}</td>
                      <td>
                        <div className="lvl">
                          <span
                            style={{
                              width: pct + '%',
                              background:
                                st === 'ok'
                                  ? 'var(--ok)'
                                  : st === 'low'
                                  ? 'var(--warn)'
                                  : 'var(--bad)',
                            }}
                          />
                          <i style={{ insetInlineStart: 100 / 3 + '%' }} />
                        </div>
                      </td>
                      <td className="n">
                        <span
                          className={cx(
                            'fs-16 fw-6',
                            st === 'out' ? 't-bad' : st === 'low' ? 't-warn' : ''
                          )}
                        >
                          {fmt(p.stock)}
                        </span>
                      </td>
                      <td className="n t-2">{fmt(p.reorder)}</td>
                      <td>
                        {st === 'out' ? (
                          <span className="badge b-bad">
                            <span className="dot" />
                            نفد
                          </span>
                        ) : st === 'low' ? (
                          <span className="badge b-warn">
                            <span className="dot" />
                            منخفض
                          </span>
                        ) : (
                          <span className="badge b-ok">
                            <span className="dot" />
                            متوفر
                          </span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          {list.length === 0 && (
            <Empty
              icon="search"
              title="لا توجد نتائج"
              body="جرّب كلمة بحث مختلفة أو أزل فلتر المنخفضة."
            />
          )}
        </div>
      </div>
    </div>
  );
}import React, { useState, useEffect } from 'react';
import { Icon } from '../ui/Icons';
import { fmt, PImg, Api, toAsciiNum, cx } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { PosProduct, StocktakeSession } from '../../types/pos.types';

interface StocktakePageProps {
  toast: (msg: string, tone?: 'ok' | 'bad') => void;
}

export function StocktakePage({ toast }: StocktakePageProps) {
  const [scope, setScope] = useState<PosProduct[]>([]);
  const [session, setSession] = useState<StocktakeSession | null>(null);
  const [code, setCode] = useState('');
  const [qty, setQty] = useState('1');
  const [listening, setListening] = useState(false);
  const [heard, setHeard] = useState('');

  const loadSession = () => {
    posMockService.getStocktakeSession().then((res) => {
      setScope(res.scope);
      setSession(res.session);
    });
  };

  useEffect(() => {
    loadSession();
    const unsub = posMockService.subscribe(loadSession);
    return unsub;
  }, []);

  if (!session) return null;

  const counts = session.counts;
  const counted = Object.keys(counts).length;
  const last = session.lastScan || {
    id: 111,
    qty: 85,
    via: 'voice' as const,
    words: 'خمسة وتمانين',
  };
  const log = session.log;

  const submitCode = async () => {
    const p =
      posMockService.getProductById(101) ||
      scope.find(
        (x) =>
          x.barcode === code.trim() ||
          x.sku.toLowerCase() === code.trim().toLowerCase()
      ) ||
      scope[4];

    await posMockService.recordStocktakeScan(p.id, Number(qty || 1), 'barcode');
    setCode('');
    setQty('1');
    loadSession();
  };

  const mic = () => {
    if (listening) return;
    setListening(true);
    setHeard('');
    const words = 'اتناشر';
    let i = 0;
    const iv = setInterval(() => {
      i++;
      setHeard(words.slice(0, i));
      if (i >= words.length) {
        clearInterval(iv);
        setTimeout(async () => {
          setListening(false);
          await posMockService.recordStocktakeScan(105, 12, 'voice', words);
          toast('سُجّل ١٢ — باك باك لابتوب');
          loadSession();
        }, 500);
      }
    }, 140);
  };

  const lp = posMockService.getProductById(last.id) || scope[0];

  return (
    <div className="page" data-screen-label="10 Stocktake">
      <div className="page-in page-enter">
        <div className="page-title">
          <div>
            <div className="row gap-2" style={{ marginBottom: 4 }}>
              <span className="badge b-acc">
                <span className="dot" />
                جرد جارٍ
              </span>
              <span className="mono t-3">{session.code}</span>
            </div>
            <h1>جرد الفرع</h1>
            <p>امسح الباركود أو قل الكمية بصوتك — بالعامية المصرية.</p>
          </div>
          <div className="col gap-2" style={{ minWidth: 280 }}>
            <div className="row between fs-13">
              <span className="t-2">تقدم الجرد</span>
              <b className="num">
                {fmt(counted)} / {fmt(scope.length)} صنف
              </b>
            </div>
            <div className="progress">
              <span style={{ width: (counted / (scope.length || 1)) * 100 + '%' }} />
            </div>
          </div>
        </div>
        <div className="st-grid">
          <div className="col gap-4">
            <div className="card card-pad row gap-6" style={{ alignItems: 'center' }}>
              <button
                className={cx('mic', listening && 'on')}
                onClick={mic}
                aria-label="الإدخال الصوتي"
              >
                <Icon n="mic" s={44} w={1.6} />
              </button>
              <div className="grow col gap-3">
                <div className="fs-13 t-2">
                  {listening
                    ? 'بسمعك… قول الكمية'
                    : 'اضغط الميكروفون وقل الكمية للصنف الحالي'}
                </div>
                <div className="row gap-3" style={{ minHeight: 44 }}>
                  {listening && (
                    <div className="wave">
                      {Array.from({ length: 14 }).map((_, i) => (
                        <i key={i} style={{ animationDelay: i * 0.06 + 's' }} />
                      ))}
                    </div>
                  )}
                  <span className="display" style={{ fontSize: 30, fontWeight: 500 }}>
                    {heard ? (
                      `«${heard}»`
                    ) : (
                      <span className="t-3 fs-20">مثال: «اتناشر» ، «خمسة وعشرين»</span>
                    )}
                  </span>
                </div>
                <div className="divider" style={{ height: 1, background: 'var(--line)' }} />
                <div className="row gap-2">
                  <div className="scanbar grow" style={{ height: 48 }}>
                    <span className="scan-ic" style={{ width: 30, height: 30 }}>
                      <Icon n="barcode" s={16} w={2} />
                    </span>
                    <input
                      autoFocus
                      value={code}
                      onChange={(e) => setCode(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && submitCode()}
                      placeholder="امسح باركود الصنف"
                    />
                  </div>
                  <div className="input-group" style={{ width: 110 }}>
                    <input
                      className="input num"
                      style={{
                        height: 48,
                        textAlign: 'center',
                        fontSize: 18,
                        fontWeight: 600,
                      }}
                      value={qty}
                      onChange={(e) => setQty(toAsciiNum(e.target.value))}
                      aria-label="الكمية"
                    />
                  </div>
                  <button className="btn btn-primary" style={{ height: 48 }} onClick={submitCode}>
                    تسجيل
                  </button>
                </div>
                <div className="row gap-2">
                  <Api m="POST" path={`/pos/stocktakes/${session.id}/scan`} />
                  <span className="fs-12 t-3 ltr mono">{'{ barcode, qty | qty_words }'}</span>
                </div>
              </div>
            </div>
            {lp && (
              <div
                className="last-scan"
                key={last.id + '-' + last.qty}
                style={{ animation: 'popIn .3s both' }}
              >
                <PImg p={lp} size="sm" />
                <div className="grow">
                  <div className="fs-12 t-3">
                    آخر تسجيل{' '}
                    {last.via === 'voice' ? (
                      <span className="badge b-acc" style={{ height: 20 }}>
                        <Icon n="mic" s={11} />
                        «{last.words}»
                      </span>
                    ) : (
                      <span className="badge b-neutral" style={{ height: 20 }}>
                        <Icon n="barcode" s={11} />
                        باركود
                      </span>
                    )}
                  </div>
                  <div className="fs-16 fw-5">{lp.name}</div>
                  <div className="mono t-3" style={{ fontSize: 11 }}>
                    {lp.sku}
                  </div>
                </div>
                <div className="col" style={{ alignItems: 'flex-end' }}>
                  <span className="big-qty">{fmt(last.qty)}</span>
                  <span className="fs-12 t-3">العدد الحالي</span>
                </div>
              </div>
            )}
            <div className="card" style={{ overflow: 'hidden' }}>
              <div className="card-head">
                <h3>نطاق الجرد</h3>
                <span className="meta">النظام لا يعرض الرصيد الدفتري أثناء العد</span>
              </div>
              <table className="tbl">
                <thead>
                  <tr>
                    <th>الصنف</th>
                    <th>الكود</th>
                    <th className="n">المعدود</th>
                    <th></th>
                  </tr>
                </thead>
                <tbody>
                  {scope.map((p) => (
                    <tr key={p.id} className={last.id === p.id ? 'selected' : ''}>
                      <td>
                        <div className="row gap-3">
                          <PImg p={p} size="xs" />
                          <span className="fw-5">{p.name}</span>
                        </div>
                      </td>
                      <td>
                        <span className="mono">{p.sku}</span>
                      </td>
                      <td className="n fs-16 fw-6">
                        {counts[p.id] != null ? fmt(counts[p.id]) : <span className="t-3">—</span>}
                      </td>
                      <td>
                        {counts[p.id] != null ? (
                          <span className="badge b-ok">
                            <span className="dot" />
                            تم العد
                          </span>
                        ) : (
                          <span className="badge b-neutral">لم يُعد</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
          <div className="card" style={{ position: 'sticky', top: 0 }}>
            <div className="card-head">
              <h3>سجل المسح</h3>
              <span className="meta">آخر {fmt(log.length)}</span>
            </div>
            <div className="col" style={{ padding: '6px 10px 10px' }}>
              {log.map((l, i) => {
                const p = posMockService.getProductById(l.id);
                return (
                  <div
                    key={i}
                    className="row gap-3"
                    style={{
                      padding: '10px 6px',
                      borderBottom: i < log.length - 1 ? '1px solid var(--line)' : 0,
                    }}
                  >
                    <span
                      className="kpi-icon"
                      style={{
                        width: 30,
                        height: 30,
                        background:
                          l.via === 'voice' ? 'var(--acc-soft)' : 'var(--bg-sunken)',
                        color: l.via === 'voice' ? 'var(--acc)' : 'var(--text-2)',
                      }}
                    >
                      <Icon n={l.via === 'voice' ? 'mic' : 'barcode'} s={14} />
                    </span>
                    <div className="grow" style={{ minWidth: 0 }}>
                      <div className="fs-13 fw-5 truncate">{p?.name}</div>
                      <div className="fs-12 t-3">
                        {l.words ? `«${l.words}»` : 'مسح باركود'} ·{' '}
                        <span className="num">{l.t}</span>
                      </div>
                    </div>
                    <b className="num t-ok">+{fmt(l.add)}</b>
                  </div>
                );
              })}
            </div>
            <div style={{ padding: 14, borderTop: '1px solid var(--line)' }}>
              <button
                className="btn btn-secondary"
                style={{ width: '100%' }}
                onClick={() => toast('تم إرسال مسودة الجرد للمراجعة')}
              >
                إنهاء الجرد وإرساله للمراجعة
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}import React, { useState, useEffect } from 'react';
import { Icon } from '../ui/Icons';
import { fmt } from '../ui/SharedUI';
import { ReceiveTab } from './ReceiveTab';
import { RequestTab } from './RequestTab';
import { posMockService } from '../../services/pos-mock.service';
import type { Branch, StockTransfer } from '../../types/pos.types';

interface TransfersPageProps {
  toast: (msg: string, tone?: 'ok' | 'bad') => void;
  branch?: Branch | null;
}

export function TransfersPage({ toast, branch }: TransfersPageProps) {
  const [tab, setTab] = useState<'receive' | 'request'>('receive');
  const [transfers, setTransfers] = useState<StockTransfer[]>([]);

  const loadTransfers = () => {
    posMockService.getTransfersIn().then(setTransfers);
  };

  useEffect(() => {
    loadTransfers();
    const unsub = posMockService.subscribe(loadTransfers);
    return unsub;
  }, []);

  return (
    <div className="page" data-screen-label="09 Transfers">
      <div className="page-in page-enter">
        <div className="page-title">
          <div>
            <h1>التحويلات بين الفروع</h1>
            <p>
              اطلب بضاعة من المخزن أو فرع آخر، واستلم الشحنات الواردة لـ
              {branch?.name || 'فرع مدينة نصر'}.
            </p>
          </div>
        </div>
        <div className="tabs" style={{ marginBottom: 18 }}>
          <button
            aria-selected={tab === 'receive'}
            onClick={() => setTab('receive')}
          >
            <Icon n="truck" s={16} />
            استلام شحنة واردة
            <span className="tab-count">{fmt(transfers.length)}</span>
          </button>
          <button
            aria-selected={tab === 'request'}
            onClick={() => setTab('request')}
          >
            <Icon n="plus" s={16} />
            طلب تحويل وارد للفرع
          </button>
        </div>
        {tab === 'receive' ? (
          <ReceiveTab toast={toast} />
        ) : (
          <RequestTab toast={toast} branch={branch} />
        )}
      </div>
    </div>
  );
}import React from 'react';
import { Icon } from '../ui/Icons';
import { Kbd } from '../ui/SharedUI';
import type { AppScreen, Branch, CashierUser, PosShift } from '../../types/pos.types';

interface PosHeaderProps {
  currentScreen: AppScreen;
  onScreenChange: (s: AppScreen) => void;
  branch: Branch | null;
  cashier: CashierUser | null;
  shift: PosShift | null;
  onOpenCloseShift: () => void;
  onOpenReturns: () => void;
  isDark: boolean;
  onToggleDark: () => void;
}

export function PosHeader({
  currentScreen,
  onScreenChange,
  branch,
  cashier,
  shift,
  onOpenCloseShift,
  onOpenReturns,
  isDark,
  onToggleDark,
}: PosHeaderProps) {
  return (
    <header className="ph">
      <div className="brand-mark">
        <Icon n="bag" s={20} w={2} />
      </div>
      <div className="ph-meta">
        <b>الفريد</b>
        <span>{branch?.name || 'فرع مدينة نصر'}</span>
      </div>
      <div className="ph-sep" />
      <nav className="ph-nav" aria-label="شاشات نقطة البيع">
        <button
          aria-current={currentScreen === 'terminal' ? 'page' : undefined}
          onClick={() => onScreenChange('terminal')}
        >
          <Icon n="pos" s={16} />
          <span className="lbl">نقطة البيع</span>
        </button>
        <button
          aria-current={currentScreen === 'stock' ? 'page' : undefined}
          onClick={() => onScreenChange('stock')}
        >
          <Icon n="box" s={16} />
          <span className="lbl">المخزون</span>
        </button>
        <button
          aria-current={currentScreen === 'transfers' ? 'page' : undefined}
          onClick={() => onScreenChange('transfers')}
        >
          <Icon n="truck" s={16} />
          <span className="lbl">التحويلات</span>
        </button>
        <button
          aria-current={currentScreen === 'stocktake' ? 'page' : undefined}
          onClick={() => onScreenChange('stocktake')}
        >
          <Icon n="stock" s={16} />
          <span className="lbl">الجرد</span>
        </button>
      </nav>

      <div className="ms-auto row gap-3">
        <span className="conn" title="حالة الاتصال بالسيرفر">
          <i
            style={{
              width: 7,
              height: 7,
              borderRadius: 99,
              background: 'var(--ok)',
              boxShadow: '0 0 0 2px var(--ok-bg)',
            }}
          />
          متصل
        </span>

        {shift && (
          <button
            className="shift-pill"
            onClick={onOpenCloseShift}
            title="انقر لإغلاق الوردية وجرد النقدية"
          >
            <span className="live" />
            <span>وردية #{shift.shift_number}</span>
            <Icon n="lock" s={13} className="t-3" />
          </button>
        )}

        <button
          className="btn btn-secondary btn-sm"
          onClick={onOpenReturns}
          title="مرتجع / استبدال (F8)"
        >
          <Icon n="ret" s={14} />
          <span>مرتجع</span>
          <Kbd>F8</Kbd>
        </button>

        <button
          className="icon-btn"
          onClick={onToggleDark}
          aria-label={isDark ? 'الوضع النهاري' : 'الوضع الليلي'}
          title={isDark ? 'الوضع النهاري' : 'الوضع الليلي'}
        >
          <Icon n={isDark ? 'sun' : 'moon'} s={17} />
        </button>

        <div className="ph-sep" />

        <div className="row gap-2" style={{ fontSize: 13 }}>
          <span
            className="avatar"
            style={{ width: 32, height: 32, fontSize: 12, background: 'var(--bg-sunken)' }}
          >
            {cashier?.initials || 'أس'}
          </span>
          <div className="col hide-mobile" style={{ lineHeight: 1.2 }}>
            <span className="fw-6">{cashier?.name || 'أحمد سمير'}</span>
            <span className="fs-12 t-3">{cashier?.role || 'كاشير أول'}</span>
          </div>
        </div>
      </div>
    </header>
  );
}import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom';
import { Icon } from '../ui/Icons';
import { egp, fmt, PImg, Api, Empty, Seg, Check, Search, useEsc } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { PastSale, PosProduct } from '../../types/pos.types';

interface ReturnModalProps {
  open: boolean;
  onClose: () => void;
  toast: (msg: string, tone?: 'ok' | 'bad') => void;
}

export function ReturnModal({ open, onClose, toast }: ReturnModalProps) {
  const [num, setNum] = useState<string>('');
  const [sale, setSale] = useState<PastSale | null>(null);
  const [err, setErr] = useState<string>('');
  const [mode, setMode] = useState<'return' | 'exchange'>('return');
  const [sel, setSel] = useState<Record<number, { qty: number; to: 'on_hand' | 'damaged' }>>({});
  const [repl, setRepl] = useState<{ id: number; qty: number }[]>([]);
  const [rq, setRq] = useState<string>('');
  const [busy, setBusy] = useState<boolean>(false);
  const [allProducts, setAllProducts] = useState<PosProduct[]>([]);

  useEffect(() => {
    if (open) {
      setNum('');
      setSale(null);
      setErr('');
      setMode('return');
      setSel({});
      setRepl([]);
      setRq('');
      setBusy(false);
      posMockService.getProducts().then(setAllProducts);
    }
  }, [open]);

  useEsc(onClose, open);
  if (!open) return null;

  const find = async () => {
    if (!num.trim()) return;
    const s = await posMockService.getPastSale(num);
    if (s) {
      setSale(s);
      setErr('');
    } else {
      setSale(null);
      setErr('لم يتم العثور على فاتورة بهذا الرقم في الفرع');
    }
  };

  const loadExample = async () => {
    const s = await posMockService.getPastSale('POS-NSR-10233');
    if (s) {
      setNum('POS-NSR-10233');
      setSale(s);
      setErr('');
    }
  };

  const retTotal = sale
    ? sale.items.reduce((s, i) => s + (sel[i.id]?.qty || 0) * i.price, 0)
    : 0;

  const replTotal = repl.reduce((s, r) => {
    const p = posMockService.getProductById(r.id);
    return s + (p?.price || 0) * r.qty;
  }, 0);

  const net = replTotal - retTotal;
  const anySel = Object.values(sel).some((v) => v.qty > 0);
  const canSubmit = anySel && (mode === 'return' || repl.length > 0) && !busy;

  const results = rq
    ? allProducts
        .filter(
          (p) =>
            p.name.includes(rq) ||
            p.sku.toLowerCase().includes(rq.toLowerCase())
        )
        .slice(0, 4)
    : [];

  const handleSubmit = async () => {
    if (!canSubmit || !sale) return;
    setBusy(true);
    try {
      const returnPayload = Object.entries(sel)
        .filter(([, v]) => v.qty > 0)
        .map(([id, v]) => ({
          id: Number(id),
          qty: v.qty,
          return_to: v.to,
        }));

      if (mode === 'return') {
        await posMockService.processReturn(sale.id, returnPayload);
        toast('تم تسجيل المرتجع وتحديث المخزون');
      } else {
        await posMockService.processExchange(sale.id, returnPayload, repl, net);
        toast('تم الاستبدال وإصدار فاتورة جديدة');
      }
      onClose();
    } finally {
      setBusy(false);
    }
  };

  return ReactDOM.createPortal(
    <div
      dir="rtl"
      className={document.querySelector('.app')?.classList.contains('theme-dark') ? 'theme-dark' : ''}
    >
      <div className="overlay" onClick={onClose} />
      <div
        className="modal"
        style={{ width: 'min(920px, calc(100vw - 32px))' }}
        data-screen-label="07 Return & Exchange"
        role="dialog"
        aria-modal="true"
      >
        <div className="pop">
          <div
            className="row gap-3"
            style={{ padding: '18px 22px', borderBottom: '1px solid var(--line)' }}
          >
            <div className="grow col">
              <h3 className="fs-16">مرتجع / استبدال</h3>
              <span className="perm">
                <Icon n="shield" s={12} />
                pos.sales.refund
              </span>
            </div>
            <Seg
              value={mode}
              onChange={setMode}
              options={[
                { value: 'return', label: 'إرجاع فقط' },
                { value: 'exchange', label: 'استبدال بصنف آخر' },
              ]}
            />
            <button className="icon-btn sm" onClick={onClose} aria-label="إغلاق">
              <Icon n="x" s={16} />
            </button>
          </div>

          <div
            style={{
              padding: '18px 22px',
              display: 'flex',
              flexDirection: 'column',
              gap: 16,
            }}
          >
            <div className="ret-head">
              <div className="scanbar grow" style={{ height: 48 }}>
                <span className="scan-ic" style={{ width: 30, height: 30 }}>
                  <Icon n="barcode" s={16} w={2} />
                </span>
                <input
                  autoFocus
                  value={num}
                  onChange={(e) => setNum(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && find()}
                  placeholder="امسح باركود الإيصال أو اكتب رقم الفاتورة (order_number)"
                  className="ltr"
                  style={{ textAlign: 'right' }}
                />
              </div>
              <button className="btn btn-primary" style={{ height: 48 }} onClick={find}>
                بحث
              </button>
              {!sale && (
                <button className="btn btn-ghost" style={{ height: 48 }} onClick={loadExample}>
                  مثال
                </button>
              )}
            </div>
            {err && (
              <div className="banner b-bad">
                <Icon n="alert" s={16} />
                {err}
              </div>
            )}

            {!sale ? (
              <Empty
                icon="ret"
                title="ابدأ بمسح إيصال البيع الأصلي"
                body="سيتم عرض بنود الفاتورة لتختار الأصناف والكميات المرتجعة وحالتها."
              />
            ) : (
              <>
                <div className="order-meta">
                  <div>
                    <span>رقم الفاتورة</span>
                    <b className="mono">{sale.number}</b>
                  </div>
                  <div>
                    <span>التاريخ</span>
                    <b>{sale.date}</b>
                  </div>
                  <div>
                    <span>العميل</span>
                    <b>{sale.customer}</b>
                  </div>
                  <div>
                    <span>الدفع / الكاشير</span>
                    <b>
                      {sale.method} · {sale.cashier}
                    </b>
                  </div>
                </div>
                <div className="card" style={{ overflow: 'hidden' }}>
                  <table className="tbl">
                    <thead>
                      <tr>
                        <th style={{ width: 40 }}></th>
                        <th>الصنف</th>
                        <th className="n">السعر</th>
                        <th className="n">المباع</th>
                        <th style={{ textAlign: 'center' }}>كمية الإرجاع</th>
                        <th>حالة الصنف الراجع</th>
                        <th className="n">المسترد</th>
                      </tr>
                    </thead>
                    <tbody>
                      {sale.items.map((i) => {
                        const p = posMockService.getProductById(i.id);
                        const s = sel[i.id] || { qty: 0, to: 'on_hand' };
                        const on = s.qty > 0;
                        const upd = (v: Partial<{ qty: number; to: 'on_hand' | 'damaged' }>) =>
                          setSel((x) => ({ ...x, [i.id]: { ...s, ...v } }));

                        return (
                          <tr key={i.id} className={on ? 'selected' : ''}>
                            <td>
                              <Check
                                on={on}
                                onChange={(v) => upd({ qty: v ? 1 : 0 })}
                              />
                            </td>
                            <td>
                              <div className="row gap-2">
                                <PImg p={p} size="xs" />
                                <div>
                                  <div className="fs-13 fw-5">{p?.name}</div>
                                  <div className="mono t-3" style={{ fontSize: 11 }}>
                                    {p?.sku}
                                  </div>
                                </div>
                              </div>
                            </td>
                            <td className="n">{egp(i.price)}</td>
                            <td className="n">{fmt(i.qty)}</td>
                            <td style={{ textAlign: 'center' }}>
                              <div className="stepper-q" style={{ opacity: on ? 1 : 0.5 }}>
                                <button
                                  onClick={() => upd({ qty: Math.min(i.qty, s.qty + 1) })}
                                >
                                  <Icon n="plus" s={13} />
                                </button>
                                <span>{fmt(s.qty)}</span>
                                <button
                                  onClick={() => upd({ qty: Math.max(0, s.qty - 1) })}
                                >
                                  <Icon n="minus" s={13} />
                                </button>
                              </div>
                            </td>
                            <td>
                              <div
                                className="seg"
                                style={{
                                  opacity: on ? 1 : 0.45,
                                  pointerEvents: on ? 'auto' : 'none',
                                }}
                              >
                                <button
                                  aria-pressed={s.to === 'on_hand'}
                                  onClick={() => upd({ to: 'on_hand' })}
                                >
                                  <span className="row gap-1">
                                    <i
                                      style={{
                                        width: 7,
                                        height: 7,
                                        borderRadius: 9,
                                        background: 'var(--ok)',
                                      }}
                                    />
                                    سليم
                                  </span>
                                </button>
                                <button
                                  aria-pressed={s.to === 'damaged'}
                                  onClick={() => upd({ to: 'damaged' })}
                                >
                                  <span className="row gap-1">
                                    <i
                                      style={{
                                        width: 7,
                                        height: 7,
                                        borderRadius: 9,
                                        background: 'var(--bad)',
                                      }}
                                    />
                                    تالف
                                  </span>
                                </button>
                              </div>
                            </td>
                            <td className="n fw-6">{on ? egp(s.qty * i.price) : '—'}</td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>

                {mode === 'exchange' && (
                  <div
                    className="card card-pad col gap-3"
                    style={{ background: 'var(--bg-sunken)' }}
                  >
                    <div className="row between">
                      <span className="section-label">الصنف البديل</span>
                      <span className="fs-12 t-3">
                        ينفَّذ الإرجاع والفاتورة الجديدة في عملية واحدة
                      </span>
                    </div>
                    <div style={{ position: 'relative' }}>
                      <Search
                        value={rq}
                        onChange={setRq}
                        placeholder="ابحث عن الصنف البديل بالاسم أو الكود…"
                      />
                      {results.length > 0 && (
                        <div className="scan-results" style={{ maxHeight: 240 }}>
                          {results.map((p) => (
                            <button
                              key={p.id}
                              className="scan-row"
                              onClick={() => {
                                setRepl((r) =>
                                  r.find((x) => x.id === p.id)
                                    ? r.map((x) =>
                                        x.id === p.id ? { ...x, qty: x.qty + 1 } : x
                                      )
                                    : [...r, { id: p.id, qty: 1 }]
                                );
                                setRq('');
                              }}
                            >
                              <PImg p={p} size="xs" />
                              <span className="grow fs-13">{p.name}</span>
                              <span className="badge b-neutral">رصيد {fmt(p.stock)}</span>
                              <span className="price">{egp(p.price)}</span>
                            </button>
                          ))}
                        </div>
                      )}
                    </div>
                    {repl.map((r) => {
                      const p = posMockService.getProductById(r.id);
                      if (!p) return null;
                      return (
                        <div
                          key={r.id}
                          className="row gap-3"
                          style={{
                            background: 'var(--bg-card)',
                            padding: 10,
                            borderRadius: 12,
                            border: '1px solid var(--line)',
                          }}
                        >
                          <PImg p={p} size="xs" />
                          <span className="grow fs-13 fw-5">{p.name}</span>
                          <div className="stepper-q">
                            <button
                              onClick={() =>
                                setRepl((x) =>
                                  x.map((y) => (y.id === r.id ? { ...y, qty: y.qty + 1 } : y))
                                )
                              }
                            >
                              <Icon n="plus" s={13} />
                            </button>
                            <span>{fmt(r.qty)}</span>
                            <button
                              onClick={() =>
                                setRepl((x) =>
                                  r.qty > 1
                                    ? x.map((y) =>
                                        y.id === r.id ? { ...y, qty: y.qty - 1 } : y
                                      )
                                    : x.filter((y) => y.id !== r.id)
                                )
                              }
                            >
                              <Icon n="minus" s={13} />
                            </button>
                          </div>
                          <span className="price" style={{ width: 80, textAlign: 'end' }}>
                            {egp(p.price * r.qty)}
                          </span>
                        </div>
                      );
                    })}
                    {repl.length === 0 && (
                      <div className="fs-13 t-3">لم يتم اختيار صنف بديل بعد.</div>
                    )}
                  </div>
                )}
              </>
            )}
          </div>

          {sale && (
            <div
              className="row gap-3"
              style={{
                padding: '14px 22px',
                borderTop: '1px solid var(--line)',
                background: 'var(--bg-card)',
              }}
            >
              {mode === 'return' ? (
                <div
                  className="net grow"
                  style={{
                    background: 'var(--bad-bg)',
                    color: 'var(--bad)',
                    padding: '10px 14px',
                  }}
                >
                  <Icon n="cash" s={18} />
                  <span className="fs-13 fw-6">رد نقدية للعميل</span>
                  <span className="ms-auto display fs-20 fw-6 num">{egp(retTotal)} ج</span>
                </div>
              ) : (
                <div
                  className="net grow"
                  style={{
                    background:
                      !anySel || !repl.length
                        ? 'var(--bg-sunken)'
                        : net > 0
                        ? 'var(--ok-bg)'
                        : net < 0
                        ? 'var(--bad-bg)'
                        : 'var(--info-bg)',
                    color:
                      !anySel || !repl.length
                        ? 'var(--text-2)'
                        : net > 0
                        ? 'var(--ok)'
                        : net < 0
                        ? 'var(--bad)'
                        : 'var(--info)',
                    padding: '10px 14px',
                  }}
                >
                  <span className="fs-12 t-2" style={{ color: 'inherit', opacity: 0.8 }}>
                    مرتجع {egp(retTotal)} ← بديل {egp(replTotal)}
                  </span>
                  <span className="fs-13 fw-6">
                    {net > 0
                      ? 'تحصيل فرق من العميل'
                      : net < 0
                      ? 'رد فرق للعميل'
                      : 'بدون فروق'}
                  </span>
                  <span className="ms-auto display fs-20 fw-6 num">{egp(Math.abs(net))} ج</span>
                </div>
              )}
              <Api m="POST" path={`/pos/sales/${sale.id}/${mode}`} />
              <button
                className="btn btn-primary btn-lg"
                disabled={!canSubmit}
                onClick={handleSubmit}
              >
                <Icon n="check" s={16} w={2.4} />
                {busy
                  ? 'جارِ التنفيذ…'
                  : mode === 'return'
                  ? 'تأكيد المرتجع'
                  : 'تأكيد الاستبدال'}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom';
import { Icon } from '../ui/Icons';
import { egp, fmt, MoneyInput, Api, Field, cx, useEsc } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { PosShift, ShiftStats } from '../../types/pos.types';

interface CloseShiftModalProps {
  open: boolean;
  onClose: () => void;
  shift: PosShift | null;
  onClosed: (shift: PosShift) => void;
}

export function CloseShiftModal({ open, onClose, shift, onClosed }: CloseShiftModalProps) {
  const [actual, setActual] = useState<string>('');
  const [notes, setNotes] = useState<string>('');
  const [busy, setBusy] = useState<boolean>(false);
  const [stats, setStats] = useState<ShiftStats>({
    cashSales: 7360,
    cardSales: 2840,
    returns: 450,
    expenses: 180,
    invoices: 23,
  });

  useEffect(() => {
    if (open) {
      setActual('');
      setNotes('');
      setBusy(false);
      posMockService.getShiftStats().then(setStats);
    }
  }, [open]);

  useEsc(onClose, open);
  if (!open || !shift) return null;

  const expected = shift.opening_cash + stats.cashSales - stats.returns - stats.expenses;
  const has = actual !== '';
  const diff = Number(actual || 0) - expected;
  const state: 'idle' | 'ok' | 'over' | 'short' = !has
    ? 'idle'
    : Math.abs(diff) < 0.01
    ? 'ok'
    : diff > 0
    ? 'over'
    : 'short';

  const needNote = state === 'short' || state === 'over';
  const canSubmit = has && (!needNote || notes.trim().length >= 3) && !busy;

  const diffLabel = {
    idle: 'أدخل النقد الفعلي لحساب الفرق',
    ok: 'مطابق تمامًا',
    over: 'زيادة في الدرج',
    short: 'عجز في الدرج',
  }[state];

  const diffIcon = {
    idle: 'info',
    ok: 'check',
    over: 'arrowUpLeft',
    short: 'alert',
  }[state];

  const started = new Date(shift.opened_at);

  const handleSubmit = async () => {
    if (!canSubmit) return;
    setBusy(true);
    try {
      const closedShift = await posMockService.closeShift(Number(actual), notes);
      onClosed(closedShift);
    } finally {
      setBusy(false);
    }
  };

  return ReactDOM.createPortal(
    <div
      dir="rtl"
      className={document.querySelector('.app')?.classList.contains('theme-dark') ? 'theme-dark' : ''}
    >
      <div className="overlay" onClick={onClose} />
      <div
        className="modal"
        style={{ width: 'min(860px, calc(100vw - 32px))' }}
        data-screen-label="02 Close Shift"
        role="dialog"
        aria-modal="true"
      >
        <div className="pop">
          <div
            className="row between"
            style={{ padding: '18px 22px', borderBottom: '1px solid var(--line)' }}
          >
            <div className="col">
              <h3 className="fs-16">إغلاق الوردية وجرد النقدية</h3>
              <div className="fs-12 t-3 row gap-1">
                <span className="num ltr">{shift.shift_number}</span>
                <span className="dot-sep" />
                {shift.treasury.name}
                <span className="dot-sep" />
                بدأت{' '}
                <span className="num">
                  {started.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>
            </div>
            <button className="icon-btn sm" onClick={onClose} aria-label="إغلاق">
              <Icon n="x" s={16} />
            </button>
          </div>

          <div className="grid" style={{ gridTemplateColumns: '1fr 1fr' }}>
            <div
              style={{
                padding: '18px 22px',
                borderInlineEnd: '1px solid var(--line)',
                background: 'var(--bg-sunken)',
              }}
            >
              <div className="section-label" style={{ marginBottom: 6 }}>
                ملخص حركة النقدية
              </div>
              <div className="ledger">
                <div className="lr">
                  <span className="op base">·</span>
                  العهدة الافتتاحية
                  <span className="amt">{egp(shift.opening_cash)}</span>
                </div>
                <div className="lr">
                  <span className="op plus">+</span>
                  مبيعات نقدية <span className="t-3 fs-12">({fmt(stats.invoices)} فاتورة)</span>
                  <span className="amt">{egp(stats.cashSales)}</span>
                </div>
                <div className="lr">
                  <span className="op minus">−</span>
                  مرتجعات نقدية
                  <span className="amt">{egp(stats.returns)}</span>
                </div>
                <div className="lr">
                  <span className="op minus">−</span>
                  مصروفات نثرية
                  <span className="amt">{egp(stats.expenses)}</span>
                </div>
                <div className="lr" style={{ paddingTop: 14 }}>
                  <span className="op eq">=</span>
                  <b>النقد المتوقع بالدرج</b>
                  <span className="amt fs-20 fw-6">{egp(expected)}</span>
                </div>
              </div>
              <div
                className="row gap-2 fs-12 t-3"
                style={{
                  marginTop: 10,
                  padding: '10px 12px',
                  borderRadius: 12,
                  border: '1px dashed var(--line-strong)',
                }}
              >
                <Icon n="card" s={15} />
                مبيعات البطاقة <b className="num t-1">{egp(stats.cardSales)}</b> ج — لا تدخل في جرد الدرج
              </div>
            </div>

            <div style={{ padding: '18px 22px', display: 'flex', flexDirection: 'column', gap: 14 }}>
              <div className="col gap-2">
                <span className="fs-13 fw-5">النقد الفعلي بالدرج</span>
                <MoneyInput
                  value={actual}
                  onChange={setActual}
                  autoFocus
                  placeholder={String(expected)}
                />
                <div className="row gap-2">
                  <button className="note-chip" onClick={() => setActual(String(expected))}>
                    مطابق للمتوقع
                  </button>
                </div>
              </div>
              <div className={cx('diff', state)}>
                <span className="diff-ic">
                  <Icon n={diffIcon} s={18} w={2} />
                </span>
                <div className="col">
                  <span className="fs-12" style={{ opacity: 0.8 }}>
                    الفرق
                  </span>
                  <b className="fs-13">{diffLabel}</b>
                </div>
                <span className="v">
                  {has
                    ? (diff > 0 ? '+' : diff < 0 ? '−' : '') + egp(Math.abs(diff))
                    : '—'}
                </span>
              </div>
              <Field
                label={
                  <>
                    ملاحظات{' '}
                    {needNote ? (
                      <span className="t-bad fs-12">(مطلوبة لتبرير الفرق)</span>
                    ) : (
                      <span className="t-3 fs-12">(اختياري)</span>
                    )}
                  </>
                }
              >
                <textarea
                  className={cx('input', needNote && notes.trim().length < 3 && 'is-error')}
                  rows={3}
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  placeholder={
                    state === 'short'
                      ? `مثال: عجز ${egp(Math.abs(diff))} جنيه فرق فكة مع عميل`
                      : 'أي ملاحظات على الوردية…'
                  }
                />
              </Field>
            </div>
          </div>

          <div
            className="row gap-2"
            style={{ padding: '14px 22px', borderTop: '1px solid var(--line)' }}
          >
            <div className="row gap-2 fs-12 t-3 grow">
              <Icon n="info" s={14} />
              ستُرسل الوردية بحالة{' '}
              <span className="badge b-warn" style={{ height: 20 }}>
                بانتظار الاعتماد
              </span>
              <Api m="POST" path="/pos/shifts/close" />
            </div>
            <button className="btn btn-secondary" onClick={onClose}>
              رجوع للبيع
            </button>
            <button
              className="btn"
              style={{ background: 'var(--bad)', color: '#fff' }}
              disabled={!canSubmit}
              onClick={handleSubmit}
            >
              <Icon n="lock" s={16} />
              {busy ? 'جارِ الإغلاق…' : 'إغلاق الوردية وإرسالها للاعتماد'}
            </button>
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
}import React, { useState, useEffect } from 'react';
import { Icon } from '../ui/Icons';
import { egp, fmt, MoneyInput, Api } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { PosShift, Treasury, Branch, CashierUser } from '../../types/pos.types';

interface OpenShiftGateProps {
  onOpened: (shift: PosShift) => void;
}

export function OpenShiftGate({ onOpened }: OpenShiftGateProps) {
  const [treasury, setTreasury] = useState<number>(1);
  const [cash, setCash] = useState<string>('500');
  const [busy, setBusy] = useState<boolean>(false);
  const [treasuries, setTreasuries] = useState<Treasury[]>([]);
  const [branch, setBranch] = useState<Branch | null>(null);
  const [cashier, setCashier] = useState<CashierUser | null>(null);

  useEffect(() => {
    posMockService.getTreasuries().then((list) => {
      setTreasuries(list);
      const free = list.find((t) => t.state === 'free');
      if (free) setTreasury(free.id);
    });
    posMockService.getBranch().then(setBranch);
    posMockService.getCashier().then(setCashier);
  }, []);

  const amount = Number(cash || 0);
  const now = new Date();
  const hr = now.getHours();
  const greet = hr < 12 ? 'صباح الخير' : 'مساء الخير';

  const submit = async () => {
    if (!treasury || busy) return;
    setBusy(true);
    try {
      const opened = await posMockService.openShift(treasury, amount);
      onOpened(opened);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="gate" data-screen-label="01 Open Shift">
      <div className="gate-card" role="dialog" aria-modal="true" aria-label="فتح الوردية">
        <div className="welcome">
          <div className="row gap-3" style={{ position: 'relative', zIndex: 1 }}>
            <span className="avatar">{cashier?.initials || 'أس'}</span>
            <div className="grow">
              <div style={{ fontSize: 13, opacity: 0.85 }}>{greet}،</div>
              <div className="display" style={{ fontSize: 22, fontWeight: 500, lineHeight: 1.25 }}>
                {cashier?.name || 'أحمد سمير'}
              </div>
            </div>
            <div className="col" style={{ alignItems: 'flex-end', gap: 4 }}>
              <span className="badge" style={{ background: 'rgba(255,255,255,.18)', color: '#fff' }}>
                <Icon n="store" s={13} />
                {branch?.name || 'فرع مدينة نصر'}
              </span>
              <span style={{ fontSize: 12, opacity: 0.85 }} className="num">
                {now.toLocaleDateString('ar-EG', { weekday: 'long', day: 'numeric', month: 'long' })}
              </span>
            </div>
          </div>
          <div
            className="row gap-2"
            style={{
              position: 'relative',
              zIndex: 1,
              marginTop: 16,
              padding: '10px 12px',
              borderRadius: 12,
              background: 'rgba(0,0,0,.14)',
              fontSize: 12.5,
            }}
          >
            <Icon n="lock" s={15} />
            لا توجد وردية مفتوحة باسمك. افتح وردية لبدء البيع.
          </div>
        </div>

        <div style={{ padding: '20px 24px 8px', display: 'flex', flexDirection: 'column', gap: 18 }}>
          <div className="col gap-2">
            <div className="row between">
              <span className="fs-13 fw-5">درج النقدية</span>
              <span className="fs-12 t-3">
                {treasuries.filter((t) => t.state === 'free').length} متاح في الفرع
              </span>
            </div>
            <div className="tres" role="radiogroup">
              {treasuries.map((t) => (
                <button
                  key={t.id}
                  role="radio"
                  aria-checked={treasury === t.id}
                  disabled={t.state === 'busy'}
                  onClick={() => setTreasury(t.id)}
                >
                  <div className="row between">
                    <Icon
                      n="cash"
                      s={18}
                      style={{ color: treasury === t.id ? 'var(--acc)' : 'var(--text-3)' }}
                    />
                    {t.state === 'busy' ? (
                      <span className="badge b-neutral" style={{ height: 20, fontSize: 11 }}>
                        مشغول
                      </span>
                    ) : (
                      <span className="radio-dot" />
                    )}
                  </div>
                  <div className="fs-13 fw-6">{t.name}</div>
                  <div className="fs-12 t-3 truncate" style={{ lineHeight: 1.3 }}>
                    {t.last}
                  </div>
                </button>
              ))}
            </div>
          </div>

          <div className="col gap-2">
            <div className="row between">
              <span className="fs-13 fw-5">العهدة الافتتاحية</span>
              <button className="fs-12 t-3" onClick={() => setCash('')}>
                مسح
              </button>
            </div>
            <MoneyInput value={cash} onChange={setCash} autoFocus onEnter={submit} />
            <div className="denoms">
              {[200, 500, 1000].map((v) => (
                <button key={v} className="denom" onClick={() => setCash(String(amount + v))}>
                  +{fmt(v)}
                  <small>ج</small>
                </button>
              ))}
              <button className="denom ghost" onClick={() => setCash('500')}>
                نفس أمس
              </button>
            </div>
          </div>
        </div>

        <div style={{ padding: '16px 24px 22px' }}>
          <button
            className="pay-btn"
            style={{ margin: 0, width: '100%' }}
            disabled={!treasury || busy}
            onClick={submit}
          >
            <span className="row gap-2">{busy ? 'جارِ فتح الوردية…' : 'فتح الوردية وبدء البيع'}</span>
            <span className="row gap-2">
              <span className="amt num">{egp(amount)}</span>
              <Icon n="arrowLeft" s={18} />
            </span>
          </button>
          <div className="api-block center" style={{ justifyContent: 'center' }}>
            <Api path="/api/v1/pos/shifts/current" /> <Api m="POST" path="/api/v1/pos/shifts/open" />
          </div>
        </div>
      </div>
    </div>
  );
}import React, { useState } from 'react';
import { CustomerBar } from './CustomerBar';
import { CartLine } from './CartLine';
import { Icon } from '../ui/Icons';
import { egp, fmt, Kbd, toAsciiNum } from '../ui/SharedUI';
import type { PosCartLine, Customer, CashierUser } from '../../types/pos.types';

interface CartProps {
  cart: PosCartLine[];
  setCart: React.Dispatch<React.SetStateAction<PosCartLine[]>>;
  customer: Customer | null;
  setCustomer: (c: Customer | null) => void;
  discount: number;
  setDiscount: (d: number) => void;
  onHold: () => void;
  onHeld: () => void;
  heldCount: number;
  onPay: () => void;
  onClear: () => void;
  lastAdded: { id: number; k: number } | null;
  toast: (msg: string, tone?: 'ok' | 'bad') => void;
  cashier?: CashierUser | null;
}

export function Cart({
  cart,
  setCart,
  customer,
  setCustomer,
  discount,
  setDiscount,
  onHold,
  onHeld,
  heldCount,
  onPay,
  onClear,
  lastAdded,
  toast,
  cashier,
}: CartProps) {
  const canOverride = cashier?.perms?.includes('pos.override_price') ?? true;
  const subtotal = cart.reduce((s, l) => s + l.listPrice * l.qty, 0);
  const lineAdj = cart.reduce((s, l) => s + (l.listPrice - l.price) * l.qty, 0);
  const total = Math.max(0, subtotal - lineAdj - discount);
  const items = cart.reduce((s, l) => s + l.qty, 0);
  const [discOpen, setDiscOpen] = useState(false);
  const [discVal, setDiscVal] = useState('');

  return (
    <aside className="cart">
      <CustomerBar customer={customer} setCustomer={setCustomer} toast={toast} />
      <div className="cart-head">
        <div className="row gap-2">
          <h3 className="fs-16">الفاتورة الحالية</h3>
          {items > 0 && <span className="badge b-neutral num">{fmt(items)} قطعة</span>}
        </div>
        {cart.length > 0 && (
          <button className="btn btn-ghost btn-sm" onClick={onClear}>
            <Icon n="trash" s={14} />
            مسح
          </button>
        )}
      </div>
      <div className="cart-list">
        {cart.length === 0 ? (
          <div className="empty" style={{ paddingTop: 56 }}>
            <div className="empty-ic">
              <Icon n="barcode" s={24} />
            </div>
            <h4>الفاتورة فارغة</h4>
            <p>امسح باركود صنف أو اضغط على أي صنف من الكتالوج لإضافته.</p>
            <div className="row gap-2 fs-12 t-3" style={{ marginTop: 8 }}>
              <Kbd>F2</Kbd> بحث <Kbd>F6</Kbd> المعلقة <Kbd>F8</Kbd> مرتجع
            </div>
          </div>
        ) : (
          cart.map((l) => (
            <CartLine
              key={l.id}
              l={l}
              canOverride={canOverride}
              flash={lastAdded?.id === l.id ? lastAdded.k : null}
              onQty={(q) =>
                setCart((c) => c.map((x) => (x.id === l.id ? { ...x, qty: q } : x)))
              }
              onPrice={(pr) =>
                setCart((c) => c.map((x) => (x.id === l.id ? { ...x, price: pr } : x)))
              }
              onRemove={() => setCart((c) => c.filter((x) => x.id !== l.id))}
            />
          ))
        )}
      </div>
      <div className="totals">
        <div className="r">
          <span>المجموع الفرعي</span>
          <b>{egp(subtotal)}</b>
        </div>
        {lineAdj !== 0 && (
          <div className="r">
            <span>تعديلات الأسعار</span>
            <b className="t-warn">−{egp(lineAdj)}</b>
          </div>
        )}
        <div className="r">
          <span className="row gap-2">
            الخصم{' '}
            {discOpen ? (
              <span className="row gap-1">
                <input
                  className="price-input"
                  autoFocus
                  value={discVal}
                  onChange={(e) => setDiscVal(toAsciiNum(e.target.value))}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      setDiscount(Math.min(Number(discVal || 0), subtotal));
                      setDiscOpen(false);
                    }
                  }}
                  onBlur={() => {
                    setDiscount(Math.min(Number(discVal || 0), subtotal));
                    setDiscOpen(false);
                  }}
                  placeholder="0"
                />
              </span>
            ) : (
              <button
                className="t-acc fs-12 fw-6"
                onClick={() => {
                  setDiscVal(discount ? String(discount) : '');
                  setDiscOpen(true);
                }}
                disabled={!cart.length}
              >
                {discount ? 'تعديل' : '+ إضافة'}
              </button>
            )}
          </span>
          <b className={discount ? 't-ok' : ''}>{discount ? '−' + egp(discount) : '٠'}</b>
        </div>
        <div className="grand">
          <span className="fs-13 t-2">الإجمالي</span>
          <span className="v">
            {egp(total)}
            <small>ج.م</small>
          </span>
        </div>
      </div>
      <div className="actions">
        <button className="btn btn-secondary" disabled={!cart.length} onClick={onHold}>
          <Icon n="pause" s={15} />
          تعليق
        </button>
        <button className="btn btn-secondary" onClick={onHeld}>
          <Icon n="inbox" s={16} />
          المعلقة
          {heldCount > 0 && <span className="badge-count">{fmt(heldCount)}</span>}
          <Kbd>F6</Kbd>
        </button>
        <button
          className="btn btn-danger"
          disabled={!cart.length}
          onClick={onClear}
          aria-label="إلغاء ومسح الفاتورة"
          title="إلغاء ومسح الفاتورة"
        >
          <Icon n="x" s={18} />
        </button>
      </div>
      <button className="pay-btn" disabled={!cart.length} onClick={onPay}>
        <span className="row gap-2">
          إتمام الدفع{' '}
          <span
            className="kbd"
            style={{
              background: 'rgba(255,255,255,.15)',
              borderColor: 'rgba(255,255,255,.35)',
              color: '#fff',
            }}
          >
            Space
          </span>
        </span>
        <span className="amt num">{egp(total)} ج</span>
      </button>
    </aside>
  );
}import React, { useState } from 'react';
import { Icon } from '../ui/Icons';
import { egp, fmt, PImg, cx, toAsciiNum } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { PosCartLine } from '../../types/pos.types';

interface CartLineProps {
  l: PosCartLine;
  onQty: (q: number) => void;
  onRemove: () => void;
  onPrice: (price: number) => void;
  canOverride?: boolean;
  flash?: boolean | number | null;
}

export function CartLine({ l, onQty, onRemove, onPrice, canOverride, flash }: CartLineProps) {
  const p = posMockService.getProductById(l.id);
  const [edit, setEdit] = useState(false);
  const [val, setVal] = useState(String(l.price));
  const overridden = l.price !== l.listPrice;

  if (!p) return null;

  return (
    <div className={cx('line', flash ? 'flash' : '')}>
      <PImg p={p} size="sm" />
      <div style={{ minWidth: 0 }}>
        <div className="line-name truncate">{p.name}</div>
        <div className="line-sub">
          {edit ? (
            <input
              className="price-input"
              autoFocus
              value={val}
              onChange={(e) => setVal(toAsciiNum(e.target.value))}
              onBlur={() => {
                onPrice(Number(val || l.listPrice));
                setEdit(false);
              }}
              onKeyDown={(e) => {
                if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
                if (e.key === 'Escape') {
                  setVal(String(l.price));
                  setEdit(false);
                }
              }}
            />
          ) : (
            <span
              className={cx('num', canOverride && 'price-edit')}
              onClick={() => {
                if (canOverride) {
                  setVal(String(l.price));
                  setEdit(true);
                }
              }}
              title={canOverride ? 'تعديل السعر (pos.override_price)' : undefined}
            >
              {egp(l.price)} ج
            </span>
          )}
          {overridden && !edit && (
            <>
              <s className="num">{egp(l.listPrice)}</s>
              <span
                className="badge b-warn"
                style={{ height: 18, fontSize: 10.5, padding: '0 6px' }}
              >
                سعر معدّل
              </span>
            </>
          )}
          {l.qty > p.stock && (
            <span
              className="badge b-bad"
              style={{ height: 18, fontSize: 10.5, padding: '0 6px' }}
            >
              الرصيد {fmt(p.stock)}
            </span>
          )}
        </div>
      </div>
      <div className="col" style={{ alignItems: 'flex-end', gap: 6 }}>
        <div className="row gap-1">
          <div className="stepper-q">
            <button onClick={() => onQty(l.qty + 1)} aria-label="زيادة">
              <Icon n="plus" s={14} />
            </button>
            <span>{fmt(l.qty)}</span>
            <button
              onClick={() => (l.qty > 1 ? onQty(l.qty - 1) : onRemove())}
              aria-label="نقص"
            >
              <Icon n="minus" s={14} />
            </button>
          </div>
          <button
            className="icon-btn sm"
            onClick={onRemove}
            aria-label="حذف"
            style={{ color: 'var(--text-3)' }}
          >
            <Icon n="trash" s={15} />
          </button>
        </div>
        <span className="price fs-14">{egp(l.price * l.qty)}</span>
      </div>
    </div>
  );
}import React, { useState, useEffect } from 'react';
import { ScanBar } from './ScanBar';
import { egp, fmt, PImg, cx } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { PosProduct, ProductCategory, Customer, PosCartLine } from '../../types/pos.types';

interface CatalogProps {
  cart: PosCartLine[];
  customer: Customer | null;
  onAdd: (p: PosProduct) => void;
  scanRef?: React.RefObject<HTMLInputElement | null>;
}

export function Catalog({ cart, customer, onAdd, scanRef }: CatalogProps) {
  const [cat, setCat] = useState<string>('all');
  const [categories, setCategories] = useState<ProductCategory[]>([]);
  const [products, setProducts] = useState<PosProduct[]>([]);

  const loadData = () => {
    posMockService.getCategories().then(setCategories);
    posMockService.getProducts().then(setProducts);
  };

  useEffect(() => {
    loadData();
    const unsub = posMockService.subscribe(loadData);
    return unsub;
  }, []);

  const list = products.filter((p) => cat === 'all' || p.cat === cat);
  const qtyOf = (id: number) => cart.find((l) => l.id === id)?.qty || 0;

  return (
    <div className="catalog">
      <ScanBar customer={customer} onAdd={onAdd} inputRef={scanRef} products={products} />
      <div className="cats">
        {categories.map((c) => (
          <button
            key={c.id}
            className="cat"
            aria-pressed={cat === c.id}
            onClick={() => setCat(c.id)}
          >
            {c.name}
            <span className="count">
              {fmt(
                c.id === 'all'
                  ? products.length
                  : products.filter((p) => p.cat === c.id).length
              )}
            </span>
          </button>
        ))}
      </div>
      <div className="grid-scroll">
        <div className="pgrid">
          {list.map((p) => {
            const q = qtyOf(p.id);
            const price = customer?.tier === 'wholesale' ? p.wholesale : p.price;
            return (
              <button
                key={p.id}
                className={cx('pcard', p.stock === 0 && 'out')}
                onClick={() => p.stock > 0 && onAdd(p)}
                disabled={p.stock === 0}
              >
                {q > 0 && <span className="qty-tag">{fmt(q)}</span>}
                {p.stock === 0 ? (
                  <span className="stock-tag badge b-bad" style={{ height: 22 }}>
                    نفد
                  </span>
                ) : p.stock <= p.reorder ? (
                  <span className="stock-tag badge b-warn" style={{ height: 22 }}>
                    باقي {fmt(p.stock)}
                  </span>
                ) : null}
                <PImg p={p} />
                <div style={{ padding: '0 4px' }}>
                  <div className="pcard-name">{p.name}</div>
                  <div className="mono t-3" style={{ fontSize: 11 }}>
                    {p.sku}
                  </div>
                </div>
                <div className="pcard-foot">
                  <span className="price fs-16">
                    {egp(price)}
                    <small>ج</small>
                  </span>
                  {customer?.tier === 'wholesale' && (
                    <span className="badge b-info" style={{ height: 20, fontSize: 11 }}>
                      جملة
                    </span>
                  )}
                </div>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}import React, { useState, useRef, useEffect } from 'react';
import { Icon } from '../ui/Icons';
import { fmt, cx, toAsciiNum, Field, Seg, Modal, useOutside } from '../ui/SharedUI';
import { posMockService } from '../../services/pos-mock.service';
import type { Customer } from '../../types/pos.types';

interface CustomerBarProps {
  customer: Customer | null;
  setCustomer: (c: Customer | null) => void;
  toast: (msg: string, tone?: 'ok' | 'bad') => void;
}

export function CustomerBar({ customer, setCustomer, toast }: CustomerBarProps) {
  const [q, setQ] = useState('');
  const [open, setOpen] = useState(false);
  const [quick, setQuick] = useState(false);
  const [nw, setNw] = useState<{ name: string; phone: string; tier: 'retail' | 'wholesale' }>({
    name: '',
    phone: '',
    tier: 'retail',
  });
  const [customers, setCustomers] = useState<Customer[]>([]);
  const ref = useRef<HTMLDivElement>(null);
  useOutside(ref, () => setOpen(false));

  useEffect(() => {
    posMockService.getCustomers().then(setCustomers);
  }, []);

  const res = customers.filter(
    (c) => !q || c.phone.includes(q) || c.name.includes(q)
  );

  const handleCreateCustomer = async () => {
    if (!nw.name || nw.phone.length < 10) return;
    const created = await posMockService.createQuickCustomer({
      name: nw.name,
      phone: nw.phone,
      tier: nw.tier,
    });
    setCustomer(created);
    setQuick(false);
    setNw({ name: '', phone: '', tier: 'retail' });
    toast('تم تسجيل العميل وربطه بالفاتورة');
    posMockService.getCustomers().then(setCustomers);
  };

  if (customer) {
    return (
      <div className="cust">
        <div className="cust-chip">
          <span
            className="avatar"
            style={{ background: 'var(--acc-soft)', color: 'var(--acc)' }}
          >
            {customer.name.slice(0, 1)}
          </span>
          <div className="grow">
            <div className="fs-13 fw-6 row gap-2">
              {customer.name}
              {customer.tier === 'wholesale' ? (
                <span className="badge b-info" style={{ height: 20, fontSize: 11 }}>
                  أسعار جملة
                </span>
              ) : (
                <span className="badge b-neutral" style={{ height: 20, fontSize: 11 }}>
                  تجزئة
                </span>
              )}
            </div>
            <div className="fs-12 t-3 row gap-1">
              <span className="num ltr">{customer.phone}</span>
              <span className="dot-sep" />
              <Icon n="star" s={12} />
              {fmt(customer.points)} نقطة
            </div>
          </div>
          <button
            className="icon-btn sm"
            onClick={() => setCustomer(null)}
            aria-label="إزالة العميل"
          >
            <Icon n="x" s={15} />
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="cust" ref={ref}>
      <div className="row gap-2">
        <div className="input-group grow">
          <Icon n="phone" s={15} />
          <input
            className="input"
            style={{ height: 40 }}
            value={q}
            onChange={(e) => {
              setQ(e.target.value);
              setOpen(true);
            }}
            onFocus={() => setOpen(true)}
            placeholder="عميل: رقم الهاتف أو الاسم"
          />
        </div>
        <button
          className="btn btn-secondary"
          style={{ height: 40, padding: '0 12px' }}
          onClick={() => setQuick(true)}
          title="تسجيل عميل سريع"
        >
          <Icon n="userPlus" s={16} />
          جديد
        </button>
      </div>
      {open && (
        <div className="menu" style={{ top: 'calc(100% - 6px)', insetInline: 14 }}>
          {res.map((c) => (
            <button
              key={c.id}
              onClick={() => {
                setCustomer(c);
                setOpen(false);
                setQ('');
              }}
            >
              <span className="avatar" style={{ width: 26, height: 26, fontSize: 11 }}>
                {c.name.slice(0, 1)}
              </span>
              <span className="grow">{c.name}</span>
              <span className="num ltr t-3 fs-12">{c.phone}</span>
            </button>
          ))}
          {res.length === 0 && (
            <button
              onClick={() => {
                setNw({ ...nw, phone: q });
                setQuick(true);
                setOpen(false);
              }}
            >
              <Icon n="userPlus" s={16} />
              تسجيل «{q}» كعميل جديد
            </button>
          )}
        </div>
      )}
      <Modal
        open={quick}
        onClose={() => setQuick(false)}
        title="تسجيل عميل سريع"
        width={420}
        footer={
          <>
            <button className="btn btn-secondary" onClick={() => setQuick(false)}>
              إلغاء
            </button>
            <button
              className="btn btn-primary"
              disabled={!nw.name || nw.phone.length < 10}
              onClick={handleCreateCustomer}
            >
              حفظ وربط بالفاتورة
            </button>
          </>
        }
      >
        <div className="col gap-4">
          <Field label="الاسم" req>
            <input
              className="input"
              autoFocus
              value={nw.name}
              onChange={(e) => setNw({ ...nw, name: e.target.value })}
              placeholder="اسم العميل"
            />
          </Field>
          <Field label="رقم الهاتف" req>
            <input
              className="input ltr num"
              style={{ textAlign: 'right' }}
              value={nw.phone}
              onChange={(e) => setNw({ ...nw, phone: toAsciiNum(e.target.value) })}
              placeholder="01xxxxxxxxx"
            />
          </Field>
          <Field label="نوع التسعير">
            <Seg
              value={nw.tier}
              onChange={(v) => setNw({ ...nw, tier: v })}
              options={[
                { value: 'retail', label: 'تجزئة + نقاط ولاء' },
                { value: 'wholesale', label: 'أسعار جملة' },
              ]}
            />
          </Field>
        </div>
      </Modal>
    </div>
  );
}import React, { useState, useEffect, useMemo } from 'react';
import { Icon } from '../ui/Icons';
import { egp, fmt, PImg, Api, Kbd, cx } from '../ui/SharedUI';
import type { PosProduct, Customer } from '../../types/pos.types';

interface ScanBarProps {
  products: PosProduct[];
  customer: Customer | null;
  onAdd: (p: PosProduct) => void;
  inputRef?: React.RefObject<HTMLInputElement | null>;
}

export function ScanBar({ products, customer, onAdd, inputRef }: ScanBarProps) {
  const [q, setQ] = useState('');
  const [hl, setHl] = useState(0);
  const [open, setOpen] = useState(false);

  const results = useMemo(() => {
    const s = q.trim().toLowerCase();
    if (!s) return [];
    return products
      .filter((p) => p.name.includes(s) || p.sku.toLowerCase().includes(s) || p.barcode.includes(s))
      .slice(0, 7);
  }, [q, products]);

  useEffect(() => setHl(0), [q]);

  const pick = (p: PosProduct) => {
    onAdd(p);
    setQ('');
    setOpen(false);
  };

  const onKey = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setHl((h) => Math.min(h + 1, results.length - 1));
    }
    if (e.key === 'ArrowUp') {
      e.preventDefault();
      setHl((h) => Math.max(h - 1, 0));
    }
    if (e.key === 'Enter') {
      const exact = products.find(
        (p) => p.barcode === q.trim() || p.sku.toLowerCase() === q.trim().toLowerCase()
      );
      if (exact) {
        pick(exact);
      } else if (results[hl]) {
        pick(results[hl]);
      }
    }
    if (e.key === 'Escape') {
      setQ('');
      setOpen(false);
    }
  };

  return (
    <div className="scanbar">
      <span className="scan-ic">
        <Icon n="barcode" s={18} w={2} />
      </span>
      <input
        ref={inputRef}
        value={q}
        onChange={(e) => {
          setQ(e.target.value);
          setOpen(true);
        }}
        onFocus={() => setOpen(true)}
        onBlur={() => setTimeout(() => setOpen(false), 150)}
        onKeyDown={onKey}
        placeholder="امسح الباركود أو ابحث بالاسم / الكود (SKU)…"
        aria-label="بحث الأصناف"
      />
      <span className="row gap-1 fs-12 t-3">
        <Kbd>F2</Kbd>
      </span>
      {open && q && (
        <div className="scan-results">
          {results.length === 0 ? (
            <div className="empty" style={{ padding: 24 }}>
              <h4 className="fs-14">لا يوجد صنف مطابق</h4>
              <p>جرّب الباركود الكامل أو جزء من الاسم</p>
            </div>
          ) : (
            results.map((p, i) => (
              <button
                key={p.id}
                className={cx('scan-row', i === hl && 'hl')}
                onMouseDown={() => pick(p)}
                onMouseEnter={() => setHl(i)}
              >
                <PImg p={p} size="xs" />
                <div className="grow">
                  <div className="fs-13 fw-5 truncate">{p.name}</div>
                  <div className="fs-12 t-3 ltr" style={{ textAlign: 'right' }}>
                    <span className="mono">{p.sku}</span> · <span className="mono">{p.barcode}</span>
                  </div>
                </div>
                <span
                  className={cx(
                    'badge',
                    p.stock === 0 ? 'b-bad' : p.stock <= p.reorder ? 'b-warn' : 'b-neutral'
                  )}
                >
                  {p.stock === 0 ? (
                    'نفد'
                  ) : (
                    <>
                      رصيد <b className="num">{fmt(p.stock)}</b>
                    </>
                  )}
                </span>
                <span className="price fs-14">
                  {egp(customer?.tier === 'wholesale' ? p.wholesale : p.price)}
                </span>
              </button>
            ))
          )}
          <div
            className="row between fs-12 t-3"
            style={{ padding: '8px 10px 4px', borderTop: '1px solid var(--line)', marginTop: 4 }}
          >
            <span className="row gap-1">
              <Kbd>↑</Kbd>
              <Kbd>↓</Kbd> تنقّل <Kbd>Enter</Kbd> إضافة
            </span>
            <Api
              path={`/pos/products/lookup?q=…${customer ? '&customer_id=' + customer.id : ''}`}
            />
          </div>
        </div>
      )}
    </div>
  );
}import React from 'react';

