export interface IconProps {
  n: string;
  s?: number;
  w?: number;
  className?: string;
  style?: React.CSSProperties;
}

export function Icon({ n, s = 18, w = 1.8, className, style }: IconProps) {
  return (
    <svg
      width={s}
      height={s}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={w}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
      style={style}
      aria-hidden="true"
    >
      {IC[n] || null}
    </svg>
  );
}import React, {
  useState,
  useEffect,
  useRef,
  useCallback,
  createContext,
  useContext,
  ReactNode,
} from 'react';
import ReactDOM from 'react-dom';
import { Icon } from './Icons';
import type { PosProduct } from '../../types/pos.types';

export const cx = (...a: (string | boolean | undefined | null)[]): string =>
  a.filter(Boolean).join(' ');

export const nf = new Intl.NumberFormat('ar-EG', { maximumFractionDigits: 0 });
export const fmt = (v: number | string): string => nf.format(Number(v) || 0);

export const nf2 = new Intl.NumberFormat('ar-EG', {
  minimumFractionDigits: 0,
  maximumFractionDigits: 2,
});
export const egp = (v: number): string => nf2.format(Math.round(v * 100) / 100);

export const toAsciiNum = (s: string | number): string =>
  String(s)
    .replace(/[٠-٩]/g, (d) => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
    .replace(/[^\d.]/g, '');

