export function PImg({
  p,
  size,
  children,
}: {
  p?: PosProduct;
  size?: 'xs' | 'sm' | 'md';
  children?: ReactNode;
}) {
  if (!p) return null;
  const icon =
    p.cat === 'hand' || p.cat === 'cross' || p.cat === 'back'
      ? 'bag'
      : p.cat === 'wallet'
      ? 'wallet'
      : p.cat === 'travel'
      ? 'truck'
      : p.cat === 'acc'
      ? 'tag'
      : 'bag';

  return (
    <div
      className={cx('pimg', size)}
      style={{ '--h': p.h } as React.CSSProperties}
    >
      <Icon
        n={icon}
        s={size === 'xs' ? 16 : size === 'sm' ? 20 : 34}
        w={1.4}
        style={{ position: 'relative', zIndex: 1 }}
      />
      {children}
    </div>
  );
}

