export function resolveServiceUrl(configured: string): string {
  if (typeof window === 'undefined') return configured;
  const hostname = window.location.hostname;
  const parts = hostname?.split('.').map(Number);
  const privateIpv4 = parts?.length === 4 && parts.every(part => Number.isInteger(part) && part >= 0 && part <= 255)
    && (parts[0] === 10 || (parts[0] === 192 && parts[1] === 168) || (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31));
  if (!privateIpv4) return configured;
  try {
    const url = new URL(configured);
    if (!['localhost', '127.0.0.1', '[::1]'].includes(url.hostname)) return configured;
    url.hostname = hostname;
    return url.href.replace(/\/$/, '');
  } catch {
    return configured;
  }
}const { chromium } = require('playwright');
const assert = require('node:assert/strict');
(async () => {
  const browser = await chromium.launch({ headless: true, channel: 'msedge' });
  try {
    const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
    await context.addInitScript(() => {
      window.SpeechRecognition = class {
        start() { this.onresult({ results: [[{ transcript: 'اتنين وعشرين' }]] }); this.onend(); }
        abort() {}
      };
    });
    const page = await context.newPage();
    const scans = [], errors = [];
    page.on('pageerror', e => errors.push(e.message));
    const actor = { id: 1, name: 'موظف جرد', roles: ['staff'], branch_id: 1, permissions: ['pos.access', 'stocktakes.update'] };
    await context.route('**/api/v1/**', async route => {
      const p = new URL(route.request().url()).pathname;
      const headers = { 'access-control-allow-origin': '*', 'access-control-allow-headers': '*', 'access-control-allow-methods': '*' };
      const json = (data, status = 200) => route.fulfill({ headers, status, json: data });
      if (route.request().method() === 'OPTIONS') return route.fulfill({ headers, status: 204 });
      if (p.endsWith('/auth/handoff/exchange')) return json({ token: 'pos-count-test', data: actor, redirect: { path: '/pos' } });
      if (p.endsWith('/admin/me')) return json({ data: actor });
      if (p.endsWith('/stocktakes/7/scan')) {
        scans.push(route.request().postDataJSON());
        if (scans.length === 1) return json({ message: 'فشل مؤقت بعد الحفظ' }, 503);
        return json({ sku: 'BAG-01', counted_qty: 22, system_qty: 987654 });
      }
      return json({ data: [] });
    });
    await page.goto(`${process.env.BACKOFFICE_URL || 'http://127.0.0.1:5173'}/auth/callback#code=pos-count-handoff`);
    const counter = page.getByRole('region', { name: 'عد الجرد بالصوت' });
    await counter.getByRole('textbox', { name: 'معرّف جلسة الجرد' }).fill('٧');
    await counter.getByRole('textbox', { name: 'باركود الجرد' }).fill('6221234567890');
    await counter.getByRole('button', { name: 'قول العدد' }).click();
    await counter.getByRole('textbox', { name: 'العدد المنطوق' }).filter({ visible: true }).waitFor();
    assert.equal(await counter.getByRole('textbox', { name: 'العدد المنطوق' }).inputValue(), 'اتنين وعشرين');
    await counter.getByRole('button', { name: 'تسجيل المسحة' }).click();
    await counter.getByRole('alert').waitFor();
    await counter.getByRole('button', { name: 'تسجيل المسحة' }).click();
    await counter.getByRole('status').filter({ hasText: '22' }).waitFor();
    assert.equal(scans.length, 2);
    assert.equal(scans[0].scan_id, scans[1].scan_id);
    assert.match(scans[0].scan_id, /^[0-9a-f-]{36}$/);
    assert.equal(scans[0].qty_words, 'اتنين وعشرين');
    assert.ok(!(await counter.innerText()).includes('987654'));
    assert.deepEqual(errors, []);
    console.log('POS voice count passed: speech, Arabic session digits, stable scan retry, blind count.');
  } finally { await browser.close(); }
})().catch(e => { console.error(e); process.exitCode = 1; });// Screen 5 — Checkout & payment;  Screen 6 — Hold + Held drawer
function CheckoutModal({ open, onClose, cart, customer, discount, onPaid }) {
  const [method, setMethod] = useState('cash');
  const [received, setReceived] = useState('');
  const [cashPart, setCashPart] = useState('');
  const [notes, setNotes] = useState('');
  const [stage, setStage] = useState('pay'); // pay | sending | done
  const [idem, setIdem] = useState('');
  const subtotal = cart.reduce((s, l) => s + l.price * l.qty, 0);
  const total = Math.max(0, subtotal - discount);
  useEffect(() => { if (open) { setMethod('cash'); setReceived(''); setCashPart(''); setNotes(''); setStage('pay'); setIdem(uuid()); } }, [open]);
  useEffect(() => {
    if (!open || stage !== 'pay') return;
    const h = e => { if (e.target.tagName === 'TEXTAREA') return; if (e.key === 'F1') { e.preventDefault(); setMethod('cash'); } if (e.key === 'F3') { e.preventDefault(); setMethod('card'); } if (e.key === 'F4') { e.preventDefault(); setMethod('mixed'); } };
    window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h);
  }, [open, stage]);
  useEsc(() => stage !== 'sending' && onClose(), open);
  if (!open) return null;

  const rec = Number(received || 0);
  const change = rec - total;
  const cashA = Math.min(Number(cashPart || 0), total);
  const cardA = Math.max(0, total - cashA);
  const valid = method === 'card' || (method === 'cash' && rec >= total) || (method === 'mixed' && cashA > 0 && cardA > 0 && Math.abs(cashA + cardA - total) < 0.01);
  const roundUps = [...new Set([total, Math.ceil(total / 50) * 50, Math.ceil(total / 100) * 100, Math.ceil(total / 200) * 200, Math.ceil(total / 500) * 500])].filter(v => v >= total).slice(0, 4);
  const press = k => {
    const set = method === 'mixed' ? setCashPart : setReceived;
    const cur = method === 'mixed' ? cashPart : received;
    if (k === '⌫') set(cur.slice(0, -1)); else if (k === '.') { if (!cur.includes('.')) set((cur || '0') + '.'); } else set(cur + k);
  };
  const payload = {
    items: cart.map(l => ({ product_variant_id: l.id, qty: l.qty, unit_price: l.price, discount_amount: 0 })),
    customer_id: customer?.id ?? null, payment_method: method,
    cash_amount: method === 'cash' ? total : method === 'mixed' ? cashA : 0,
    card_amount: method === 'card' ? total : method === 'mixed' ? cardA : 0, notes,
  };
  const confirm = () => { if (!valid) return; setStage('sending'); setTimeout(() => setStage('done'), 900); };

  return ReactDOM.createPortal(<div dir="rtl" className={document.querySelector('.app')?.classList.contains('theme-dark') ? 'theme-dark' : ''}>
    <div className="overlay" onClick={() => stage === 'pay' && onClose()} />
    <div className="modal" style={{ width: 'min(960px, calc(100vw - 32px))' }} data-screen-label="05 Checkout" role="dialog" aria-modal="true">
      <div className="pop">
        {stage !== 'done' ? <div className="co">
          <div className="co-main">
            <div className="row between">
              <h3 className="fs-16">الدفع وطرق التحصيل</h3>
              <button className="icon-btn sm" onClick={onClose} aria-label="إغلاق"><Icon n="x" s={16} /></button>
            </div>
            <div className="due">
              <div className="col gap-1"><span className="fs-13 t-2">المطلوب سداده</span><span className="v">{egp(total)}<small>ج.م</small></span></div>
              {customer && <span className="badge b-neutral"><Icon n="users" s={13} />{customer.name}</span>}
            </div>
            <div className="methods" role="radiogroup">
              {[['cash', 'نقدي', 'cash', 'F1'], ['card', 'بطاقة / فيزا', 'card', 'F3'], ['mixed', 'دفع مختلط', 'split', 'F4']].map(([v, l, ic, k]) =>
                <button key={v} role="radio" className="method" aria-checked={method === v} onClick={() => setMethod(v)}><Kbd>{k}</Kbd><Icon n={ic} s={24} w={1.6} />{l}</button>)}
            </div>

            {method === 'cash' && <div className="grid" style={{ gridTemplateColumns: '1fr 220px', gap: 16 }}>
              <div className="col gap-3">
                <span className="fs-13 fw-5">المبلغ المستلم من العميل</span>
                <MoneyInput value={received} onChange={setReceived} autoFocus placeholder={String(total)} onEnter={confirm} />
                <div className="denoms">{roundUps.map((v, i) => <button key={v} className="denom" onClick={() => setReceived(String(v))}>{i === 0 && v === total ? <span className="fs-13" style={{ fontFamily: 'var(--f-body)' }}>المبلغ بالضبط</span> : <>{fmt(v)}<small>ج</small></>}</button>)}</div>
                <div className={cx('change', change < 0 && received && 'neg')}>
                  <span className="col"><span className="fs-12" style={{ opacity: .75 }}>{change < 0 && received ? 'المبلغ غير كافٍ — متبقٍ' : 'المتبقي للعميل (الفكة)'}</span></span>
                  <span className="v">{received ? egp(Math.abs(change)) : '٠'}<small className="fs-13" style={{ opacity: .6, marginInlineStart: 4 }}>ج</small></span>
                </div>
              </div>
              <div className="keypad">{['7', '8', '9', '4', '5', '6', '1', '2', '3', '.', '0', '⌫'].map(k => <button key={k} onClick={() => press(k)}>{k}</button>)}</div>
            </div>}

            {method === 'card' && <div className="col gap-3">
              <div className="card card-pad row gap-4" style={{ background: 'var(--bg-sunken)' }}>
                <div style={{ width: 64, height: 88, borderRadius: 12, background: 'var(--bg-ink)', color: 'var(--on-ink)', display: 'grid', placeItems: 'center', flexShrink: 0 }}><Icon n="card" s={26} w={1.5} /></div>
                <div className="col gap-1 grow">
                  <b className="fs-14">ادفع على ماكينة البطاقات</b>
                  <p className="fs-13 t-2">أدخل مبلغ <b className="num t-1">{egp(total)} ج</b> على الماكينة، وبعد خروج إيصال الموافقة اضغط «تأكيد الدفع».</p>
                </div>
              </div>
              <Field label="آخر ٤ أرقام / رقم الموافقة" hint="اختياري — يظهر في تقرير الوردية"><input className="input ltr num" style={{ textAlign: 'right', maxWidth: 240 }} placeholder="•••• 4821" /></Field>
            </div>}

            {method === 'mixed' && <div className="col gap-3">
              <div className="grid" style={{ gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                <div className="col gap-2"><span className="fs-13 fw-5 row gap-2"><Icon n="cash" s={16} />الجزء النقدي</span><MoneyInput size="md" value={cashPart} onChange={v => setCashPart(String(Math.min(Number(v || 0), total) || ''))} autoFocus placeholder="0" /></div>
                <div className="col gap-2"><span className="fs-13 fw-5 row gap-2"><Icon n="card" s={16} />الجزء بالبطاقة <span className="t-3 fs-12">(تلقائي)</span></span>
                  <div className="money-in md" style={{ background: 'var(--bg-sunken)' }}><span className="cur">ج.م</span><input readOnly value={cashPart ? String(cardA) : ''} placeholder="—" /></div></div>
              </div>
              <div className="split-bar"><span style={{ width: `${total ? cashA / total * 100 : 0}%`, background: 'var(--ok)' }} /><span style={{ width: `${total && cashPart ? cardA / total * 100 : 0}%`, background: 'var(--info)' }} /></div>
              <div className="row between fs-12">
                <span className="row gap-3"><span className="row gap-1"><i style={{ width: 8, height: 8, borderRadius: 99, background: 'var(--ok)' }} />نقدي <b className="num">{egp(cashA)}</b></span><span className="row gap-1"><i style={{ width: 8, height: 8, borderRadius: 99, background: 'var(--info)' }} />بطاقة <b className="num">{egp(cashPart ? cardA : 0)}</b></span></span>
                {valid ? <span className="t-ok row gap-1 fw-6"><Icon n="check" s={14} w={2.5} />المجموع = إجمالي الفاتورة</span> : <span className="t-3">حدد جزءًا نقديًا أقل من الإجمالي</span>}
              </div>
              <div className="row gap-2">{[0.25, 0.5, 0.75].map(r => <button key={r} className="note-chip" onClick={() => setCashPart(String(Math.round(total * r)))}>{fmt(r * 100)}٪ نقدي</button>)}</div>
            </div>}

            <Field label={<>ملاحظات على الفاتورة <span className="t-3 fs-12">(اختياري)</span></>}><input className="input" value={notes} onChange={e => setNotes(e.target.value)} placeholder="تظهر في أسفل الإيصال" /></Field>
            <div className="row gap-2" style={{ marginTop: 'auto' }}>
              <button className="btn btn-secondary btn-lg" onClick={onClose}>رجوع</button>
              <button className="pay-btn grow" style={{ margin: 0 }} disabled={!valid || stage === 'sending'} onClick={confirm}>
                <span className="row gap-2"><Icon n="printer" s={18} />{stage === 'sending' ? 'جارِ تسجيل البيع…' : 'تأكيد الدفع وطباعة الإيصال'}</span>
                <span className="kbd" style={{ background: 'rgba(255,255,255,.15)', borderColor: 'rgba(255,255,255,.35)', color: '#fff' }}>Enter</span>
              </button>
            </div>
          </div>
          <div className="co-side">
            <div className="row between"><span className="section-label">ملخص الفاتورة</span><span className="fs-12 t-3 num">{fmt(cart.reduce((s, l) => s + l.qty, 0))} قطعة</span></div>
            <div className="col gap-2" style={{ flex: 1, overflow: 'auto', maxHeight: 300 }}>
              {cart.map(l => { const p = pById(l.id); return <div key={l.id} className="row gap-2"><PImg p={p} size="xs" /><div className="grow" style={{ minWidth: 0 }}><div className="fs-12 fw-5 truncate">{p.name}</div><div className="fs-12 t-3 num">{fmt(l.qty)} × {egp(l.price)}</div></div><span className="price fs-13">{egp(l.qty * l.price)}</span></div>; })}
            </div>
            <div className="col gap-1 fs-13" style={{ borderTop: '1px dashed var(--line-strong)', paddingTop: 10 }}>
              <div className="row between t-2"><span>المجموع</span><span className="num">{egp(subtotal)}</span></div>
              {discount > 0 && <div className="row between t-2"><span>خصم</span><span className="num t-ok">−{egp(discount)}</span></div>}
              <div className="row between fw-6"><span>الإجمالي</span><span className="num fs-16">{egp(total)}</span></div>
            </div>
            <div className="col gap-2" style={{ borderTop: '1px solid var(--line)', paddingTop: 12 }}>
              <Api m="POST" path="/api/v1/pos/sales" />
              <div className="fs-12 t-3">Idempotency-Key</div>
              <code className="mono" style={{ fontSize: 10.5, direction: 'ltr', wordBreak: 'break-all', color: 'var(--text-2)' }}>{idem}</code>
              <div className="fs-12 t-3">يمنع تكرار الخصم عند الضغط المزدوج</div>
            </div>
          </div>
        </div> : <ReceiptDone total={total} method={method} received={rec} change={change} cashA={cashA} cardA={cardA} cart={cart} customer={customer} discount={discount} notes={notes} onNew={() => onPaid(payload)} />}
      </div>
    </div>
  </div>, document.body);
}

function ReceiptDone({ total, method, received, change, cashA, cardA, cart, customer, discount, notes, onNew }) {
  useEffect(() => { const h = e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onNew(); } }; const t = setTimeout(() => window.addEventListener('keydown', h), 300); return () => { clearTimeout(t); window.removeEventListener('keydown', h); }; }, []);
  return <div className="grid" style={{ gridTemplateColumns: '1fr 360px' }}>
    <div className="col center" style={{ padding: 36, gap: 18, alignItems: 'flex-start', justifyContent: 'center' }}>
      <span style={{ width: 60, height: 60, borderRadius: 20, background: 'var(--ok-bg)', color: 'var(--ok)', display: 'grid', placeItems: 'center' }}><Icon n="check" s={30} w={2.4} /></span>
      <div><h2 className="fs-26">تم تسجيل البيع بنجاح</h2><p className="t-2" style={{ marginTop: 4 }}>فاتورة <b className="num ltr t-1">POS-NSR-10268</b> — تم خصم المخزون وإيداع النقدية بالدرج.</p></div>
      {method !== 'card' && <div className="change" style={{ width: '100%', maxWidth: 380 }}><span className="fs-13" style={{ opacity: .8 }}>{method === 'cash' ? 'الفكة للعميل' : 'تم تحصيل نقدي'}</span><span className="v">{egp(method === 'cash' ? Math.max(0, change) : cashA)} <small className="fs-13" style={{ opacity: .6 }}>ج</small></span></div>}
      <div className="row gap-2">
        <button className="btn btn-secondary btn-lg"><Icon n="printer" s={17} />إعادة الطباعة</button>
        <button className="btn btn-primary btn-lg" autoFocus onClick={onNew}>فاتورة جديدة <Kbd>Enter</Kbd></button>
      </div>
    </div>
    <div style={{ background: 'var(--bg-sunken)', padding: '28px 0 40px', borderInlineStart: '1px solid var(--line)' }}>
      <div className="receipt">
        <div style={{ textAlign: 'center' }}><b className="fs-14 display">الفريد للشنط</b><div style={{ color: '#6f6a76' }}>{BRANCH.name}</div><div className="num" style={{ color: '#6f6a76' }}>POS-NSR-10268 · {new Date().toLocaleString('ar-EG', { dateStyle: 'short', timeStyle: 'short' })}</div></div>
        <div className="dash" />
        {cart.map(l => { const p = pById(l.id); return <div key={l.id}><div className="truncate">{p.name}</div><div className="rr" style={{ color: '#6f6a76' }}><span className="num">{fmt(l.qty)} × {egp(l.price)}</span><span className="num" style={{ color: '#18151c' }}>{egp(l.qty * l.price)}</span></div></div>; })}
        <div className="dash" />
        {discount > 0 && <div className="rr"><span>خصم</span><span className="num">−{egp(discount)}</span></div>}
        <div className="rr" style={{ fontWeight: 700, fontSize: 14 }}><span>الإجمالي</span><span className="num">{egp(total)} ج</span></div>
        {method === 'cash' && <><div className="rr"><span>نقدي مستلم</span><span className="num">{egp(received)}</span></div><div className="rr"><span>الباقي</span><span className="num">{egp(Math.max(0, change))}</span></div></>}
        {method === 'card' && <div className="rr"><span>بطاقة</span><span className="num">{egp(total)}</span></div>}
        {method === 'mixed' && <><div className="rr"><span>نقدي</span><span className="num">{egp(cashA)}</span></div><div className="rr"><span>بطاقة</span><span className="num">{egp(cardA)}</span></div></>}
        {customer && <><div className="dash" /><div className="rr"><span>العميل</span><span>{customer.name}</span></div></>}
        {notes && <div style={{ marginTop: 6, color: '#6f6a76' }}>{notes}</div>}
        <div className="dash" />
        <div style={{ textAlign: 'center', color: '#6f6a76' }}>الكاشير: {CASHIER.name} — الاستبدال خلال ١٤ يومًا بالإيصال</div>
        <div className="bars" />
      </div>
    </div>
  </div>;
}

function HoldModal({ open, onClose, onHold, cart, customer }) {
  const [note, setNote] = useState('');
  useEffect(() => { if (open) setNote(''); }, [open]);
  const total = cart.reduce((s, l) => s + l.price * l.qty, 0);
  return <Modal open={open} onClose={onClose} title="تعليق الفاتورة" width={460}
    footer={<><span className="grow"><Api m="POST" path="/pos/sales/hold" /></span><button className="btn btn-secondary" onClick={onClose}>إلغاء</button><button className="btn btn-primary" onClick={() => onHold(note)}><Icon n="pause" s={15} />تعليق وخدمة زبون آخر</button></>}>
    <div className="col gap-4">
      <div className="sunken row gap-3" style={{ padding: 12 }}>
        <div className="stack-thumbs">{cart.slice(0, 3).map(l => <PImg key={l.id} p={pById(l.id)} size="xs" />)}</div>
        <div className="grow"><div className="fs-13 fw-6 num">{fmt(cart.reduce((s, l) => s + l.qty, 0))} قطعة</div><div className="fs-12 t-3">{customer ? customer.name : 'بدون عميل'}</div></div>
        <span className="price fs-16">{egp(total)} ج</span>
      </div>
      <Field label={<>ملاحظة <span className="t-3 fs-12">(اختياري)</span></>}>
        <input className="input" autoFocus value={note} onChange={e => setNote(e.target.value)} onKeyDown={e => e.key === 'Enter' && onHold(note)} placeholder="مثال: زبون بيجيب محفظة إضافية" />
      </Field>
      <div className="row gap-2 wrap">{['بانتظار العميل', 'بيجيب فلوس', 'بيقيس لون تاني', 'هيرجع كمان شوية'].map(s => <button key={s} className="note-chip" onClick={() => setNote(s)}>{s}</button>)}</div>
    </div>
  </Modal>;
}

function HeldDrawer({ open, onClose, held, onResume, onDelete, cartBusy }) {
  return <Drawer open={open} onClose={onClose} title="الفواتير المعلقة" sub={<span className="row gap-2">{fmt(held.length)} فاتورة في {BRANCH.name} <Api path="/pos/sales/held" /></span>}>
    {held.length === 0 ? <Empty icon="inbox" title="لا توجد فواتير معلقة" body="الفواتير التي تعلّقها من شاشة البيع ستظهر هنا لاستكمالها لاحقًا." /> :
      <div className="col gap-3">
        {cartBusy && <div className="banner b-warn"><Icon n="alert" s={16} />السلة الحالية بها أصناف — الاسترجاع سيضيف الأصناف إليها.</div>}
        {held.map(h => {
          const total = h.items.reduce((s, i) => s + pById(i.id).price * i.qty, 0);
          const pcs = h.items.reduce((s, i) => s + i.qty, 0);
          return <div key={h.ref} className="held-card" data-screen-label="06 Held Sale">
            <div className="row gap-3">
              <div className="stack-thumbs">{h.items.slice(0, 3).map(i => <PImg key={i.id} p={pById(i.id)} size="sm" />)}</div>
              <div className="grow">
                <div className="row gap-2"><b className="mono" style={{ fontSize: 13 }}>{h.ref}</b>{h.mins > 60 && <span className="badge b-warn" style={{ height: 20, fontSize: 11 }}>منذ أكثر من ساعة</span>}</div>
                <div className="fs-12 t-3 row gap-1"><Icon n="history" s={12} />{h.at}<span className="dot-sep" />{fmt(pcs)} قطعة<span className="dot-sep" />{h.customer || 'بدون عميل'}</div>
              </div>
              <span className="price fs-20">{egp(total)}<small>ج</small></span>
            </div>
            {h.note && <div className="fs-13 t-2 row gap-2" style={{ padding: '8px 10px', borderRadius: 10, background: 'var(--bg-sunken)' }}><Icon n="edit" s={14} />{h.note}</div>}
            <div className="row gap-2">
              <button className="btn btn-primary grow" onClick={() => onResume(h)}><Icon n="arrowUpLeft" s={15} />استرجاع الفاتورة</button>
              <button className="btn btn-ghost" onClick={() => onDelete(h)}><Icon n="trash" s={15} />حذف</button>
            </div>
          </div>;
        })}
      </div>}
  </Drawer>;
}

Object.assign(window, { CheckoutModal, HoldModal, HeldDrawer });// Screens 8, 9, 10 — Branch stock, Transfers, Stocktake
function StockPage() {
  const [q, setQ] = useState('');
  const [low, setLow] = useState(false);
  const [cat, setCat] = useState('all');
  const list = PRODUCTS.filter(p => (!q || p.name.includes(q) || p.sku.toLowerCase().includes(q.toLowerCase()) || p.barcode.includes(q)) && (!low || p.stock <= p.reorder) && (cat === 'all' || p.cat === cat));
  const lowCount = PRODUCTS.filter(p => p.stock <= p.reorder).length;
  const outCount = PRODUCTS.filter(p => p.stock === 0).length;
  return <div className="page" data-screen-label="08 Branch Stock"><div className="page-in page-enter">
    <div className="page-title">
      <div><h1>مخزون الفرع</h1><p>أرصدة {BRANCH.name} لحظيًا — بدون مغادرة نقطة البيع.</p></div>
      <Api path={`/pos/stock?q=${q || '…'}&low_stock=${low}&per_page=20`} />
    </div>
    <div className="grid" style={{ gridTemplateColumns: 'repeat(3, 1fr)', gap: 12, marginBottom: 16 }}>
      <KPI label="أصناف بالفرع" value={fmt(PRODUCTS.length)} icon="box" foot={<>إجمالي <b className="num t-1">{fmt(PRODUCTS.reduce((s, p) => s + p.stock, 0))}</b> قطعة</>} />
      <KPI label="منخفضة عن حد الطلب" value={fmt(lowCount)} icon="alert" warn onClick={() => setLow(!low)} active={low} foot="اضغط للفلترة" />
      <KPI label="نفدت من الفرع" value={fmt(outCount)} icon="x" foot="اطلب تحويل من فرع آخر" />
    </div>
    <div className="card" style={{ overflow: 'hidden' }}>
      <div className="toolbar">
        <div className="input-group" style={{ width: 360 }}><Icon n="barcode" s={16} /><input className="input" autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="SKU أو الاسم أو الباركود" /></div>
        <button className={cx('chip', low && 'on')} onClick={() => setLow(!low)}><Icon n="alert" s={13} />الأصناف المنخفضة<span className="count">{fmt(lowCount)}</span></button>
        <FilterSelect label="الفئة" value={cat === 'all' ? '' : cat} options={CATS.slice(1).map(c => ({ value: c.id, label: c.name }))} onChange={v => setCat(v || 'all')} />
        <span className="ms-auto fs-12 t-3">{fmt(list.length)} صنف</span>
      </div>
      <div className="table-wrap"><table className="tbl">
        <thead><tr><th>الصنف</th><th>الكود</th><th>الباركود</th><th className="n">السعر</th><th>المستوى</th><th className="n">الرصيد المتاح</th><th className="n">حد إعادة الطلب</th><th></th></tr></thead>
        <tbody>{list.map(p => {
          const st = p.stock === 0 ? 'out' : p.stock <= p.reorder ? 'low' : 'ok';
          const pct = Math.min(100, p.stock / (p.reorder * 3) * 100);
          return <tr key={p.id}>
            <td><div className="row gap-3"><PImg p={p} size="sm" /><span className="fw-5">{p.name}</span></div></td>
            <td><span className="mono">{p.sku}</span></td>
            <td><span className="mono t-3">{p.barcode}</span></td>
            <td className="n">{egp(p.price)}</td>
            <td><div className="lvl"><span style={{ width: pct + '%', background: st === 'ok' ? 'var(--ok)' : st === 'low' ? 'var(--warn)' : 'var(--bad)' }} /><i style={{ insetInlineStart: (100 / 3) + '%' }} /></div></td>
            <td className="n"><span className={cx('fs-16 fw-6', st === 'out' ? 't-bad' : st === 'low' ? 't-warn' : '')}>{fmt(p.stock)}</span></td>
            <td className="n t-2">{fmt(p.reorder)}</td>
            <td>{st === 'out' ? <span className="badge b-bad"><span className="dot" />نفد</span> : st === 'low' ? <span className="badge b-warn"><span className="dot" />منخفض</span> : <span className="badge b-ok"><span className="dot" />متوفر</span>}</td>
          </tr>;
        })}</tbody>
      </table></div>
      {list.length === 0 && <Empty icon="search" title="لا توجد نتائج" body="جرّب كلمة بحث مختلفة أو أزل فلتر المنخفضة." />}
    </div>
  </div></div>;
}

function TransfersPage({ toast }) {
  const [tab, setTab] = useState('receive');
  return <div className="page" data-screen-label="09 Transfers"><div className="page-in page-enter">
    <div className="page-title">
      <div><h1>التحويلات بين الفروع</h1><p>اطلب بضاعة من المخزن أو فرع آخر، واستلم الشحنات الواردة لـ{BRANCH.name}.</p></div>
    </div>
    <div className="tabs" style={{ marginBottom: 18 }}>
      <button aria-selected={tab === 'receive'} onClick={() => setTab('receive')}><Icon n="truck" s={16} />استلام شحنة واردة<span className="tab-count">{fmt(TRANSFERS_IN.length)}</span></button>
      <button aria-selected={tab === 'request'} onClick={() => setTab('request')}><Icon n="plus" s={16} />طلب تحويل وارد للفرع</button>
    </div>
    {tab === 'receive' ? <ReceiveTab toast={toast} /> : <RequestTab toast={toast} />}
  </div></div>;
}

function ReceiveTab({ toast }) {
  const [list, setList] = useState(TRANSFERS_IN);
  const [cur, setCur] = useState(TRANSFERS_IN[0].id);
  const t = list.find(x => x.id === cur);
  const [rec, setRec] = useState({});
  useEffect(() => { if (t) setRec(Object.fromEntries(t.items.map(i => [i.id, String(i.qty)]))); }, [cur]);
  if (!t) return <div className="card"><Empty icon="truck" title="لا توجد شحنات واردة" body="كل التحويلات المشحونة للفرع تم استلامها." /></div>;
  const shipped = t.items.reduce((s, i) => s + i.qty, 0);
  const got = t.items.reduce((s, i) => s + Number(rec[i.id] || 0), 0);
  const diffs = t.items.filter(i => Number(rec[i.id] || 0) !== i.qty).length;
  return <div className="grid" style={{ gridTemplateColumns: '320px minmax(0, 1fr)', gap: 16, alignItems: 'start' }}>
    <div className="tr-list">
      {list.map(x => <button key={x.id} className="tr-item" aria-pressed={x.id === cur} onClick={() => setCur(x.id)}>
        <div className="row between"><b className="mono" style={{ fontSize: 12.5 }}>{x.number}</b><Status kind="transfer" s="shipped" /></div>
        <div className="route"><Icon n={x.from.includes('المخزن') ? 'warehouse' : 'store'} s={15} className="t-3" /><span className="truncate" style={{ maxWidth: 110 }}>{x.from}</span><span className="ln" /><Icon n="store" s={15} className="t-acc" /><span>فرعنا</span></div>
        <div className="row between fs-12 t-3"><span>{x.shipped}</span><span className="num">{fmt(x.items.reduce((s, i) => s + i.qty, 0))} قطعة · {fmt(x.items.length)} أصناف</span></div>
      </button>)}
    </div>
    <div className="card" style={{ overflow: 'hidden' }}>
      <div className="card-head">
        <div className="col"><h3>{t.number}</h3><span className="fs-12 t-3">من {t.from} · السائق {t.driver}</span></div>
        <button className="btn btn-secondary btn-sm" onClick={() => setRec(Object.fromEntries(t.items.map(i => [i.id, String(i.qty)])))}><Icon n="check" s={14} />الكل مطابق</button>
      </div>
      <table className="tbl">
        <thead><tr><th>الصنف</th><th className="n">المشحون</th><th style={{ textAlign: 'center' }}>المستلم فعليًا</th><th className="n">الفرق</th><th className="n">رصيد الفرع بعد</th></tr></thead>
        <tbody>{t.items.map(i => {
          const p = pById(i.id); const r = Number(rec[i.id] || 0); const d = r - i.qty;
          return <tr key={i.id} className={d !== 0 ? 'selected' : ''}>
            <td><div className="row gap-3"><PImg p={p} size="xs" /><div><div className="fw-5">{p.name}</div><div className="mono t-3" style={{ fontSize: 11 }}>{p.sku}</div></div></div></td>
            <td className="n fw-6">{fmt(i.qty)}</td>
            <td style={{ textAlign: 'center' }}><input className={cx('qty-input', d !== 0 && 'bad')} value={rec[i.id] ?? ''} onChange={e => setRec({ ...rec, [i.id]: toAsciiNum(e.target.value) })} /></td>
            <td className="n">{d === 0 ? <span className="t-ok"><Icon n="check" s={15} w={2.4} /></span> : <span className="badge b-bad num">{d > 0 ? '+' : '−'}{fmt(Math.abs(d))}</span>}</td>
            <td className="n"><span className="t-3 num">{fmt(p.stock)}</span> <Icon n="arrowLeft" s={12} className="t-3" /> <b className="num">{fmt(p.stock + r)}</b></td>
          </tr>;
        })}</tbody>
      </table>
      <div className="row gap-3" style={{ padding: '14px 16px', borderTop: '1px solid var(--line)', background: 'var(--bg-sunken)' }}>
        <div className="grow col gap-1">
          <div className="fs-13"><b className="num">{fmt(got)}</b> من <b className="num">{fmt(shipped)}</b> قطعة {diffs > 0 && <span className="badge b-bad" style={{ marginInlineStart: 6 }}>{fmt(diffs)} صنف به فرق</span>}</div>
          <div className="row gap-2"><Api m="POST" path={`/pos/transfers/${t.id}/receive`} /><span className="perm"><Icon n="shield" s={11} />transfers.receive</span></div>
        </div>
        <button className="btn btn-accent btn-lg" onClick={() => { toast(`تم استلام ${t.number} ورفع رصيد الفرع`); const rest = list.filter(x => x.id !== t.id); setList(rest); setCur(rest[0]?.id); }}><Icon n="check" s={16} w={2.4} />تأكيد الاستلام ورفع الرصيد</button>
      </div>
    </div>
  </div>;
}

function RequestTab({ toast }) {
  const [src, setSrc] = useState(1);
  const [lines, setLines] = useState([{ id: 106, qty: 8 }, { id: 112, qty: 10 }]);
  const [q, setQ] = useState('');
  const [note, setNote] = useState('');
  const res = q ? PRODUCTS.filter(p => p.name.includes(q) || p.sku.toLowerCase().includes(q.toLowerCase())).slice(0, 5) : [];
  const suggestions = PRODUCTS.filter(p => p.stock <= p.reorder && !lines.find(l => l.id === p.id));
  const add = (p, qty = 1) => setLines(l => l.find(x => x.id === p.id) ? l : [...l, { id: p.id, qty }]);
  return <div className="grid" style={{ gridTemplateColumns: 'minmax(0, 1fr) 340px', gap: 16, alignItems: 'start' }}>
    <div className="card" style={{ overflow: 'visible' }}>
      <div className="card-head"><h3>الأصناف المطلوبة</h3><span className="meta">{fmt(lines.length)} أصناف · {fmt(lines.reduce((s, l) => s + l.qty, 0))} قطعة</span></div>
      <div style={{ padding: 16, position: 'relative' }}>
        <Search value={q} onChange={setQ} placeholder="أضف صنفًا بالاسم أو الكود…" />
        {res.length > 0 && <div className="scan-results" style={{ insetInline: 16 }}>{res.map(p => <button key={p.id} className="scan-row" onClick={() => { add(p); setQ(''); }}><PImg p={p} size="xs" /><span className="grow fs-13">{p.name}</span><span className="badge b-neutral">رصيدنا {fmt(p.stock)}</span></button>)}</div>}
      </div>
      <table className="tbl">
        <thead><tr><th>الصنف</th><th className="n">رصيدنا</th><th className="n">حد الطلب</th><th style={{ textAlign: 'center' }}>الكمية المطلوبة</th><th></th></tr></thead>
        <tbody>{lines.map(l => { const p = pById(l.id); return <tr key={l.id}>
          <td><div className="row gap-3"><PImg p={p} size="xs" /><div><div className="fw-5">{p.name}</div><div className="mono t-3" style={{ fontSize: 11 }}>{p.sku}</div></div></div></td>
          <td className={cx('n', p.stock <= p.reorder && 't-warn fw-6')}>{fmt(p.stock)}</td>
          <td className="n t-2">{fmt(p.reorder)}</td>
          <td style={{ textAlign: 'center' }}><div className="stepper-q"><button onClick={() => setLines(x => x.map(y => y.id === l.id ? { ...y, qty: y.qty + 1 } : y))}><Icon n="plus" s={13} /></button><span>{fmt(l.qty)}</span><button onClick={() => setLines(x => x.map(y => y.id === l.id ? { ...y, qty: Math.max(1, y.qty - 1) } : y))}><Icon n="minus" s={13} /></button></div></td>
          <td><button className="icon-btn sm" onClick={() => setLines(x => x.filter(y => y.id !== l.id))}><Icon n="trash" s={15} /></button></td>
        </tr>; })}</tbody>
      </table>
      {lines.length === 0 && <Empty icon="box" title="لم تتم إضافة أصناف" body="ابحث عن صنف أو اختر من المقترحات." />}
      {suggestions.length > 0 && <div style={{ padding: 16, borderTop: '1px solid var(--line)' }}>
        <div className="section-label row gap-2" style={{ marginBottom: 10 }}><Icon n="sparkle" s={13} className="t-acc" />مقترح — أصناف تحت حد الطلب</div>
        <div className="row gap-2 wrap">{suggestions.map(p => <button key={p.id} className="chip" onClick={() => add(p, Math.max(1, p.reorder * 2 - p.stock))}><Icon n="plus" s={12} />{p.name.split('—')[0]}<span className="count">{fmt(p.stock)}</span></button>)}</div>
      </div>}
    </div>
    <div className="card card-pad col gap-4" style={{ position: 'sticky', top: 0 }}>
      <div className="col gap-2"><span className="fs-13 fw-5">الفرع المصدر</span>
        <div className="col gap-2">{SOURCES.map(s => <button key={s.id} role="radio" aria-checked={src === s.id} onClick={() => setSrc(s.id)} className="row gap-3" style={{ padding: '10px 12px', borderRadius: 12, border: '1.5px solid ' + (src === s.id ? 'var(--acc)' : 'var(--line-strong)'), background: src === s.id ? 'var(--acc-tint)' : 'var(--bg-card)', textAlign: 'start' }}>
          <span className="radio-dot" /><Icon n={s.kind} s={17} className="t-3" /><span className="fs-13 fw-5 grow">{s.name}</span>
        </button>)}</div>
      </div>
      <div className="route" style={{ padding: '10px 12px', borderRadius: 12, background: 'var(--bg-sunken)' }}><Icon n="warehouse" s={15} /><span className="truncate">{SOURCES.find(s => s.id === src).name}</span><span className="ln" /><Icon n="store" s={15} className="t-acc" />{BRANCH.name}</div>
      <Field label={<>ملاحظة <span className="t-3 fs-12">(اختياري)</span></>}><textarea className="input" rows={2} value={note} onChange={e => setNote(e.target.value)} placeholder="مثال: مطلوب قبل الويك إند" /></Field>
      <button className="btn btn-accent btn-lg" disabled={!lines.length} onClick={() => { toast('تم إرسال طلب التحويل للاعتماد'); setLines([]); }}><Icon n="arrowLeft" s={16} />إرسال طلب التحويل</button>
      <div className="col gap-1"><Api m="POST" path="/pos/transfer-requests" /><span className="perm"><Icon n="shield" s={11} />transfers.create · Idempotency-Key</span></div>
    </div>
  </div>;
}

function StocktakePage({ toast }) {
  const SCOPE = PRODUCTS.slice(0, 12);
  const [counts, setCounts] = useState({ 101: 14, 103: 21, 107: 41, 111: 85 });
  const [code, setCode] = useState('');
  const [qty, setQty] = useState('1');
  const [listening, setListening] = useState(false);
  const [heard, setHeard] = useState('');
  const [last, setLast] = useState({ id: 111, qty: 85, via: 'voice', words: 'خمسة وتمانين' });
  const [log, setLog] = useState([{ id: 111, add: 85, via: 'voice', words: 'خمسة وتمانين', t: '٠٣:٤٢' }, { id: 107, add: 41, via: 'barcode', t: '٠٣:٣٨' }, { id: 103, add: 21, via: 'barcode', t: '٠٣:٣١' }, { id: 101, add: 14, via: 'barcode', t: '٠٣:٢٥' }]);
  const counted = Object.keys(counts).length;
  const scan = (p, n, via, words) => {
    setCounts(c => ({ ...c, [p.id]: (c[p.id] || 0) + n }));
    setLast({ id: p.id, qty: (counts[p.id] || 0) + n, via, words });
    setLog(l => [{ id: p.id, add: n, via, words, t: new Date().toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' }).replace(/\s?[صم]$/, '') }, ...l].slice(0, 8));
  };
  const submitCode = () => { const p = PRODUCTS.find(x => x.barcode === code.trim() || x.sku.toLowerCase() === code.trim().toLowerCase()) || SCOPE[4]; scan(p, Number(qty || 1), 'barcode'); setCode(''); setQty('1'); };
  const mic = () => {
    if (listening) return;
    setListening(true); setHeard('');
    const words = 'اتناشر'; let i = 0;
    const iv = setInterval(() => { i++; setHeard(words.slice(0, i)); if (i >= words.length) { clearInterval(iv); setTimeout(() => { setListening(false); scan(pById(105), 12, 'voice', words); toast('سُجّل ١٢ — باك باك لابتوب'); }, 500); } }, 140);
  };
  const lp = pById(last.id);
  return <div className="page" data-screen-label="10 Stocktake"><div className="page-in page-enter">
    <div className="page-title">
      <div><div className="row gap-2" style={{ marginBottom: 4 }}><span className="badge b-acc"><span className="dot" />جرد جارٍ</span><span className="mono t-3">STK-NSR-0019</span></div><h1>جرد الفرع</h1><p>امسح الباركود أو قل الكمية بصوتك — بالعامية المصرية.</p></div>
      <div className="col gap-2" style={{ minWidth: 280 }}>
        <div className="row between fs-13"><span className="t-2">تقدم الجرد</span><b className="num">{fmt(counted)} / {fmt(SCOPE.length)} صنف</b></div>
        <div className="progress"><span style={{ width: counted / SCOPE.length * 100 + '%' }} /></div>
      </div>
    </div>
    <div className="st-grid">
      <div className="col gap-4">
        <div className="card card-pad row gap-6" style={{ alignItems: 'center' }}>
          <button className={cx('mic', listening && 'on')} onClick={mic} aria-label="الإدخال الصوتي"><Icon n="mic" s={44} w={1.6} /></button>
          <div className="grow col gap-3">
            <div className="fs-13 t-2">{listening ? 'بسمعك… قول الكمية' : 'اضغط الميكروفون وقل الكمية للصنف الحالي'}</div>
            <div className="row gap-3" style={{ minHeight: 44 }}>
              {listening ? <div className="wave">{Array.from({ length: 14 }).map((_, i) => <i key={i} style={{ animationDelay: i * 0.06 + 's' }} />)}</div> : null}
              <span className="display" style={{ fontSize: 30, fontWeight: 500 }}>{heard ? `«${heard}»` : <span className="t-3 fs-20">مثال: «اتناشر» ، «خمسة وعشرين»</span>}</span>
            </div>
            <div className="divider" style={{ height: 1, background: 'var(--line)' }} />
            <div className="row gap-2">
              <div className="scanbar grow" style={{ height: 48 }}>
                <span className="scan-ic" style={{ width: 30, height: 30 }}><Icon n="barcode" s={16} w={2} /></span>
                <input autoFocus value={code} onChange={e => setCode(e.target.value)} onKeyDown={e => e.key === 'Enter' && submitCode()} placeholder="امسح باركود الصنف" />
              </div>
              <div className="input-group" style={{ width: 110 }}><input className="input num" style={{ height: 48, textAlign: 'center', fontSize: 18, fontWeight: 600 }} value={qty} onChange={e => setQty(toAsciiNum(e.target.value))} aria-label="الكمية" /></div>
              <button className="btn btn-primary" style={{ height: 48 }} onClick={submitCode}>تسجيل</button>
            </div>
            <div className="row gap-2"><Api m="POST" path="/pos/stocktakes/19/scan" /><span className="fs-12 t-3 ltr mono">{'{ barcode, qty | qty_words }'}</span></div>
          </div>
        </div>
        <div className="last-scan" key={last.id + '-' + last.qty} style={{ animation: 'popIn .3s both' }}>
          <PImg p={lp} size="sm" />
          <div className="grow"><div className="fs-12 t-3">آخر تسجيل {last.via === 'voice' ? <span className="badge b-acc" style={{ height: 20 }}><Icon n="mic" s={11} />«{last.words}»</span> : <span className="badge b-neutral" style={{ height: 20 }}><Icon n="barcode" s={11} />باركود</span>}</div><div className="fs-16 fw-5">{lp.name}</div><div className="mono t-3" style={{ fontSize: 11 }}>{lp.sku}</div></div>
          <div className="col" style={{ alignItems: 'flex-end' }}><span className="big-qty">{fmt(last.qty)}</span><span className="fs-12 t-3">العدد الحالي</span></div>
        </div>
        <div className="card" style={{ overflow: 'hidden' }}>
          <div className="card-head"><h3>نطاق الجرد</h3><span className="meta">النظام لا يعرض الرصيد الدفتري أثناء العد</span></div>
          <table className="tbl"><thead><tr><th>الصنف</th><th>الكود</th><th className="n">المعدود</th><th></th></tr></thead>
            <tbody>{SCOPE.map(p => <tr key={p.id} className={last.id === p.id ? 'selected' : ''}>
              <td><div className="row gap-3"><PImg p={p} size="xs" /><span className="fw-5">{p.name}</span></div></td>
              <td><span className="mono">{p.sku}</span></td>
              <td className="n fs-16 fw-6">{counts[p.id] != null ? fmt(counts[p.id]) : <span className="t-3">—</span>}</td>
              <td>{counts[p.id] != null ? <span className="badge b-ok"><span className="dot" />تم العد</span> : <span className="badge b-neutral">لم يُعد</span>}</td>
            </tr>)}</tbody></table>
        </div>
      </div>
      <div className="card" style={{ position: 'sticky', top: 0 }}>
        <div className="card-head"><h3>سجل المسح</h3><span className="meta">آخر {fmt(log.length)}</span></div>
        <div className="col" style={{ padding: '6px 10px 10px' }}>{log.map((l, i) => { const p = pById(l.id); return <div key={i} className="row gap-3" style={{ padding: '10px 6px', borderBottom: i < log.length - 1 ? '1px solid var(--line)' : 0 }}>
          <span className="kpi-icon" style={{ width: 30, height: 30, background: l.via === 'voice' ? 'var(--acc-soft)' : 'var(--bg-sunken)', color: l.via === 'voice' ? 'var(--acc)' : 'var(--text-2)' }}><Icon n={l.via === 'voice' ? 'mic' : 'barcode'} s={14} /></span>
          <div className="grow" style={{ minWidth: 0 }}><div className="fs-13 fw-5 truncate">{p.name}</div><div className="fs-12 t-3">{l.words ? `«${l.words}»` : 'مسح باركود'} · <span className="num">{l.t}</span></div></div>
          <b className="num t-ok">+{fmt(l.add)}</b>
        </div>; })}</div>
        <div style={{ padding: 14, borderTop: '1px solid var(--line)' }}><button className="btn btn-secondary" style={{ width: '100%' }}>إنهاء الجرد وإرساله للمراجعة</button></div>
      </div>
    </div>
  </div></div>;
}

Object.assign(window, { StockPage, TransfersPage, StocktakePage });/* ============ POS — screen layer on top of tokens.css ============ */
html, body { height: 100%; overflow: hidden; }
.app { height: 100vh; display: flex; flex-direction: column; background: var(--bg-canvas); color: var(--text-1); }
.kbd { display: inline-flex; align-items: center; justify-content: center; min-width: 22px; height: 20px; padding: 0 5px; border-radius: 5px; border: 1px solid var(--line-strong); border-bottom-width: 2px; background: var(--bg-card); font-family: var(--f-display); font-size: 10.5px; font-weight: 600; color: var(--text-2); line-height: 1; }
.btn .kbd { background: transparent; border-color: currentColor; color: inherit; opacity: .55; }

/* ---------- Header ---------- */
.ph { height: 60px; flex-shrink: 0; display: flex; align-items: center; gap: 14px; padding: 0 16px; background: var(--bg-card); border-bottom: 1px solid var(--line); }
.ph .brand-mark { width: 34px; height: 34px; border-radius: 10px; background: radial-gradient(circle at 30% 25%, #ff8a65 0%, #e0491f 75%); display: grid; place-items: center; color: #fff; flex-shrink: 0; box-shadow: inset 0 -2px 0 rgba(0,0,0,.12); }
.ph-meta { display: flex; flex-direction: column; line-height: 1.25; }
.ph-meta b { font-family: var(--f-display); font-weight: 600; font-size: 14px; }
.ph-meta span { font-size: 11.5px; color: var(--text-3); }
.ph-sep { width: 1px; height: 28px; background: var(--line); }
.ph-nav { display: flex; gap: 2px; padding: 3px; border-radius: 12px; background: var(--bg-sunken); border: 1px solid var(--line); }
.ph-nav button { height: 34px; padding: 0 12px; border-radius: 9px; display: inline-flex; align-items: center; gap: 7px; font-size: 13px; font-weight: 500; color: var(--text-2); transition: background .15s, color .15s; }
.ph-nav button:hover { color: var(--text-1); }
.ph-nav button[aria-current="page"] { background: var(--bg-card); color: var(--text-1); font-weight: 600; box-shadow: var(--sh-2); }
.ph-nav button[aria-current="page"] svg { color: var(--acc); }
.shift-pill { display: inline-flex; align-items: center; gap: 8px; height: 34px; padding: 0 12px 0 10px; border-radius: 10px; background: var(--bg-sunken); border: 1px solid var(--line); font-size: 12px; }
.shift-pill .live { width: 8px; height: 8px; border-radius: 99px; background: var(--ok); box-shadow: 0 0 0 3px var(--ok-bg); }
.conn { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: var(--ok); font-weight: 500; }
.conn.off { color: var(--bad); }

/* ---------- Sale layout ---------- */
.sale { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 440px; }
.catalog { min-width: 0; display: flex; flex-direction: column; padding: 16px 16px 0; gap: 12px; overflow: hidden; }
.scanbar { position: relative; display: flex; align-items: center; gap: 10px; height: 56px; padding: 0 10px 0 14px; background: var(--bg-card); border: 1.5px solid var(--line-strong); border-radius: 16px; box-shadow: var(--sh-1); transition: border-color .15s, box-shadow .15s; }
.scanbar:focus-within { border-color: var(--acc); box-shadow: var(--ring); }
.scanbar input { flex: 1; min-width: 0; height: 100%; border: 0; outline: none; background: transparent; font-size: 16px; }
.scanbar input::placeholder { color: var(--text-3); }
.scan-ic { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; background: var(--acc-soft); color: var(--acc); flex-shrink: 0; }
.scan-results { position: absolute; top: calc(100% + 6px); inset-inline: 0; z-index: 30; background: var(--bg-card); border: 1px solid var(--line); border-radius: 16px; box-shadow: var(--sh-pop); padding: 6px; max-height: 360px; overflow: auto; animation: popIn .16s cubic-bezier(.2,1,.3,1) both; }
.scan-row { width: 100%; display: flex; align-items: center; gap: 12px; padding: 8px 10px; border-radius: 10px; text-align: start; }
.scan-row:hover, .scan-row.hl { background: var(--bg-hover); }
.cats { display: flex; gap: 6px; overflow-x: auto; scrollbar-width: none; flex-shrink: 0; }
.cats::-webkit-scrollbar { display: none; }
.cat { height: 36px; padding: 0 14px; border-radius: 99px; border: 1px solid var(--line); background: var(--bg-card); font-size: 13px; font-weight: 500; color: var(--text-2); white-space: nowrap; display: inline-flex; align-items: center; gap: 6px; transition: all .15s; }
.cat:hover { color: var(--text-1); border-color: var(--line-strong); }
.cat[aria-pressed="true"] { background: var(--bg-ink); color: var(--on-ink); border-color: transparent; }
.cat .count { font-family: var(--f-display); font-size: 11px; opacity: .6; }
.grid-scroll { flex: 1; overflow-y: auto; margin: 0 -16px; padding: 2px 16px 16px; }
.pgrid { display: grid; grid-template-columns: repeat(auto-fill, minmax(168px, 1fr)); gap: 12px; }
.pcard { position: relative; display: flex; flex-direction: column; text-align: start; background: var(--bg-card); border: 1px solid var(--line); border-radius: 16px; padding: 8px; gap: 8px; transition: border-color .15s, box-shadow .15s, transform .08s; }
.pcard:hover { border-color: var(--line-strong); box-shadow: var(--sh-2); }
.pcard:active { transform: scale(.98); }
.pcard.out { opacity: .5; }
.pcard .qty-tag { position: absolute; top: 14px; inset-inline-start: 14px; z-index: 2; min-width: 26px; height: 26px; padding: 0 7px; border-radius: 99px; background: var(--acc); color: #fff; font-family: var(--f-display); font-size: 12px; font-weight: 600; display: grid; place-items: center; box-shadow: 0 0 0 3px var(--bg-card); animation: popIn .2s both; }
.pcard .stock-tag { position: absolute; top: 14px; inset-inline-end: 14px; z-index: 2; }
.pcard-name { font-size: 13px; font-weight: 500; line-height: 1.35; display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
.pcard-foot { display: flex; align-items: center; justify-content: space-between; padding: 0 4px 2px; }
.price { font-family: var(--f-display); font-weight: 600; font-variant-numeric: tabular-nums; }
.price small { font-size: .72em; color: var(--text-3); font-weight: 400; margin-inline-start: 3px; }

/* Product placeholder art */
.pimg { position: relative; aspect-ratio: 4 / 3; border-radius: 11px; overflow: hidden; display: grid; place-items: center;
  background: radial-gradient(120% 90% at 30% 20%, oklch(0.97 0.025 var(--h)) 0%, oklch(0.9 0.05 var(--h)) 100%); color: oklch(0.52 0.11 var(--h)); }
.theme-dark .pimg { background: radial-gradient(120% 90% at 30% 20%, oklch(0.34 0.04 var(--h)) 0%, oklch(0.25 0.04 var(--h)) 100%); color: oklch(0.78 0.1 var(--h)); }
.pimg::after { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(-45deg, transparent 0 9px, rgba(255,255,255,.18) 9px 10px); }
.pimg.sm { width: 44px; height: 44px; aspect-ratio: auto; border-radius: 10px; flex-shrink: 0; }
.pimg.xs { width: 36px; height: 36px; aspect-ratio: auto; border-radius: 9px; flex-shrink: 0; }

/* ---------- Cart column ---------- */
.cart { min-width: 0; display: flex; flex-direction: column; background: var(--bg-card); border-inline-start: 1px solid var(--line); }
.cust { padding: 12px 14px; border-bottom: 1px solid var(--line); position: relative; }
.cust-chip { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 12px; background: var(--bg-sunken); border: 1px solid var(--line); }
.cart-head { display: flex; align-items: center; justify-content: space-between; padding: 12px 16px 8px; }
.cart-list { flex: 1; overflow-y: auto; padding: 0 8px; }
.line { display: grid; grid-template-columns: 44px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 10px 8px; border-radius: 12px; position: relative; }
.line + .line { border-top: 1px solid var(--line); }
.line:hover { background: var(--bg-sunken); }
.line.flash { animation: flash .9s ease; }
@keyframes flash { 0% { background: var(--acc-soft); } 100% { background: transparent; } }
.line-name { font-size: 13px; font-weight: 500; line-height: 1.35; }
.line-sub { font-size: 11.5px; color: var(--text-3); display: flex; gap: 6px; align-items: center; }
.stepper-q { display: inline-flex; align-items: center; height: 32px; border-radius: 10px; border: 1px solid var(--line-strong); background: var(--bg-card); overflow: hidden; }
.stepper-q button { width: 30px; height: 100%; display: grid; place-items: center; color: var(--text-2); }
.stepper-q button:hover { background: var(--bg-hover); color: var(--text-1); }
.stepper-q input, .stepper-q span { width: 34px; text-align: center; border: 0; outline: none; background: transparent; font-family: var(--f-display); font-weight: 600; font-size: 13px; }
.price-edit { border-bottom: 1px dashed var(--text-3); cursor: pointer; }
.price-edit:hover { color: var(--acc); border-color: var(--acc); }
.price-input { width: 84px; height: 28px; border-radius: 8px; border: 1px solid var(--acc); box-shadow: var(--ring); outline: none; text-align: center; font-family: var(--f-display); font-weight: 600; background: var(--bg-card); }
.totals { padding: 12px 16px; border-top: 1px solid var(--line); background: var(--bg-sunken); display: flex; flex-direction: column; gap: 6px; font-size: 13px; }
.totals .r { display: flex; justify-content: space-between; align-items: center; color: var(--text-2); }
.totals .r b { color: var(--text-1); font-family: var(--f-display); font-weight: 500; }
.grand { display: flex; justify-content: space-between; align-items: flex-end; padding-top: 8px; margin-top: 2px; border-top: 1px dashed var(--line-strong); }
.grand .v { font-family: var(--f-display); font-size: 34px; font-weight: 600; line-height: 1; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.grand .v small { font-size: 14px; color: var(--text-3); font-weight: 400; margin-inline-start: 4px; }
.actions { display: grid; grid-template-columns: 1fr 1fr 48px; gap: 8px; padding: 12px 14px 8px; }
.actions .btn { height: 44px; }
.pay-btn { margin: 0 14px 14px; height: 60px; border-radius: 16px; background: var(--acc); color: #fff; display: flex; align-items: center; justify-content: space-between; padding: 0 20px; font-size: 16px; font-weight: 600; transition: background .15s, transform .08s, opacity .15s; box-shadow: 0 8px 20px -10px rgba(224,73,31,.7); }
.pay-btn:hover:not(:disabled) { background: var(--acc-hover); }
.pay-btn:active:not(:disabled) { transform: translateY(1px); }
.pay-btn:disabled { opacity: .4; cursor: not-allowed; box-shadow: none; }
.pay-btn .amt { font-family: var(--f-display); font-size: 20px; }
.badge-count { min-width: 20px; height: 20px; padding: 0 6px; border-radius: 99px; background: var(--acc); color: #fff; font-family: var(--f-display); font-size: 11px; display: inline-grid; place-items: center; }

/* ---------- Big money input ---------- */
.money-in { display: flex; align-items: center; gap: 10px; height: 72px; padding: 0 18px; border-radius: 16px; border: 1.5px solid var(--line-strong); background: var(--bg-card); transition: border-color .15s, box-shadow .15s; }
.money-in:focus-within { border-color: var(--acc); box-shadow: var(--ring); }
.money-in input { flex: 1; min-width: 0; border: 0; outline: none; background: transparent; font-family: var(--f-display); font-size: 34px; font-weight: 600; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; direction: ltr; text-align: right; }
.money-in .cur { font-size: 14px; color: var(--text-3); font-weight: 500; }
.money-in.md { height: 56px; } .money-in.md input { font-size: 24px; }
.denoms { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.denom { height: 44px; border-radius: 12px; border: 1px solid var(--line-strong); background: var(--bg-card); font-family: var(--f-display); font-weight: 600; font-size: 14px; display: inline-flex; align-items: center; justify-content: center; gap: 4px; transition: all .12s; }
.denom:hover { background: var(--bg-hover); border-color: rgba(24,21,28,.24); }
.denom:active { transform: scale(.97); }
.denom small { font-weight: 400; font-size: 11px; color: var(--text-3); }
.denom.ghost { border-style: dashed; color: var(--text-2); font-family: var(--f-body); font-weight: 500; font-size: 13px; }

/* ---------- Full-screen gate (open shift) ---------- */
.gate { position: fixed; inset: 0; z-index: 90; display: grid; place-items: center; padding: 24px; background: color-mix(in srgb, var(--bg-canvas) 55%, transparent); backdrop-filter: blur(10px) saturate(1.2); -webkit-backdrop-filter: blur(10px) saturate(1.2); animation: fadeIn .2s both; overflow: auto; }
.gate-card { width: min(560px, 100%); background: var(--bg-card); border: 1px solid var(--line); border-radius: 28px; box-shadow: var(--sh-pop); overflow: hidden; animation: popIn .3s cubic-bezier(.2,1,.3,1) both; }
.welcome { position: relative; padding: 22px 24px; color: #fff; background: radial-gradient(120% 160% at 90% 0%, #f4886b 0%, #e6542b 50%, #d8401a 100%); overflow: hidden; }
.welcome::after { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(-60deg, rgba(255,255,255,.07) 0 1.5px, transparent 1.5px 7px); pointer-events: none; }
.welcome .avatar { width: 48px; height: 48px; font-size: 16px; background: rgba(255,255,255,.2); color: #fff; }
.tres { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.tres button { text-align: start; padding: 12px; border-radius: 14px; border: 1.5px solid var(--line-strong); background: var(--bg-card); display: flex; flex-direction: column; gap: 6px; transition: all .15s; position: relative; }
.tres button:hover:not(:disabled) { border-color: rgba(24,21,28,.28); }
.tres button[aria-checked="true"] { border-color: var(--acc); box-shadow: 0 0 0 3px var(--acc-soft); background: var(--acc-tint); }
.tres button:disabled { opacity: .55; cursor: not-allowed; background: var(--bg-sunken); }
.radio-dot { width: 18px; height: 18px; border-radius: 99px; border: 1.5px solid var(--line-strong); display: grid; place-items: center; }
[aria-checked="true"] > .row > .radio-dot, [aria-checked="true"] .radio-dot { border-color: var(--acc); }
[aria-checked="true"] .radio-dot::after { content: ''; width: 8px; height: 8px; border-radius: 99px; background: var(--acc); }

/* ---------- Diff indicator ---------- */
.diff { border-radius: 16px; padding: 14px 16px; display: flex; align-items: center; gap: 12px; transition: background .2s, color .2s; }
.diff.ok { background: var(--ok-bg); color: var(--ok); }
.diff.over { background: var(--ok-bg); color: var(--ok); }
.diff.short { background: var(--bad-bg); color: var(--bad); }
.diff.idle { background: var(--bg-sunken); color: var(--text-2); }
.diff .v { font-family: var(--f-display); font-size: 26px; font-weight: 600; line-height: 1; margin-inline-start: auto; direction: ltr; font-variant-numeric: tabular-nums; }
.diff-ic { width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center; background: color-mix(in srgb, currentColor 14%, transparent); flex-shrink: 0; }
.ledger { display: flex; flex-direction: column; }
.ledger .lr { display: flex; align-items: center; gap: 10px; padding: 11px 0; font-size: 13px; border-bottom: 1px dashed var(--line-strong); }
.ledger .lr:last-child { border-bottom: 0; }
.ledger .op { width: 22px; height: 22px; border-radius: 7px; display: grid; place-items: center; font-family: var(--f-display); font-weight: 600; font-size: 13px; flex-shrink: 0; }
.op.plus { background: var(--ok-bg); color: var(--ok); } .op.minus { background: var(--bad-bg); color: var(--bad); } .op.eq { background: var(--bg-ink); color: var(--on-ink); } .op.base { background: var(--neutral-bg); color: var(--text-2); }
.ledger .amt { margin-inline-start: auto; font-family: var(--f-display); font-weight: 500; font-variant-numeric: tabular-nums; }

/* ---------- Checkout ---------- */
.co { display: grid; grid-template-columns: minmax(0, 1fr) 300px; min-height: 520px; }
.co-main { padding: 22px 24px; display: flex; flex-direction: column; gap: 18px; }
.co-side { background: var(--bg-sunken); border-inline-start: 1px solid var(--line); padding: 22px 20px; display: flex; flex-direction: column; gap: 14px; }
.due { display: flex; align-items: flex-end; justify-content: space-between; }
.due .v { font-family: var(--f-display); font-size: 44px; font-weight: 600; line-height: 1; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.due .v small { font-size: 16px; color: var(--text-3); font-weight: 400; margin-inline-start: 6px; }
.methods { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.method { height: 76px; border-radius: 16px; border: 1.5px solid var(--line-strong); background: var(--bg-card); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; font-size: 13px; font-weight: 600; color: var(--text-2); position: relative; transition: all .15s; }
.method:hover { color: var(--text-1); border-color: rgba(24,21,28,.28); }
.method[aria-checked="true"] { border-color: var(--acc); color: var(--text-1); background: var(--acc-tint); box-shadow: 0 0 0 3px var(--acc-soft); }
.method[aria-checked="true"] svg { color: var(--acc); }
.method .kbd { position: absolute; top: 8px; inset-inline-end: 8px; }
.keypad { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.keypad button { height: 52px; border-radius: 12px; background: var(--bg-card); border: 1px solid var(--line); font-family: var(--f-display); font-size: 20px; font-weight: 500; transition: background .1s, transform .06s; }
.keypad button:hover { background: var(--bg-hover); }
.keypad button:active { transform: scale(.96); background: var(--bg-active); }
.change { border-radius: 16px; padding: 16px 18px; background: var(--bg-ink); color: var(--on-ink); display: flex; align-items: center; justify-content: space-between; }
.change .v { font-family: var(--f-display); font-size: 30px; font-weight: 600; font-variant-numeric: tabular-nums; line-height: 1; }
.change.neg { background: var(--bad-bg); color: var(--bad); }
.split-bar { height: 10px; border-radius: 99px; overflow: hidden; display: flex; background: var(--hatch-track); }
.split-bar > span { transition: width .25s cubic-bezier(.2,1,.3,1); }

/* Receipt */
.receipt { width: 300px; margin: 0 auto; background: #fff; color: #18151c; padding: 22px 20px 26px; font-size: 12px; position: relative; box-shadow: var(--sh-2); border-radius: 4px 4px 0 0; font-family: var(--f-body); }
.receipt::after { content: ''; position: absolute; left: 0; right: 0; bottom: -10px; height: 10px; background: linear-gradient(-45deg, transparent 6px, #fff 6px) 0 0 / 12px 10px repeat-x, linear-gradient(45deg, transparent 6px, #fff 6px) 0 0 / 12px 10px repeat-x; }
.receipt .dash { border-top: 1px dashed rgba(0,0,0,.25); margin: 10px 0; }
.receipt .rr { display: flex; justify-content: space-between; gap: 8px; padding: 2px 0; }
.receipt .num { font-family: var(--f-display); }
.bars { height: 34px; margin-top: 12px; background: repeating-linear-gradient(90deg, #18151c 0 2px, transparent 2px 4px, #18151c 4px 5px, transparent 5px 8px, #18151c 8px 11px, transparent 11px 12px); }

/* Held */
.held-card { border: 1px solid var(--line); border-radius: 16px; padding: 14px; display: flex; flex-direction: column; gap: 12px; background: var(--bg-card); transition: border-color .15s, box-shadow .15s; }
.held-card:hover { border-color: var(--line-strong); box-shadow: var(--sh-2); }
.stack-thumbs { display: flex; }
.stack-thumbs > * { margin-inline-start: -10px; box-shadow: 0 0 0 2px var(--bg-card); }
.stack-thumbs > *:first-child { margin-inline-start: 0; }
.note-chip { height: 30px; padding: 0 12px; border-radius: 99px; border: 1px solid var(--line-strong); font-size: 12px; color: var(--text-2); transition: all .12s; }
.note-chip:hover { background: var(--bg-hover); color: var(--text-1); }

/* ---------- Pages (stock / transfers / count) ---------- */
.page { flex: 1; min-height: 0; overflow-y: auto; }
.page-in { max-width: 1320px; margin: 0 auto; padding: 22px 24px 40px; }
.page-title { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; margin-bottom: 18px; flex-wrap: wrap; }
.page-title h1 { font-size: 24px; font-weight: 500; line-height: 1.25; }
.page-title p { color: var(--text-2); font-size: 13.5px; margin-top: 4px; }
.lvl { width: 120px; height: 6px; border-radius: 99px; background: var(--bg-active); overflow: hidden; position: relative; }
.lvl > span { position: absolute; inset-block: 0; inset-inline-start: 0; border-radius: 99px; }
.lvl > i { position: absolute; top: -3px; bottom: -3px; width: 2px; background: var(--text-1); border-radius: 2px; opacity: .55; }

.tr-list { display: flex; flex-direction: column; gap: 8px; }
.tr-item { text-align: start; border: 1.5px solid var(--line); border-radius: 16px; padding: 14px; background: var(--bg-card); display: flex; flex-direction: column; gap: 10px; transition: all .15s; }
.tr-item:hover { border-color: var(--line-strong); }
.tr-item[aria-pressed="true"] { border-color: var(--acc); box-shadow: 0 0 0 3px var(--acc-soft); }
.route { display: flex; align-items: center; gap: 8px; font-size: 12.5px; }
.route .ln { flex: 1; height: 1.5px; background: repeating-linear-gradient(90deg, var(--line-strong) 0 4px, transparent 4px 8px); position: relative; }
.qty-input { width: 72px; height: 36px; border-radius: 10px; border: 1px solid var(--line-strong); text-align: center; font-family: var(--f-display); font-weight: 600; font-size: 14px; outline: none; background: var(--bg-card); }
.qty-input:focus { border-color: var(--acc); box-shadow: var(--ring); }
.qty-input.bad { border-color: var(--bad); color: var(--bad); }

/* Stocktake */
.st-grid { display: grid; grid-template-columns: minmax(0, 1fr) 380px; gap: 16px; align-items: start; }
.mic { width: 132px; height: 132px; border-radius: 99px; display: grid; place-items: center; background: var(--bg-ink); color: var(--on-ink); position: relative; transition: transform .15s, background .2s; flex-shrink: 0; }
.mic:hover { transform: scale(1.03); }
.mic.on { background: var(--acc); color: #fff; }
.mic.on::before, .mic.on::after { content: ''; position: absolute; inset: -10px; border-radius: 99px; border: 2px solid var(--acc); opacity: 0; animation: ring 1.6s ease-out infinite; }
.mic.on::after { animation-delay: .8s; }
@keyframes ring { 0% { transform: scale(.85); opacity: .7; } 100% { transform: scale(1.35); opacity: 0; } }
.wave { display: flex; align-items: center; gap: 3px; height: 28px; }
.wave i { width: 3px; border-radius: 3px; background: var(--acc); animation: wv 0.9s ease-in-out infinite; }
@keyframes wv { 0%, 100% { height: 4px; } 50% { height: 26px; } }
.last-scan { border-radius: 20px; padding: 18px; background: var(--bg-card); border: 1px solid var(--line); display: flex; gap: 16px; align-items: center; }
.big-qty { font-family: var(--f-display); font-size: 56px; font-weight: 600; line-height: 1; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
.progress { height: 8px; border-radius: 99px; background: var(--hatch-track); overflow: hidden; }
.progress > span { display: block; height: 100%; border-radius: 99px; background: var(--hatch); transition: width .4s cubic-bezier(.2,1,.3,1); }

/* Returns */
.ret-head { display: flex; gap: 10px; align-items: center; }
.order-meta { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; background: var(--line); border-radius: 14px; overflow: hidden; border: 1px solid var(--line); }
.order-meta > div { background: var(--bg-sunken); padding: 10px 12px; display: flex; flex-direction: column; gap: 2px; }
.order-meta span { font-size: 11.5px; color: var(--text-3); }
.order-meta b { font-size: 13px; font-weight: 600; }
.net { border-radius: 16px; padding: 14px 16px; display: flex; align-items: center; gap: 12px; }

/* API annotation */
.api { display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 8px; border-radius: 6px; background: #1d1a21; color: #e7e3ea; font-family: ui-monospace, 'SF Mono', Menlo, monospace; font-size: 10.5px; direction: ltr; white-space: nowrap; letter-spacing: 0; vertical-align: middle; }
.api b { font-weight: 700; }
.api .GET { color: #4ade80; } .api .POST { color: #fdba74; }
.api-block { margin-top: 10px; display: flex; flex-wrap: wrap; gap: 6px; }

/* Misc */
.perm { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; color: var(--text-3); font-family: ui-monospace, Menlo, monospace; direction: ltr; }
.dot-sep::before { content: '•'; margin: 0 2px; color: var(--text-3); }
.section-label { font-size: 12px; font-weight: 600; color: var(--text-3); letter-spacing: .02em; }
.modal.xl { width: min(980px, calc(100vw - 32px)); }

@media (max-width: 1200px) {
  .sale { grid-template-columns: minmax(0, 1fr) 380px; }
  .ph-nav button span.lbl { display: none; }
  .co { grid-template-columns: 1fr; } .co-side { display: none; }
  .st-grid { grid-template-columns: 1fr; }
}// Screen 7 — Return & Exchange modal
function ReturnModal({ open, onClose, toast }) {
  const [num, setNum] = useState('');
  const [sale, setSale] = useState(null);
  const [err, setErr] = useState('');
  const [mode, setMode] = useState('return');
  const [sel, setSel] = useState({}); // id -> {qty, to}
  const [repl, setRepl] = useState([]); // {id, qty}
  const [rq, setRq] = useState('');
  const [busy, setBusy] = useState(false);
  useEffect(() => { if (open) { setNum(''); setSale(null); setErr(''); setMode('return'); setSel({}); setRepl([]); setRq(''); setBusy(false); } }, [open]);
  useEsc(onClose, open);
  if (!open) return null;

  const find = () => {
    const key = num.trim().toUpperCase();
    const s = PAST_SALES[key] || PAST_SALES['POS-NSR-' + key];
    if (s) { setSale({ ...s, number: PAST_SALES[key] ? key : 'POS-NSR-' + key }); setErr(''); } else { setSale(null); setErr('لم يتم العثور على فاتورة بهذا الرقم في الفرع'); }
  };
  const retTotal = sale ? sale.items.reduce((s, i) => s + (sel[i.id]?.qty || 0) * i.price, 0) : 0;
  const replTotal = repl.reduce((s, r) => s + pById(r.id).price * r.qty, 0);
  const net = replTotal - retTotal;
  const anySel = Object.values(sel).some(v => v.qty > 0);
  const canSubmit = anySel && (mode === 'return' || repl.length > 0) && !busy;
  const results = rq ? PRODUCTS.filter(p => p.name.includes(rq) || p.sku.toLowerCase().includes(rq.toLowerCase())).slice(0, 4) : [];

  return ReactDOM.createPortal(<div dir="rtl" className={document.querySelector('.app')?.classList.contains('theme-dark') ? 'theme-dark' : ''}>
    <div className="overlay" onClick={onClose} />
    <div className="modal" style={{ width: 'min(920px, calc(100vw - 32px))' }} data-screen-label="07 Return & Exchange" role="dialog" aria-modal="true">
      <div className="pop">
        <div className="row gap-3" style={{ padding: '18px 22px', borderBottom: '1px solid var(--line)' }}>
          <div className="grow col"><h3 className="fs-16">مرتجع / استبدال</h3><span className="perm"><Icon n="shield" s={12} />pos.sales.refund</span></div>
          <Seg value={mode} onChange={setMode} options={[{ value: 'return', label: 'إرجاع فقط' }, { value: 'exchange', label: 'استبدال بصنف آخر' }]} />
          <button className="icon-btn sm" onClick={onClose} aria-label="إغلاق"><Icon n="x" s={16} /></button>
        </div>

        <div style={{ padding: '18px 22px', display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div className="ret-head">
            <div className="scanbar grow" style={{ height: 48 }}>
              <span className="scan-ic" style={{ width: 30, height: 30 }}><Icon n="barcode" s={16} w={2} /></span>
              <input autoFocus value={num} onChange={e => setNum(e.target.value)} onKeyDown={e => e.key === 'Enter' && find()} placeholder="امسح باركود الإيصال أو اكتب رقم الفاتورة (order_number)" className="ltr" style={{ textAlign: 'right' }} />
            </div>
            <button className="btn btn-primary" style={{ height: 48 }} onClick={find}>بحث</button>
            {!sale && <button className="btn btn-ghost" style={{ height: 48 }} onClick={() => { setNum('POS-NSR-10233'); setSale({ ...PAST_SALES['POS-NSR-10233'], number: 'POS-NSR-10233' }); setErr(''); }}>مثال</button>}
          </div>
          {err && <div className="banner b-bad"><Icon n="alert" s={16} />{err}</div>}

          {!sale ? <Empty icon="ret" title="ابدأ بمسح إيصال البيع الأصلي" body="سيتم عرض بنود الفاتورة لتختار الأصناف والكميات المرتجعة وحالتها." /> : <>
            <div className="order-meta">
              <div><span>رقم الفاتورة</span><b className="mono">{sale.number}</b></div>
              <div><span>التاريخ</span><b>{sale.date}</b></div>
              <div><span>العميل</span><b>{sale.customer}</b></div>
              <div><span>الدفع / الكاشير</span><b>{sale.method} · {sale.cashier}</b></div>
            </div>
            <div className="card" style={{ overflow: 'hidden' }}>
              <table className="tbl">
                <thead><tr><th style={{ width: 40 }}></th><th>الصنف</th><th className="n">السعر</th><th className="n">المباع</th><th style={{ textAlign: 'center' }}>كمية الإرجاع</th><th>حالة الصنف الراجع</th><th className="n">المسترد</th></tr></thead>
                <tbody>{sale.items.map(i => {
                  const p = pById(i.id); const s = sel[i.id] || { qty: 0, to: 'on_hand' }; const on = s.qty > 0;
                  const upd = v => setSel(x => ({ ...x, [i.id]: { ...s, ...v } }));
                  return <tr key={i.id} className={on ? 'selected' : ''}>
                    <td><Check on={on} onChange={v => upd({ qty: v ? 1 : 0 })} /></td>
                    <td><div className="row gap-2"><PImg p={p} size="xs" /><div><div className="fs-13 fw-5">{p.name}</div><div className="mono t-3" style={{ fontSize: 11 }}>{p.sku}</div></div></div></td>
                    <td className="n">{egp(i.price)}</td>
                    <td className="n">{fmt(i.qty)}</td>
                    <td style={{ textAlign: 'center' }}><div className="stepper-q" style={{ opacity: on ? 1 : .5 }}>
                      <button onClick={() => upd({ qty: Math.min(i.qty, s.qty + 1) })}><Icon n="plus" s={13} /></button><span>{fmt(s.qty)}</span><button onClick={() => upd({ qty: Math.max(0, s.qty - 1) })}><Icon n="minus" s={13} /></button>
                    </div></td>
                    <td><div className="seg" style={{ opacity: on ? 1 : .45, pointerEvents: on ? 'auto' : 'none' }}>
                      <button aria-pressed={s.to === 'on_hand'} onClick={() => upd({ to: 'on_hand' })}><span className="row gap-1"><i style={{ width: 7, height: 7, borderRadius: 9, background: 'var(--ok)' }} />سليم</span></button>
                      <button aria-pressed={s.to === 'damaged'} onClick={() => upd({ to: 'damaged' })}><span className="row gap-1"><i style={{ width: 7, height: 7, borderRadius: 9, background: 'var(--bad)' }} />تالف</span></button>
                    </div></td>
                    <td className="n fw-6">{on ? egp(s.qty * i.price) : '—'}</td>
                  </tr>;
                })}</tbody>
              </table>
            </div>

            {mode === 'exchange' && <div className="card card-pad col gap-3" style={{ background: 'var(--bg-sunken)' }}>
              <div className="row between"><span className="section-label">الصنف البديل</span><span className="fs-12 t-3">ينفَّذ الإرجاع والفاتورة الجديدة في عملية واحدة</span></div>
              <div style={{ position: 'relative' }}>
                <Search value={rq} onChange={setRq} placeholder="ابحث عن الصنف البديل بالاسم أو الكود…" />
                {results.length > 0 && <div className="scan-results" style={{ maxHeight: 240 }}>{results.map(p => <button key={p.id} className="scan-row" onClick={() => { setRepl(r => r.find(x => x.id === p.id) ? r.map(x => x.id === p.id ? { ...x, qty: x.qty + 1 } : x) : [...r, { id: p.id, qty: 1 }]); setRq(''); }}>
                  <PImg p={p} size="xs" /><span className="grow fs-13">{p.name}</span><span className="badge b-neutral">رصيد {fmt(p.stock)}</span><span className="price">{egp(p.price)}</span></button>)}</div>}
              </div>
              {repl.map(r => { const p = pById(r.id); return <div key={r.id} className="row gap-3" style={{ background: 'var(--bg-card)', padding: 10, borderRadius: 12, border: '1px solid var(--line)' }}>
                <PImg p={p} size="xs" /><span className="grow fs-13 fw-5">{p.name}</span>
                <div className="stepper-q"><button onClick={() => setRepl(x => x.map(y => y.id === r.id ? { ...y, qty: y.qty + 1 } : y))}><Icon n="plus" s={13} /></button><span>{fmt(r.qty)}</span><button onClick={() => setRepl(x => r.qty > 1 ? x.map(y => y.id === r.id ? { ...y, qty: y.qty - 1 } : y) : x.filter(y => y.id !== r.id))}><Icon n="minus" s={13} /></button></div>
                <span className="price" style={{ width: 80, textAlign: 'end' }}>{egp(p.price * r.qty)}</span>
              </div>; })}
              {repl.length === 0 && <div className="fs-13 t-3">لم يتم اختيار صنف بديل بعد.</div>}
            </div>}
          </>}
        </div>

        {sale && <div className="row gap-3" style={{ padding: '14px 22px', borderTop: '1px solid var(--line)', background: 'var(--bg-card)' }}>
          {mode === 'return' ? <div className="net grow" style={{ background: 'var(--bad-bg)', color: 'var(--bad)', padding: '10px 14px' }}>
            <Icon n="cash" s={18} /><span className="fs-13 fw-6">رد نقدية للعميل</span><span className="ms-auto display fs-20 fw-6 num">{egp(retTotal)} ج</span>
          </div> : <div className="net grow" style={{ background: !anySel || !repl.length ? 'var(--bg-sunken)' : net > 0 ? 'var(--ok-bg)' : net < 0 ? 'var(--bad-bg)' : 'var(--info-bg)', color: !anySel || !repl.length ? 'var(--text-2)' : net > 0 ? 'var(--ok)' : net < 0 ? 'var(--bad)' : 'var(--info)', padding: '10px 14px' }}>
            <span className="fs-12 t-2" style={{ color: 'inherit', opacity: .8 }}>مرتجع {egp(retTotal)} ← بديل {egp(replTotal)}</span>
            <span className="fs-13 fw-6">{net > 0 ? 'تحصيل فرق من العميل' : net < 0 ? 'رد فرق للعميل' : 'بدون فروق'}</span>
            <span className="ms-auto display fs-20 fw-6 num">{egp(Math.abs(net))} ج</span>
          </div>}
          <Api m="POST" path={`/pos/sales/${sale.id}/${mode}`} />
          <button className="btn btn-primary btn-lg" disabled={!canSubmit} onClick={() => { setBusy(true); setTimeout(() => { toast(mode === 'return' ? 'تم تسجيل المرتجع وتحديث المخزون' : 'تم الاستبدال وإصدار فاتورة جديدة'); onClose(); }, 700); }}>
            <Icon n="check" s={16} w={2.4} />{busy ? 'جارِ التنفيذ…' : mode === 'return' ? 'تأكيد المرتجع' : 'تأكيد الاستبدال'}
          </button>
        </div>}
      </div>
    </div>
  </div>, document.body);
}

Object.assign(window, { ReturnModal });// Screens 1 & 2 — Open shift gate, Close shift modal
function OpenShiftGate({ onOpened }) {
  const [treasury, setTreasury] = useState(1);
  const [cash, setCash] = useState('500');
  const [busy, setBusy] = useState(false);
  const amount = Number(cash || 0);
  const now = new Date();
  const hr = now.getHours();
  const greet = hr < 12 ? 'صباح الخير' : 'مساء الخير';

  const submit = () => {
    if (!treasury || busy) return;
    setBusy(true);
    setTimeout(() => {
      onOpened({ id: 512, shift_number: 'SH-NSR-0512', treasury_id: treasury, treasury: TREASURIES.find(t => t.id === treasury), opening_cash: amount, opened_at: now, status: 'open' });
    }, 700);
  };

  return <div className="gate" data-screen-label="01 Open Shift">
    <div className="gate-card" role="dialog" aria-modal="true" aria-label="فتح الوردية">
      <div className="welcome">
        <div className="row gap-3" style={{ position: 'relative', zIndex: 1 }}>
          <span className="avatar">{CASHIER.initials}</span>
          <div className="grow">
            <div style={{ fontSize: 13, opacity: .85 }}>{greet}،</div>
            <div className="display" style={{ fontSize: 22, fontWeight: 500, lineHeight: 1.25 }}>{CASHIER.name}</div>
          </div>
          <div className="col" style={{ alignItems: 'flex-end', gap: 4 }}>
            <span className="badge" style={{ background: 'rgba(255,255,255,.18)', color: '#fff' }}><Icon n="store" s={13} />{BRANCH.name}</span>
            <span style={{ fontSize: 12, opacity: .85 }} className="num">{now.toLocaleDateString('ar-EG', { weekday: 'long', day: 'numeric', month: 'long' })}</span>
          </div>
        </div>
        <div className="row gap-2" style={{ position: 'relative', zIndex: 1, marginTop: 16, padding: '10px 12px', borderRadius: 12, background: 'rgba(0,0,0,.14)', fontSize: 12.5 }}>
          <Icon n="lock" s={15} />
          لا توجد وردية مفتوحة باسمك. افتح وردية لبدء البيع.
        </div>
      </div>

      <div style={{ padding: '20px 24px 8px', display: 'flex', flexDirection: 'column', gap: 18 }}>
        <div className="col gap-2">
          <div className="row between"><span className="fs-13 fw-5">درج النقدية</span><span className="fs-12 t-3">{TREASURIES.filter(t => t.state === 'free').length} متاح في الفرع</span></div>
          <div className="tres" role="radiogroup">
            {TREASURIES.map(t => <button key={t.id} role="radio" aria-checked={treasury === t.id} disabled={t.state === 'busy'} onClick={() => setTreasury(t.id)}>
              <div className="row between"><Icon n="cash" s={18} style={{ color: treasury === t.id ? 'var(--acc)' : 'var(--text-3)' }} />{t.state === 'busy' ? <span className="badge b-neutral" style={{ height: 20, fontSize: 11 }}>مشغول</span> : <span className="radio-dot" />}</div>
              <div className="fs-13 fw-6">{t.name}</div>
              <div className="fs-12 t-3 truncate" style={{ lineHeight: 1.3 }}>{t.last}</div>
            </button>)}
          </div>
        </div>

        <div className="col gap-2">
          <div className="row between"><span className="fs-13 fw-5">العهدة الافتتاحية</span><button className="fs-12 t-3" onClick={() => setCash('')}>مسح</button></div>
          <MoneyInput value={cash} onChange={setCash} autoFocus onEnter={submit} />
          <div className="denoms">
            {[200, 500, 1000].map(v => <button key={v} className="denom" onClick={() => setCash(String(amount + v))}>+{fmt(v)}<small>ج</small></button>)}
            <button className="denom ghost" onClick={() => setCash('500')}>نفس أمس</button>
          </div>
        </div>
      </div>

      <div style={{ padding: '16px 24px 22px' }}>
        <button className="pay-btn" style={{ margin: 0, width: '100%' }} disabled={!treasury || busy} onClick={submit}>
          <span className="row gap-2">{busy ? 'جارِ فتح الوردية…' : 'فتح الوردية وبدء البيع'}</span>
          <span className="row gap-2"><span className="amt num">{egp(amount)}</span><Icon n="arrowLeft" s={18} /></span>
        </button>
        <div className="api-block center" style={{ justifyContent: 'center' }}>
          <Api path="/api/v1/pos/shifts/current" /> <Api m="POST" path="/api/v1/pos/shifts/open" />
        </div>
      </div>
    </div>
  </div>;
}

function CloseShiftModal({ open, onClose, shift, onClosed }) {
  const [actual, setActual] = useState('');
  const [notes, setNotes] = useState('');
  const [busy, setBusy] = useState(false);
  useEffect(() => { if (open) { setActual(''); setNotes(''); setBusy(false); } }, [open]);
  useEsc(onClose, open);
  if (!open || !shift) return null;
  const s = SHIFT_STATS;
  const expected = shift.opening_cash + s.cashSales - s.returns - s.expenses;
  const has = actual !== '';
  const diff = Number(actual || 0) - expected;
  const state = !has ? 'idle' : Math.abs(diff) < 0.01 ? 'ok' : diff > 0 ? 'over' : 'short';
  const needNote = state === 'short' || state === 'over';
  const canSubmit = has && (!needNote || notes.trim().length >= 3) && !busy;
  const diffLabel = { idle: 'أدخل النقد الفعلي لحساب الفرق', ok: 'مطابق تمامًا', over: 'زيادة في الدرج', short: 'عجز في الدرج' }[state];
  const diffIcon = { idle: 'info', ok: 'check', over: 'arrowUpLeft', short: 'alert' }[state];
  const started = shift.opened_at;

  return ReactDOM.createPortal(<div dir="rtl" className={document.querySelector('.app')?.classList.contains('theme-dark') ? 'theme-dark' : ''}>
    <div className="overlay" onClick={onClose} />
    <div className="modal" style={{ width: 'min(860px, calc(100vw - 32px))' }} data-screen-label="02 Close Shift" role="dialog" aria-modal="true">
      <div className="pop">
        <div className="row between" style={{ padding: '18px 22px', borderBottom: '1px solid var(--line)' }}>
          <div className="col">
            <h3 className="fs-16">إغلاق الوردية وجرد النقدية</h3>
            <div className="fs-12 t-3 row gap-1"><span className="num ltr">{shift.shift_number}</span><span className="dot-sep" />{shift.treasury.name}<span className="dot-sep" />بدأت <span className="num">{started.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}</span></div>
          </div>
          <button className="icon-btn sm" onClick={onClose} aria-label="إغلاق"><Icon n="x" s={16} /></button>
        </div>

        <div className="grid" style={{ gridTemplateColumns: '1fr 1fr' }}>
          <div style={{ padding: '18px 22px', borderInlineEnd: '1px solid var(--line)', background: 'var(--bg-sunken)' }}>
            <div className="section-label" style={{ marginBottom: 6 }}>ملخص حركة النقدية</div>
            <div className="ledger">
              <div className="lr"><span className="op base">·</span>العهدة الافتتاحية<span className="amt">{egp(shift.opening_cash)}</span></div>
              <div className="lr"><span className="op plus">+</span>مبيعات نقدية <span className="t-3 fs-12">({fmt(s.invoices)} فاتورة)</span><span className="amt">{egp(s.cashSales)}</span></div>
              <div className="lr"><span className="op minus">−</span>مرتجعات نقدية<span className="amt">{egp(s.returns)}</span></div>
              <div className="lr"><span className="op minus">−</span>مصروفات نثرية<span className="amt">{egp(s.expenses)}</span></div>
              <div className="lr" style={{ paddingTop: 14 }}><span className="op eq">=</span><b>النقد المتوقع بالدرج</b><span className="amt fs-20 fw-6">{egp(expected)}</span></div>
            </div>
            <div className="row gap-2 fs-12 t-3" style={{ marginTop: 10, padding: '10px 12px', borderRadius: 12, border: '1px dashed var(--line-strong)' }}>
              <Icon n="card" s={15} />مبيعات البطاقة <b className="num t-1">{egp(s.cardSales)}</b> ج — لا تدخل في جرد الدرج
            </div>
          </div>

          <div style={{ padding: '18px 22px', display: 'flex', flexDirection: 'column', gap: 14 }}>
            <div className="col gap-2">
              <span className="fs-13 fw-5">النقد الفعلي بالدرج</span>
              <MoneyInput value={actual} onChange={setActual} autoFocus placeholder={String(expected)} />
              <div className="row gap-2">
                <button className="note-chip" onClick={() => setActual(String(expected))}>مطابق للمتوقع</button>
              </div>
            </div>
            <div className={cx('diff', state)}>
              <span className="diff-ic"><Icon n={diffIcon} s={18} w={2} /></span>
              <div className="col"><span className="fs-12" style={{ opacity: .8 }}>الفرق</span><b className="fs-13">{diffLabel}</b></div>
              <span className="v">{has ? (diff > 0 ? '+' : diff < 0 ? '−' : '') + egp(Math.abs(diff)) : '—'}</span>
            </div>
            <Field label={<>ملاحظات {needNote ? <span className="t-bad fs-12">(مطلوبة لتبرير الفرق)</span> : <span className="t-3 fs-12">(اختياري)</span>}</>}>
              <textarea className={cx('input', needNote && notes.trim().length < 3 && 'is-error')} rows={3} value={notes} onChange={e => setNotes(e.target.value)} placeholder={state === 'short' ? `مثال: عجز ${egp(Math.abs(diff))} جنيه فرق فكة مع عميل` : 'أي ملاحظات على الوردية…'} />
            </Field>
          </div>
        </div>

        <div className="row gap-2" style={{ padding: '14px 22px', borderTop: '1px solid var(--line)' }}>
          <div className="row gap-2 fs-12 t-3 grow"><Icon n="info" s={14} />ستُرسل الوردية بحالة <span className="badge b-warn" style={{ height: 20 }}>بانتظار الاعتماد</span><Api m="POST" path="/pos/shifts/close" /></div>
          <button className="btn btn-secondary" onClick={onClose}>رجوع للبيع</button>
          <button className="btn" style={{ background: 'var(--bad)', color: '#fff' }} disabled={!canSubmit} onClick={() => { setBusy(true); setTimeout(() => onClosed({ actual_closing_cash: Number(actual), notes, cash_difference: diff }), 700); }}>
            <Icon n="lock" s={16} />{busy ? 'جارِ الإغلاق…' : 'إغلاق الوردية وإرسالها للاعتماد'}
          </button>
        </div>
      </div>
    </div>
  </div>, document.body);
}

Object.assign(window, { OpenShiftGate, CloseShiftModal });// Screen 4 — POS Sales Terminal (catalog + cart)
function ScanBar({ customer, onAdd, inputRef }) {
  const [q, setQ] = useState('');
  const [hl, setHl] = useState(0);
  const [open, setOpen] = useState(false);
  const results = useMemo(() => {
    const s = q.trim().toLowerCase();
    if (!s) return [];
    return PRODUCTS.filter(p => p.name.includes(s) || p.sku.toLowerCase().includes(s) || p.barcode.includes(s)).slice(0, 7);
  }, [q]);
  useEffect(() => setHl(0), [q]);
  const pick = p => { onAdd(p); setQ(''); setOpen(false); };
  const onKey = e => {
    if (e.key === 'ArrowDown') { e.preventDefault(); setHl(h => Math.min(h + 1, results.length - 1)); }
    if (e.key === 'ArrowUp') { e.preventDefault(); setHl(h => Math.max(h - 1, 0)); }
    if (e.key === 'Enter') {
      const exact = PRODUCTS.find(p => p.barcode === q.trim() || p.sku.toLowerCase() === q.trim().toLowerCase());
      if (exact) pick(exact); else if (results[hl]) pick(results[hl]);
    }
    if (e.key === 'Escape') { setQ(''); setOpen(false); }
  };
  return <div className="scanbar">
    <span className="scan-ic"><Icon n="barcode" s={18} w={2} /></span>
    <input ref={inputRef} value={q} onChange={e => { setQ(e.target.value); setOpen(true); }} onFocus={() => setOpen(true)} onBlur={() => setTimeout(() => setOpen(false), 150)} onKeyDown={onKey}
      placeholder="امسح الباركود أو ابحث بالاسم / الكود (SKU)…" aria-label="بحث الأصناف" />
    <span className="row gap-1 fs-12 t-3"><Kbd>F2</Kbd></span>
    {open && q && <div className="scan-results">
      {results.length === 0 ? <div className="empty" style={{ padding: 24 }}><h4 className="fs-14">لا يوجد صنف مطابق</h4><p>جرّب الباركود الكامل أو جزء من الاسم</p></div> :
        results.map((p, i) => <button key={p.id} className={cx('scan-row', i === hl && 'hl')} onMouseDown={() => pick(p)} onMouseEnter={() => setHl(i)}>
          <PImg p={p} size="xs" />
          <div className="grow"><div className="fs-13 fw-5 truncate">{p.name}</div><div className="fs-12 t-3 ltr" style={{ textAlign: 'right' }}><span className="mono">{p.sku}</span> · <span className="mono">{p.barcode}</span></div></div>
          <span className={cx('badge', p.stock === 0 ? 'b-bad' : p.stock <= p.reorder ? 'b-warn' : 'b-neutral')}>{p.stock === 0 ? 'نفد' : <>رصيد <b className="num">{fmt(p.stock)}</b></>}</span>
          <span className="price fs-14">{egp(customer?.tier === 'wholesale' ? p.wholesale : p.price)}</span>
        </button>)}
      <div className="row between fs-12 t-3" style={{ padding: '8px 10px 4px', borderTop: '1px solid var(--line)', marginTop: 4 }}>
        <span className="row gap-1"><Kbd>↑</Kbd><Kbd>↓</Kbd> تنقّل <Kbd>Enter</Kbd> إضافة</span>
        <Api path={`/pos/products/lookup?q=…${customer ? '&customer_id=' + customer.id : ''}`} />
      </div>
    </div>}
  </div>;
}

function Catalog({ cart, customer, onAdd, scanRef }) {
  const [cat, setCat] = useState('all');
  const list = PRODUCTS.filter(p => cat === 'all' || p.cat === cat);
  const qtyOf = id => cart.find(l => l.id === id)?.qty || 0;
  return <div className="catalog">
    <ScanBar customer={customer} onAdd={onAdd} inputRef={scanRef} />
    <div className="cats">
      {CATS.map(c => <button key={c.id} className="cat" aria-pressed={cat === c.id} onClick={() => setCat(c.id)}>{c.name}<span className="count">{fmt(c.id === 'all' ? PRODUCTS.length : PRODUCTS.filter(p => p.cat === c.id).length)}</span></button>)}
    </div>
    <div className="grid-scroll">
      <div className="pgrid">
        {list.map(p => {
          const q = qtyOf(p.id); const price = customer?.tier === 'wholesale' ? p.wholesale : p.price;
          return <button key={p.id} className={cx('pcard', p.stock === 0 && 'out')} onClick={() => p.stock > 0 && onAdd(p)} disabled={p.stock === 0}>
            {q > 0 && <span className="qty-tag">{fmt(q)}</span>}
            {p.stock === 0 ? <span className="stock-tag badge b-bad" style={{ height: 22 }}>نفد</span> : p.stock <= p.reorder ? <span className="stock-tag badge b-warn" style={{ height: 22 }}>باقي {fmt(p.stock)}</span> : null}
            <PImg p={p} />
            <div style={{ padding: '0 4px' }}><div className="pcard-name">{p.name}</div><div className="mono t-3" style={{ fontSize: 11 }}>{p.sku}</div></div>
            <div className="pcard-foot">
              <span className="price fs-16">{egp(price)}<small>ج</small></span>
              {customer?.tier === 'wholesale' && <span className="badge b-info" style={{ height: 20, fontSize: 11 }}>جملة</span>}
            </div>
          </button>;
        })}
      </div>
    </div>
  </div>;
}

function CustomerBar({ customer, setCustomer, toast }) {
  const [q, setQ] = useState('');
  const [open, setOpen] = useState(false);
  const [quick, setQuick] = useState(false);
  const [nw, setNw] = useState({ name: '', phone: '', tier: 'retail' });
  const ref = useRef();
  useOutside(ref, () => setOpen(false));
  const res = CUSTOMERS.filter(c => !q || c.phone.includes(q) || c.name.includes(q));
  if (customer) return <div className="cust"><div className="cust-chip">
    <span className="avatar" style={{ background: 'var(--acc-soft)', color: 'var(--acc)' }}>{customer.name.slice(0, 1)}</span>
    <div className="grow"><div className="fs-13 fw-6 row gap-2">{customer.name}{customer.tier === 'wholesale' ? <span className="badge b-info" style={{ height: 20, fontSize: 11 }}>أسعار جملة</span> : <span className="badge b-neutral" style={{ height: 20, fontSize: 11 }}>تجزئة</span>}</div>
      <div className="fs-12 t-3 row gap-1"><span className="num ltr">{customer.phone}</span><span className="dot-sep" /><Icon n="star" s={12} />{fmt(customer.points)} نقطة</div></div>
    <button className="icon-btn sm" onClick={() => setCustomer(null)} aria-label="إزالة العميل"><Icon n="x" s={15} /></button>
  </div></div>;
  return <div className="cust" ref={ref}>
    <div className="row gap-2">
      <div className="input-group grow"><Icon n="phone" s={15} /><input className="input" style={{ height: 40 }} value={q} onChange={e => { setQ(e.target.value); setOpen(true); }} onFocus={() => setOpen(true)} placeholder="عميل: رقم الهاتف أو الاسم" /></div>
      <button className="btn btn-secondary" style={{ height: 40, padding: '0 12px' }} onClick={() => setQuick(true)} title="تسجيل عميل سريع"><Icon n="userPlus" s={16} />جديد</button>
    </div>
    {open && <div className="menu" style={{ top: 'calc(100% - 6px)', insetInline: 14 }}>
      {res.map(c => <button key={c.id} onClick={() => { setCustomer(c); setOpen(false); setQ(''); }}>
        <span className="avatar" style={{ width: 26, height: 26, fontSize: 11 }}>{c.name.slice(0, 1)}</span>
        <span className="grow">{c.name}</span><span className="num ltr t-3 fs-12">{c.phone}</span>
      </button>)}
      {res.length === 0 && <button onClick={() => { setNw({ ...nw, phone: q }); setQuick(true); setOpen(false); }}><Icon n="userPlus" s={16} />تسجيل «{q}» كعميل جديد</button>}
    </div>}
    <Modal open={quick} onClose={() => setQuick(false)} title="تسجيل عميل سريع" width={420}
      footer={<><button className="btn btn-secondary" onClick={() => setQuick(false)}>إلغاء</button><button className="btn btn-primary" disabled={!nw.name || nw.phone.length < 10} onClick={() => { const c = { id: 99, name: nw.name, phone: nw.phone, tier: nw.tier, points: 0 }; setCustomer(c); setQuick(false); toast('تم تسجيل العميل وربطه بالفاتورة'); }}>حفظ وربط بالفاتورة</button></>}>
      <div className="col gap-4">
        <Field label="الاسم" req><input className="input" autoFocus value={nw.name} onChange={e => setNw({ ...nw, name: e.target.value })} placeholder="اسم العميل" /></Field>
        <Field label="رقم الهاتف" req><input className="input ltr num" style={{ textAlign: 'right' }} value={nw.phone} onChange={e => setNw({ ...nw, phone: toAsciiNum(e.target.value) })} placeholder="01xxxxxxxxx" /></Field>
        <Field label="نوع التسعير"><Seg value={nw.tier} onChange={v => setNw({ ...nw, tier: v })} options={[{ value: 'retail', label: 'تجزئة + نقاط ولاء' }, { value: 'wholesale', label: 'أسعار جملة' }]} /></Field>
      </div>
    </Modal>
  </div>;
}

function CartLine({ l, onQty, onRemove, onPrice, canOverride, flash }) {
  const p = pById(l.id);
  const [edit, setEdit] = useState(false);
  const [val, setVal] = useState(String(l.price));
  const overridden = l.price !== l.listPrice;
  return <div className={cx('line', flash && 'flash')}>
    <PImg p={p} size="sm" />
    <div style={{ minWidth: 0 }}>
      <div className="line-name truncate">{p.name}</div>
      <div className="line-sub">
        {edit ? <input className="price-input" autoFocus value={val} onChange={e => setVal(toAsciiNum(e.target.value))} onBlur={() => { onPrice(Number(val || l.listPrice)); setEdit(false); }} onKeyDown={e => { if (e.key === 'Enter') e.target.blur(); if (e.key === 'Escape') { setVal(String(l.price)); setEdit(false); } }} />
          : <span className={cx('num', canOverride && 'price-edit')} onClick={() => canOverride && (setVal(String(l.price)), setEdit(true))} title={canOverride ? 'تعديل السعر (pos.override_price)' : undefined}>{egp(l.price)} ج</span>}
        {overridden && !edit && <><s className="num">{egp(l.listPrice)}</s><span className="badge b-warn" style={{ height: 18, fontSize: 10.5, padding: '0 6px' }}>سعر معدّل</span></>}
        {l.qty > p.stock && <span className="badge b-bad" style={{ height: 18, fontSize: 10.5, padding: '0 6px' }}>الرصيد {fmt(p.stock)}</span>}
      </div>
    </div>
    <div className="col" style={{ alignItems: 'flex-end', gap: 6 }}>
      <div className="row gap-1">
        <div className="stepper-q">
          <button onClick={() => onQty(l.qty + 1)} aria-label="زيادة"><Icon n="plus" s={14} /></button>
          <span>{fmt(l.qty)}</span>
          <button onClick={() => l.qty > 1 ? onQty(l.qty - 1) : onRemove()} aria-label="نقص"><Icon n="minus" s={14} /></button>
        </div>
        <button className="icon-btn sm" onClick={onRemove} aria-label="حذف" style={{ color: 'var(--text-3)' }}><Icon n="trash" s={15} /></button>
      </div>
      <span className="price fs-14">{egp(l.price * l.qty)}</span>
    </div>
  </div>;
}

function Cart({ cart, setCart, customer, setCustomer, discount, setDiscount, onHold, onHeld, heldCount, onPay, onClear, lastAdded, toast }) {
  const canOverride = CASHIER.perms.includes('pos.override_price');
  const subtotal = cart.reduce((s, l) => s + l.listPrice * l.qty, 0);
  const lineAdj = cart.reduce((s, l) => s + (l.listPrice - l.price) * l.qty, 0);
  const total = Math.max(0, subtotal - lineAdj - discount);
  const items = cart.reduce((s, l) => s + l.qty, 0);
  const [discOpen, setDiscOpen] = useState(false);
  const [discVal, setDiscVal] = useState('');
  return <aside className="cart">
    <CustomerBar customer={customer} setCustomer={setCustomer} toast={toast} />
    <div className="cart-head">
      <div className="row gap-2"><h3 className="fs-16">الفاتورة الحالية</h3>{items > 0 && <span className="badge b-neutral num">{fmt(items)} قطعة</span>}</div>
      {cart.length > 0 && <button className="btn btn-ghost btn-sm" onClick={onClear}><Icon n="trash" s={14} />مسح</button>}
    </div>
    <div className="cart-list">
      {cart.length === 0 ? <div className="empty" style={{ paddingTop: 56 }}>
        <div className="empty-ic"><Icon n="barcode" s={24} /></div>
        <h4>الفاتورة فارغة</h4>
        <p>امسح باركود صنف أو اضغط على أي صنف من الكتالوج لإضافته.</p>
        <div className="row gap-2 fs-12 t-3" style={{ marginTop: 8 }}><Kbd>F2</Kbd> بحث <Kbd>F6</Kbd> المعلقة <Kbd>F8</Kbd> مرتجع</div>
      </div> : cart.map(l => <CartLine key={l.id} l={l} canOverride={canOverride} flash={lastAdded?.id === l.id ? lastAdded.k : null}
        onQty={q => setCart(c => c.map(x => x.id === l.id ? { ...x, qty: q } : x))}
        onPrice={pr => setCart(c => c.map(x => x.id === l.id ? { ...x, price: pr } : x))}
        onRemove={() => setCart(c => c.filter(x => x.id !== l.id))} />)}
    </div>
    <div className="totals">
      <div className="r"><span>المجموع الفرعي</span><b>{egp(subtotal)}</b></div>
      {lineAdj !== 0 && <div className="r"><span>تعديلات الأسعار</span><b className="t-warn">−{egp(lineAdj)}</b></div>}
      <div className="r">
        <span className="row gap-2">الخصم {discOpen ? <span className="row gap-1"><input className="price-input" autoFocus value={discVal} onChange={e => setDiscVal(toAsciiNum(e.target.value))} onKeyDown={e => { if (e.key === 'Enter') { setDiscount(Math.min(Number(discVal || 0), subtotal)); setDiscOpen(false); } }} onBlur={() => { setDiscount(Math.min(Number(discVal || 0), subtotal)); setDiscOpen(false); }} placeholder="0" /></span> : <button className="t-acc fs-12 fw-6" onClick={() => { setDiscVal(discount ? String(discount) : ''); setDiscOpen(true); }} disabled={!cart.length}>{discount ? 'تعديل' : '+ إضافة'}</button>}</span>
        <b className={discount ? 't-ok' : ''}>{discount ? '−' + egp(discount) : '٠'}</b>
      </div>
      <div className="grand"><span className="fs-13 t-2">الإجمالي</span><span className="v">{egp(total)}<small>ج.م</small></span></div>
    </div>
    <div className="actions">
      <button className="btn btn-secondary" disabled={!cart.length} onClick={onHold}><Icon n="pause" s={15} />تعليق</button>
      <button className="btn btn-secondary" onClick={onHeld}><Icon n="inbox" s={16} />المعلقة{heldCount > 0 && <span className="badge-count">{fmt(heldCount)}</span>}<Kbd>F6</Kbd></button>
      <button className="btn btn-danger" disabled={!cart.length} onClick={onClear} aria-label="إلغاء ومسح الفاتورة" title="إلغاء ومسح الفاتورة"><Icon n="x" s={18} /></button>
    </div>
    <button className="pay-btn" disabled={!cart.length} onClick={onPay}>
      <span className="row gap-2">إتمام الدفع <span className="kbd" style={{ background: 'rgba(255,255,255,.15)', borderColor: 'rgba(255,255,255,.35)', color: '#fff' }}>Space</span></span>
      <span className="amt num">{egp(total)} ج</span>
    </button>
  </aside>;
}

