namespace App\Enums;

/**
 * Supported payment channels for reimbursing approved customer return requests.
 */
enum RefundMethod: string
{
    case OriginalPayment = 'original_payment';
    case Wallet = 'wallet';
    case BankTransfer = 'bank_transfer';
    case Cash = 'cash';
}<?php

declare(strict_types=1);

namespace App\Enums;

/**
 * Return Merchandise Authorization (RMA) lifecycle statuses. Inventory movements occur only on Received.
 */
enum ReturnStatus: string
{
    case Pending = 'pending';
    case Approved = 'approved';
    case Rejected = 'rejected';
    case Received = 'received';
    case Refunded = 'refunded';
    case Cancelled = 'cancelled';
}<?php

declare(strict_types=1);

namespace App\Enums;

enum StaffRole: string
{
    case SuperAdmin = 'Super Admin';
    case Cashier = 'cashier';

    public static function normalizeName(string $name): string
    {
        return trim(\Normalizer::normalize($name, \Normalizer::FORM_KC) ?: $name);
    }

    public static function isReserved(string $name): bool
    {
        $name = mb_strtolower(self::normalizeName($name));
        foreach (self::cases() as $role) {
            if ($name === mb_strtolower($role->value)) {
                return true;
            }
        }

        return false;
    }
}<?php

