namespace App\Http\Controllers\Api\V1\Pos;

use App\Http\Controllers\Controller;
use App\Models\Customer;
use App\Services\PosService;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;

/**
 * POS product barcode and SKU lookup with branch stock availability and tiered customer pricing.
 */
class PosProductController extends Controller
{
    public function __construct(private readonly PosService $pos) {}

    /**
     * Search products by barcode, SKU, or name for the cashier's active branch.
     */
    public function lookup(Request $request): JsonResponse
    {
        $data = $request->validate([
            'barcode'     => ['nullable', 'string', 'max:100'],
            'q'           => ['nullable', 'string', 'max:100'],
            'customer_id' => ['nullable', 'integer', 'min:1'],
        ]);

        $query = $data['barcode'] ?? $data['q'] ?? '';

        if (empty($query)) {
            return response()->json(['data' => []]);
        }

        /** @var \App\Models\User $user */
        $user     = $request->user('staff');
        $customer = isset($data['customer_id'])
            ? Customer::find($data['customer_id'])
            : null;

        $results = $this->pos->lookupProducts($query, (int) $user->branch_id, $customer);

        return response()->json(['data' => $results]);
    }
}<?php

declare(strict_types=1);

namespace App\Http\Controllers\Api\V1\Pos;

use App\Enums\PosShiftStatus;
use App\Http\Controllers\Controller;
use App\Models\PosShift;
use App\Models\Treasury;
use App\Models\User;
use App\Services\PosService;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;

/**
 * Cashier POS terminal shifts: opening with drawer cash float, active shift monitoring, and reconciliation closing.
 */
class PosShiftController extends Controller
{
    public function __construct(private readonly PosService $pos) {}

    /**
     * Open a new cashier shift with initial drawer cash float.
     */
    public function open(Request $request): JsonResponse
    {
        $data = $request->validate([
            'treasury_id'  => ['required', 'integer', 'min:1'],
            'opening_cash' => ['required', 'numeric', 'min:0', 'max:9999999'],
        ]);

        /** @var User $user */
        $user = $request->user('staff');

        $shift = $this->pos->openShift(
            user: $user,
            branchId: (int) $user->branch_id,
            treasuryId: (int) $data['treasury_id'],
            openingCash: (float) $data['opening_cash'],
        );

        return response()->json([
            'message' => 'تم فتح الوردية بنجاح.',
            'data'    => $this->formatShift($shift->load(['cashier', 'treasury', 'branch'])),
        ], 201);
    }

    /**
     * Retrieve current open shift details for the authenticated cashier.
     */
    public function current(Request $request): JsonResponse
    {
        /** @var User $user */
        $user = $request->user('staff');

        $shift = PosShift::query()
            ->where('user_id', $user->id)
            ->where('branch_id', $user->branch_id)
            ->where('status', PosShiftStatus::Open)
            ->with(['cashier', 'treasury', 'branch'])
            ->latest('id')
            ->first();

        if ($shift === null) {
            return response()->json(['data' => null, 'has_open_shift' => false]);
        }

        return response()->json([
            'data'           => $this->formatShift($shift),
            'has_open_shift' => true,
        ]);
    }

    /**
     * Close the cashier shift with counted cash for administrative reconciliation.
     */
    public function close(Request $request): JsonResponse
    {
        $data = $request->validate([
            'actual_closing_cash' => ['required', 'numeric', 'min:0', 'max:9999999'],
            'notes'               => ['nullable', 'string', 'max:500'],
        ]);

        /** @var PosShift $shift */
        $shift = $request->attributes->get('pos_shift');

        $shift = $this->pos->closeShift(
            shift: $shift,
            actualCash: (float) $data['actual_closing_cash'],
            notes: $data['notes'] ?? null,
        );

        return response()->json([
            'message' => 'تم إغلاق الوردية وهي بانتظار اعتماد المدير.',
            'data'    => $this->formatShift($shift),
        ]);
    }

    // ===================================================================
    //  Helper
    // ===================================================================

    private function formatShift(PosShift $shift): array
    {
        return [
            'id'                    => $shift->id,
            'shift_number'          => $shift->shift_number,
            'status'                => $shift->status->value,
            'opened_at'             => $shift->opened_at,
            'closed_at'             => $shift->closed_at,
            'approved_at'           => $shift->approved_at,
            'opening_cash'          => $shift->opening_cash,
            'cash_sales_total'      => $shift->cash_sales_total,
            'card_sales_total'      => $shift->card_sales_total,
            'cash_returns_total'    => $shift->cash_returns_total,
            'cash_expenses_total'   => $shift->cash_expenses_total,
            'expected_closing_cash' => $shift->expected_closing_cash,
            'actual_closing_cash'   => $shift->actual_closing_cash,
            'cash_difference'       => $shift->cash_difference,
            'notes'                 => $shift->notes,
            'cashier'               => $shift->relationLoaded('cashier') ? [
                'id'   => $shift->cashier->id,
                'name' => $shift->cashier->name,
            ] : null,
            'treasury'              => $shift->relationLoaded('treasury') ? [
                'id'   => $shift->treasury->id,
                'name' => $shift->treasury->name,
                'code' => $shift->treasury->code,
            ] : null,
            'branch'                => $shift->relationLoaded('branch') ? [
                'id'   => $shift->branch->id,
                'name' => $shift->branch->name,
            ] : null,
        ];
    }
}<?php

declare(strict_types=1);

namespace App\Http\Middleware;

use App\Enums\PosShiftStatus;
use App\Models\PosShift;
use App\Models\User;
use Closure;
use Illuminate\Http\Request;
use Symfony\Component\HttpFoundation\Response;

/**
 * Ensures the authenticated cashier has an active, open shift at their assigned branch.
 * Injects the open shift model into request attributes under 'pos_shift'.
 */
class EnsureOpenPosShift
{
    /**
     * Handle incoming POS request and verify active shift presence.
     */
    public function handle(Request $request, Closure $next): Response
    {
        $user = $request->user('staff');

        if (! $user instanceof User || $user->branch_id === null) {
            return response()->json([
                'message' => 'لا يمكن استخدام نقطة البيع بدون ارتباط بفرع.',
            ], 403);
        }

        $shift = PosShift::query()
            ->where('user_id', $user->id)
            ->where('branch_id', $user->branch_id)
            ->where('status', PosShiftStatus::Open)
            ->latest('id')
            ->first();

        if ($shift === null) {
            return response()->json([
                'message' => 'لا توجد وردية مفتوحة. افتح وردية أولًا لإتمام العملية.',
                'code'    => 'no_open_shift',
            ], 403);
        }

        $request->attributes->set('pos_shift', $shift);

        return $next($request);
    }
}<?php

declare(strict_types=1);

namespace App\Http\Requests\Admin\Transfer;

use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;

/**
 * Transfer stage item quantity requests (approval, shipment, receipt).
 * Items are optional; omitted items default to previous stage quantities.
 */
class TransferItemsQtyRequest extends FormRequest
{
    public function authorize(): bool
    {
        return true;
    }

    /** Quantity field name for the active transfer stage (specialized in child classes). */
    protected string $qtyField = 'approved_qty';

    /**
     * @return array<string, mixed>
     */
    public function rules(): array
    {
        $transferId = $this->route('transfer')?->id;

        return [
            'expected_version' => ['nullable', 'integer', 'min:1'],
            'expected_updated_at' => ['nullable', 'date'],
            'items' => ['nullable', 'array', 'max:100'],
            'items.*.id' => [
                'required', 'bail', 'integer', 'min:1', 'distinct',
                Rule::exists('stock_transfer_items', 'id')->where('stock_transfer_id', $transferId),
            ],
            "items.*.{$this->qtyField}" => ['required', 'numeric', 'decimal:0,4', 'min:0', 'max:99999999.9999'],
        ];
    }

    /**
     * Map of [item_id => quantity] formatted for service execution.
     *
     * @return array<int, float>
     */
    public function quantitiesByItemId(): array
    {
        $map = [];

        foreach ($this->validated('items', []) ?? [] as $item) {
            $map[(int) $item['id']] = (float) $item[$this->qtyField];
        }

        return $map;
    }

    public function expectedVersion(): ?int
    {
        return $this->filled('expected_version') ? (int) $this->validated('expected_version') : null;
    }

    public function expectedUpdatedAt(): ?string
    {
        return $this->validated('expected_updated_at');
    }
}<?php

