declare(strict_types=1);

namespace App\Http\Controllers\Api\V1\Pos;

use App\Http\Controllers\Controller;
use App\Http\Resources\Api\V1\Admin\UserResource;
use App\Models\Branch;
use App\Models\User;
use App\Services\Auth\LoginDestinationResolver;
use App\Services\Auth\StaffAuthenticationAudit;
use App\Services\Auth\StaffHandoffService;
use App\Services\Auth\StaffTokenService;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;
use Illuminate\Http\Response;
use Illuminate\Support\Facades\Hash;

/**
 * POS terminal cashier authentication enforcing mandatory branch authorization checks.
 */
class PosAuthController extends Controller
{
    private const DUMMY_PASSWORD_HASH = '$2y$12$dRibbzvWAKqkXBRPna4QCuri7dR8TKHRGDIt.RsplFZRfRcJzmPlq';

    /**
     * Authenticate cashier against specific branch credentials and issue scoped staff token.
     */
    public function login(Request $request): JsonResource|JsonResponse
    {
        $data = $request->validate([
            'email' => ['required', 'string', 'email:rfc', 'max:191'],
            'password' => ['required', 'string', 'max:72'],
            'branch_id' => ['required', 'integer', 'min:1'],
        ]);

        $user = User::query()
            ->whereRaw('LOWER(email) = ?', [mb_strtolower(trim($data['email']))])
            ->first();

        // Dummy hash evaluation prevents timing attack enumeration of registered staff emails.
        $storedHash = $user instanceof User ? $user->password : self::DUMMY_PASSWORD_HASH;
        $passwordOk = Hash::check($data['password'], $storedHash);

        // Cashiers are strictly confined to their assigned active branch.
        $branchAllowed = $user instanceof User
            && $user->is_active
            && ! $user->is_system
            && $user->can('pos.access')
            && $user->branch_id === (int) $data['branch_id'];

        if (! $user instanceof User || ! $passwordOk || ! $branchAllowed) {
            StaffAuthenticationAudit::record($user, 'failed');

            return response()->json([
                'message' => 'بيانات تسجيل الدخول غير صحيحة أو الحساب غير مصرح له على هذا الفرع.',
            ], 401);
        }

        // Verify designated branch exists and is currently active.
        Branch::query()->where('id', $data['branch_id'])->where('is_active', true)->firstOrFail();

        $user->load(['branch', 'roles.permissions', 'permissions']);
        app(LoginDestinationResolver::class)->resolve($user);
        $token = app(StaffTokenService::class)->issue($user, StaffHandoffService::credentialFingerprint($user));
        StaffAuthenticationAudit::record($user, 'success');

        return UserResource::make($user)->additional(['token' => $token]);
    }

    /**
     * Revoke cashier terminal session token.
     */
    public function logout(Request $request): Response
    {
        $request->user('staff')?->currentAccessToken()?->delete();

        return response()->noContent();
    }
}<?php

declare(strict_types=1);

namespace App\Http\Resources\Api\V1\Admin;

use App\Enums\StaffRole;
use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;
use Spatie\Permission\Models\Permission;

/**
 * Administrative staff user resource representation with role/permission resolution and password rotation state.
 */
class UserResource extends JsonResource
{
    /**
     * @return array<string, mixed>
     */
    public function toArray(Request $request): array
    {
        return [
            'id' => $this->id,
            'version' => (int) $this->lock_version,
            'name' => $this->name,
            'email' => $this->email,
            'phone' => $this->phone,
            'branch_id' => $this->branch_id,
            'branch' => $this->whenLoaded('branch', fn (): ?array => $this->branch === null
                ? null
                : ['id' => $this->branch->id, 'name' => $this->branch->name]),
            'is_active' => $this->is_active,
            // Informs the frontend that immediate password rotation is enforced for this account.
            'must_change_password' => (bool) $this->must_change_password,
            'roles' => $this->whenLoaded(
                'roles',
                fn () => $this->roles->map(fn ($role): array => [
                    'id' => $role->id,
                    'name' => $role->name,
                ])->values(),
            ),
            'permissions' => $this->when(
                $this->relationLoaded('roles')
                    && $this->relationLoaded('permissions')
                    && $this->roles->every(fn ($role): bool => $role->relationLoaded('permissions')),
                fn () => $this->hasRole(StaffRole::SuperAdmin->value, 'staff')
                    ? Permission::query()->where('guard_name', 'staff')->orderBy('name')->pluck('name')
                    : $this->getAllPermissions()->pluck('name')->unique()->values(),
            ),
            'created_at' => $this->created_at,
            'updated_at' => $this->updated_at,
        ];
    }
}<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\TreasuryType;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\Relations\HasOne;

/**
 * Cash drawer, bank account, or safe representing a monetary fund repository.
 */
class Treasury extends Model
{
    protected $fillable = [
        'name',
        'code',
        'branch_id',
        'type',
        'current_balance',
        'is_active',
    ];

    protected function casts(): array
    {
        return [
            'type'            => TreasuryType::class,
            'current_balance' => 'decimal:2',
            'is_active'       => 'boolean',
        ];
    }

    /** @return BelongsTo<Branch, $this> */
    public function branch(): BelongsTo
    {
        return $this->belongsTo(Branch::class);
    }

    /** @return HasMany<TreasuryTransaction, $this> */
    public function transactions(): HasMany
    {
        return $this->hasMany(TreasuryTransaction::class);
    }

    /** @return HasOne<TreasuryTransaction, $this> */
    public function latestTransaction(): HasOne
    {
        return $this->hasOne(TreasuryTransaction::class)->latestOfMany('id');
    }

    /** @return HasMany<PosShift, $this> */
    public function shifts(): HasMany
    {
        return $this->hasMany(PosShift::class);
    }
}<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\TreasuryTransferStatus;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * Monitored monetary fund transfer between two treasury repositories.
 */
class TreasuryTransfer extends Model
{
    protected $fillable = [
        'transfer_number',
        'from_treasury_id',
        'to_treasury_id',
        'amount',
        'status',
        'created_by',
        'approved_by',
        'rejection_reason',
        'notes',
    ];

    protected function casts(): array
    {
        return [
            'status' => TreasuryTransferStatus::class,
            'amount' => 'decimal:2',
        ];
    }

    /** @return BelongsTo<Treasury, $this> */
    public function fromTreasury(): BelongsTo
    {
        return $this->belongsTo(Treasury::class, 'from_treasury_id');
    }

    /** @return BelongsTo<Treasury, $this> */
    public function toTreasury(): BelongsTo
    {
        return $this->belongsTo(Treasury::class, 'to_treasury_id');
    }

    /** @return BelongsTo<User, $this> */
    public function creator(): BelongsTo
    {
        return $this->belongsTo(User::class, 'created_by');
    }

    /** @return BelongsTo<User, $this> */
    public function approver(): BelongsTo
    {
        return $this->belongsTo(User::class, 'approved_by');
    }
}<?php

