namespace App\Http\Controllers\Api\V1\Admin;

use App\Enums\PosShiftStatus;
use App\Http\Controllers\Controller;
use App\Models\PosShift;
use App\Models\User;
use App\Services\BranchAccess;
use App\Services\PosService;
use Carbon\Carbon;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Routing\Controllers\HasMiddleware;
use Illuminate\Routing\Controllers\Middleware;
use Illuminate\Validation\Rule;

/**
 * Admin controller for reviewing POS shifts, cash discrepancies, and authorizing closures.
 */
class PosShiftAdminController extends Controller implements HasMiddleware
{
    public static function middleware(): array
    {
        return [
            new Middleware('can:pos_shifts.view', only: ['index', 'show']),
            new Middleware('can:pos_shifts.approve', only: ['approve']),
        ];
    }

    public function __construct(
        private readonly PosService $pos,
        private readonly BranchAccess $branchAccess,
    ) {}

    /**
     * Lists paginated POS shifts for administrative audit and approval.
     *
     * @param Request $request Filter query request
     * @return JsonResponse Paginated shifts response
     */
    public function index(Request $request): JsonResponse
    {
        $filters = $request->validate([
            'branch_id' => ['nullable', 'integer', 'min:1'],
            'user_id' => ['nullable', 'integer', 'min:1'],
            'status' => ['nullable', Rule::in(array_column(PosShiftStatus::cases(), 'value'))],
            'from_date' => ['nullable', 'date_format:Y-m-d'],
            'to_date' => ['nullable', 'date_format:Y-m-d'],
            'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
        ]);

        $branch = $this->branchAccess->restrictedBranch($request->user());
        $shifts = PosShift::query()->when($branch !== null, fn ($q) => $q->where('branch_id', $branch))
            ->with(['cashier', 'treasury', 'branch', 'approver'])
            ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
            ->when($filters['user_id'] ?? null, fn ($q, $v) => $q->where('user_id', $v))
            ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
            // Convert business timezone start/end bounds to UTC using an exclusive upper day boundary.
            ->when($filters['from_date'] ?? null, fn ($q, $v) => $q->where('opened_at', '>=',
                Carbon::parse($v, (string) config('app.business_timezone'))->startOfDay()->utc()))
            ->when($filters['to_date'] ?? null, fn ($q, $v) => $q->where('opened_at', '<',
                Carbon::parse($v, (string) config('app.business_timezone'))->startOfDay()->addDay()->utc()))
            ->orderByDesc('id')
            ->paginate($filters['per_page'] ?? 15);

        return response()->json($shifts);
    }

    /**
     * Retrieves full details and petty cash expenses of a specific shift.
     *
     * @param Request $request Incoming request
     * @param PosShift $shift Target shift model
     * @return JsonResponse Shift details response
     */
    public function show(Request $request, PosShift $shift): JsonResponse
    {
        $this->branchAccess->assertBranch($request->user()->id, $shift->branch_id);

        return response()->json([
            'data' => $shift->load(['cashier', 'treasury', 'branch', 'approver', 'expenses']),
        ]);
    }

    /**
     * Approves a closed shift, reconciling drawer variance and sweeping cash to the main safe.
     *
     * @param Request $request Approval request
     * @param PosShift $shift Shift awaiting approval
     * @return JsonResponse Approved shift response
     */
    public function approve(Request $request, PosShift $shift): JsonResponse
    {
        /** @var User $approver */
        $approver = $request->user();
        $this->branchAccess->assertBranch($approver->id, $shift->branch_id);

        $shift = $this->pos->approveShift($shift, $approver);

        return response()->json([
            'message' => 'تم اعتماد الوردية وترحيل النقدية للخزنة الرئيسية.',
            'data' => $shift->load(['cashier', 'treasury', 'branch', 'approver']),
        ]);
    }
}<?php

declare(strict_types=1);

namespace App\Http\Controllers\Api\V1\Pos;

use App\Http\Controllers\Controller;
use App\Models\Order;
use App\Models\PosHeldSale;
use App\Models\PosShift;
use App\Models\User;
use App\Services\OperationIdempotencyService;
use App\Services\PosService;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;

/**
 * POS terminal sales operations: direct checkout, cart hold/resume, returns, and item exchanges.
 */
class PosSaleController extends Controller
{
    public function __construct(private readonly PosService $pos) {}

    /**
     * Create and record a direct POS retail sale within the active shift.
     */
    public function store(Request $request): JsonResponse
    {
        $data = $request->validate([
            'items' => ['required', 'array', 'min:1', 'max:100'],
            'items.*.product_variant_id' => ['required', 'integer', 'min:1'],
            'items.*.qty' => ['required', 'integer', 'min:1', 'max:9999'],
            'items.*.unit_price' => ['nullable', 'numeric', 'min:0'],
            'items.*.discount_amount' => ['nullable', 'numeric', 'min:0'],
            'customer_id' => ['nullable', 'integer', 'min:1'],
            'payment_method' => ['nullable', 'string', 'in:cash,card,mixed'],
            'cash_amount' => ['nullable', 'numeric', 'min:0'],
            'card_amount' => ['nullable', 'numeric', 'min:0'],
            'override_price' => ['nullable', 'boolean'],
            'notes' => ['nullable', 'string', 'max:500'],
        ]);

        /** @var PosShift $shift */
        $shift = $request->attributes->get('pos_shift');

        // Authorize manual unit price overrides via pos.override_price permission.
        if (! empty($data['override_price'])) {
            $user = $request->user('staff');
            if (! $user->can('pos.override_price')) {
                return response()->json(['message' => 'لا تملك صلاحية تجاوز سعر البيع.'], 403);
            }
        }

        $order = app(OperationIdempotencyService::class)->run(
            'pos_sale', $request->user('staff'), $this->requiredIdempotencyKey($request),
            ['shift_id' => $shift->id, ...$data], fn () => $this->pos->createSale($shift, $data),
        );

        return response()->json([
            'message' => 'تم تسجيل البيع بنجاح.',
            'data' => $this->formatOrder($order),
        ], 201);
    }

    /**
     * Temporarily hold an uncompleted sale for later retrieval.
     */
    public function hold(Request $request): JsonResponse
    {
        $data = $request->validate([
            'items' => ['required', 'array', 'min:1'],
            'items.*.product_variant_id' => ['required', 'integer', 'min:1'],
            'items.*.qty' => ['required', 'integer', 'min:1'],
            'items.*.unit_price' => ['nullable', 'numeric', 'min:0'],
            'items.*.discount_amount' => ['nullable', 'numeric', 'min:0'],
            'customer_id' => ['nullable', 'integer', 'min:1'],
            'notes' => ['nullable', 'string', 'max:500'],
        ]);

        /** @var PosShift $shift */
        $shift = $request->attributes->get('pos_shift');

        $held = $this->pos->holdSale($shift, $data);

        return response()->json([
            'message' => 'تم تعليق الفاتورة بنجاح.',
            'hold_reference' => $held->hold_reference,
            'data' => $held->only(['id', 'hold_reference', 'items_payload', 'notes', 'created_at']),
        ], 201);
    }

    /**
     * List all held sales currently pending in the cashier's branch.
     */
    public function held(Request $request): JsonResponse
    {
        /** @var User $user */
        $user = $request->user('staff');
        $held = PosHeldSale::query()
            ->where('branch_id', $user->branch_id)
            ->with(['customer'])
            ->orderByDesc('created_at')
            ->get();

        return response()->json(['data' => $held]);
    }

    /**
     * Process item return against an existing POS sale order.
     */
    public function processReturn(Request $request, Order $sale): JsonResponse
    {
        $data = $request->validate([
            'items' => ['required', 'array', 'min:1'],
            'items.*.product_variant_id' => ['required', 'integer', 'min:1'],
            'items.*.qty' => ['required', 'integer', 'min:1'],
            'items.*.return_to' => ['nullable', 'string', 'in:on_hand,damaged'],
        ]);

        /** @var PosShift $shift */
        $shift = $request->attributes->get('pos_shift');

        $sale->load('items');

        $result = $this->pos->processReturn($shift, $sale, $data['items']);

        return response()->json([
            'message' => 'تم تسجيل المرتجع بنجاح.',
            'data' => $result,
        ]);
    }

    /**
     * Process exchange: atomically return items and create new replacement sale order.
     */
    public function processExchange(Request $request, Order $sale): JsonResponse
    {
        $data = $request->validate([
            'returned_items' => ['required', 'array', 'min:1'],
            'returned_items.*.product_variant_id' => ['required', 'integer', 'min:1'],
            'returned_items.*.qty' => ['required', 'integer', 'min:1'],
            'returned_items.*.return_to' => ['nullable', 'string', 'in:on_hand,damaged'],
            'exchange_items' => ['required', 'array', 'min:1'],
            'exchange_items.*.product_variant_id' => ['required', 'integer', 'min:1'],
            'exchange_items.*.qty' => ['required', 'integer', 'min:1'],
            'exchange_items.*.unit_price' => ['nullable', 'numeric', 'min:0'],
            'exchange_items.*.discount_amount' => ['nullable', 'numeric', 'min:0'],
            'cash_amount' => ['nullable', 'numeric', 'min:0'],
            'card_amount' => ['nullable', 'numeric', 'min:0'],
        ]);

        /** @var PosShift $shift */
        $shift = $request->attributes->get('pos_shift');

        $sale->load('items');

        // Atomically process return and replacement sale order in a single transaction.
        $exchangePayload = [
            'items' => $data['exchange_items'],
            'customer_id' => $sale->customer_id,
        ];
        if (array_key_exists('cash_amount', $data)) {
            $exchangePayload['cash_amount'] = $data['cash_amount'];
        }
        if (array_key_exists('card_amount', $data)) {
            $exchangePayload['card_amount'] = $data['card_amount'];
        }
        $result = DB::transaction(function () use ($shift, $sale, $data, $exchangePayload): array {
            $result = $this->pos->processReturn($shift, $sale, $data['returned_items']);
            $exchangeOrder = $this->pos->createSale($shift, $exchangePayload);
            $result['exchange_order_id'] = $exchangeOrder->id;

            return $result;
        }, 3);

        return response()->json([
            'message' => 'تم تسجيل الاستبدال بنجاح.',
            'data' => $result,
        ]);
    }

    // ===================================================================
    //  Helper
    // ===================================================================

    /**
     * Formats order and line items for POS receipt printer and client payload.
     *
     * @param  Order  $order  Target order model
     * @return array<string, mixed> Formatted POS order data
     */
    private function formatOrder(Order $order): array
    {
        return [
            'id' => $order->id,
            'order_number' => $order->order_number,
            'channel' => $order->channel,
            'status' => $order->status->value,
            'grand_total' => $order->grand_total,
            'cash_amount' => $order->cash_amount,
            'card_amount' => $order->card_amount,
            'customer' => $order->relationLoaded('customer') ? [
                'id' => $order->customer?->id,
                'name' => $order->customer?->name,
            ] : null,
            'items' => $order->relationLoaded('items') ? $order->items->map(fn ($i) => [
                'product_variant_id' => $i->product_variant_id,
                'sku' => $i->relationLoaded('variant') ? $i->variant?->sku : null,
                'qty' => $i->qty,
                'unit_price' => $i->unit_price,
                'discount_amount' => $i->discount_amount,
                'line_total' => $i->line_total,
            ])->all() : [],
        ];
    }
}<?php

declare(strict_types=1);

namespace App\Models;

use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * Current inventory balance per variant, branch, and location.
 * Direct mutation is prohibited; all updates occur exclusively via InventoryService::recordMovement.
 */
class StockLevel extends Model
{
    protected $fillable = [
        'product_variant_id', 'branch_id', 'location_id',
        'reorder_level',
    ];

    protected $casts = [
        'on_hand' => 'decimal:4',
        'reserved' => 'decimal:4',
        'damaged' => 'decimal:4',
        'in_transit' => 'decimal:4',
        'reorder_level' => 'decimal:4',
        'available' => 'decimal:4',
    ];

    /** Sellable available inventory = on_hand - reserved - damaged (mirrors database generated column). */
    public function getAvailableAttribute(): float
    {
        return round((float) $this->on_hand - (float) $this->reserved - (float) $this->damaged, 4);
    }

    /**
     * Scope query to rows with non-zero balance across on_hand, reserved, damaged, or in_transit.
     *
     * @param  Builder<StockLevel>  $query
     * @return Builder<StockLevel>
     */
    public function scopeHasNonZeroBalance(Builder $query): Builder
    {
        return $query->where(fn (Builder $q) => $q
            ->where('on_hand', '<>', 0)
            ->orWhere('reserved', '<>', 0)
            ->orWhere('damaged', '<>', 0)
            ->orWhere('in_transit', '<>', 0));
    }

    /**
     * Filters rows currently in an alert state — mirrors the two
     * StockLowDetected triggers in InventoryService::recordMovement:
     * a set row threshold compares against the row, while an unset row
     * threshold falls back to the variant threshold compared against the
     * branch-wide total (not the single row).
     *
     * @param  Builder<StockLevel>  $query
     * @return Builder<StockLevel>
     */
    public function scopeWhereLowStock(Builder $query): Builder
    {
        return $query
            ->join('product_variants as pv_low', 'pv_low.id', '=', 'stock_levels.product_variant_id')
            ->leftJoinSub(
                self::query()->selectRaw('branch_id, product_variant_id, COALESCE(SUM(on_hand - reserved - damaged), 0) AS branch_available')
                    ->groupBy('branch_id', 'product_variant_id'),
                'branch_totals',
                fn ($join) => $join
                    ->on('branch_totals.branch_id', '=', 'stock_levels.branch_id')
                    ->on('branch_totals.product_variant_id', '=', 'stock_levels.product_variant_id')
            )
            ->where(fn (Builder $q) => $q
                ->where(fn (Builder $row) => $row
                    ->where('stock_levels.reorder_level', '>', 0)
                    ->whereRaw('stock_levels.available <= stock_levels.reorder_level'))
                ->orWhere(fn (Builder $variant) => $variant
                    ->whereRaw('COALESCE(stock_levels.reorder_level, 0) = 0')
                    ->where('pv_low.reorder_level', '>', 0)
                    ->whereRaw('COALESCE(branch_totals.branch_available, 0) <= pv_low.reorder_level')))
            ->select('stock_levels.*');
    }

    public function variant(): BelongsTo
    {
        return $this->belongsTo(ProductVariant::class, 'product_variant_id')->withTrashed();
    }

    public function branch(): BelongsTo
    {
        return $this->belongsTo(Branch::class);
    }

    public function location(): BelongsTo
    {
        return $this->belongsTo(Location::class);
    }
}<?php

