  transfer: { draft: ['مسودة', 'b-neutral'], approved: ['معتمد', 'b-info'], shipped: ['مشحون', 'b-warn'], received: ['مستلم', 'b-ok'], cancelled: ['ملغي', 'b-bad'] },
  dealer: { active: ['نشط', 'b-ok'], pending: ['بانتظار الاعتماد', 'b-warn'], suspended: ['موقوف', 'b-bad'] },
